INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178775, 'ظ', '<span class=\"hlight\">ظ.</span> (حرف ) نشانه ٔ حرف هفدهم است از الفبای عرب و نام آن ظاء است و ظی و در حساب جُمَّل آن را به نهصد دارند و در حساب ترتیبی فارسی نماینده ٔ عدد بیست است و آن یکی از دو حرف مختص به عرب است که یکی همین ظ و دیگری ض است و از حروف مصمته و مطبقه و از حروف هفتگانه ٔ مستعلیه و از حروف روادف و از حروف لَثَوی و از حروف مائی (آبی ) و از حروف مکسوره و متعلق به قمر است و رمز است از ظاهر: و هو ظ؛ و هو ظاهر. و صاحب تاج العروس گوید که لیث روایت کرد از خلیل که او گفته است ظاء حرفی است عربی و مختص است به زبان عرب و هیچیک از امم دیگر در این حرف با عرب انبازی ندارند و آن از حروف مجهوره است و ظاء و ذال و ثاء در حیز واحدند و این سه حرف را حروف لثویه گویند، چه مبداء آنها از لثه باشد و ظاء حرف هجایی است اصلی نه بدل و نه زائد. و ابن جنی گوید در کلام نبط نیز حرف ظاء نیامده است و اگر کلمه ای دارای حرف ظاء بدان زبان درآید ظاء را بدل به طاء کنند چنانکه ما در ترجمه ٔ ظوی خواهیم آورد ان شأاﷲ تعالی . و شیخ ما گفت که ام ّقاسم و جماعتی یاد کرده اند که در ابدال این حرف چیزی نیافته اند و صاحب تسهیل نیز با اینکه بسیاری از غرائب را گرد آورده در این معنی سکوت کرده است . و همچنین در کتاب الممتع با آنکه آن کتاب جامع غرائب فن است دراین موضوع چیزی نیست، سپس در المقرب ابن عصفور دیدم که گوید ظاء به ذال معجمه بدل شود چنانکه گوئی : ترکته وقیذاً و وقیظاً و این جمله را یعقوب بن سکیت نقل کرده است - انتهی قول الشیخ . و من (یعنی صاحب تاج العروس ) گویم این معنی از کراع نیز نقل شده است چنانکه بیاید و همچنین ارض جلذاء و جلظاء (چنانکه در نوادر الاعراب آمده است ) - انتهی کلام صاحب تاج العروس . و ماعلاوه بر آنچه صاحب تاج العروس در ابدال ظاء آورده است گوئیم که ظ به ض نیز بدل شود چنانکه بهض و بهظ.<br /></font></div>'),
(178776, 'ظاب', '<span class=\"hlight\">ظاب .</span> (ع اِ) رجوع به ظأب شود.<br /></font></div>'),
(178777, 'ظاری', '<span class=\"hlight\">ظاری .</span> (ع ص ) گزنده . عاض .<br /></font></div>'),
(178778, 'ظاطریة', '<span class=\"hlight\">ظاطریة.</span> <font color=\"DarkGreen\"><b>[ طِ ری ی َ ]</font></b> (اِخ ) محلی در جنوب شرقی بغداد.<br /></font></div>'),
(178779, 'ظاعن', '<span class=\"hlight\">ظاعن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) رونده . کوچ کننده . مسافر. راهی .<br /></font></div>'),
(178780, 'ظاعنة', '<span class=\"hlight\">ظاعنة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ن َ ]</font></b> (ع ص ) تأنیث ظاعن .<br /></font></div>'),
(178781, 'ظاعنة', '<span class=\"hlight\">ظاعنة.</span> <font color=\"DarkGreen\"><b>[ع ِ ن َ ]</font></b> (اِخ ) ابن مُرّ. پدر قبیله ای است از عرب .<br /></font></div>'),
(178782, 'ظاغیة', '<span class=\"hlight\">ظاغیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) دایه . حاضنه . آنکه در تیمار و تعهد بچه باشد.<br /></font></div>'),
(178783, 'ظاف', '<span class=\"hlight\">ظاف .</span> (ع اِ) ظؤف . موی گردن . <BR><font color=\"Blue\">◄</font> پوست گردن .<br /></font></div>'),
(178784, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) ابن جعفربن ابی القاسم السلمی، مکنی به ابوعامر دمشقی . او از مکی بن علان و اسماعیل عراقی و محمدبن ابی القاسم قزوینی و دیگران استماع حدیث کرد. ذهبی در معجم گوید: وفات وی به سال <span class=\"hlight\" dir=\"rtl\">٧٠٢</span> هَ . ق . بود. و برخی ولادت وی را در <span class=\"hlight\" dir=\"rtl\">٧١٥</span> گفته اند. (الدّرر الکامنه چ حیدرآباد ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>).<br /></font></div>'),
(178785, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) ابن القاسم بن منصوربن عبداﷲبن خلف بن عبدالغنی الجذامی، مکنی به ابی منصور و معروف به حداد. موطن وی اسکندریه . او شاعری ادیب و نیکوسخن بود. و وی راست دیوانی مشتمل بر مدح گروهی از مصریان . وفات به محرم سال <span class=\"hlight\" dir=\"rtl\">٥٢٩</span> هَ . ق . به مصر. جماعتی از اعیان و از جمله حافظ ابوطاهر سلفی از وی روایت کرده اند. و از اوست :<br />حکم العیون علی القلوب یجوز<br />و دواؤها من دائهن عزیز<br />کم نظرة نالت بطرف ذابل <br />ما لاینال الذابل المهزوز<br />فحذار من تلک اللواحظ غیرة<br />فالسحر بین جفونها مکنوز.<br />هنگامی که ظافر از مصر به مهدیه رفت قطعه ٔذیل را به ابی الصلت امیةبن عبدالعزیز اندلسی نوشت وبه وی اظهار شوق کرد:<br />الا هل لدائی من فراقک افراق <br />هو السم لکن لی لقاؤک دریاق <br />فیا شمس فضل غربت و لضوئها<br />علی کل قطر بالمشارق اشراق <br />سقی العهد عهداً منک عمر عهده <br />بقلبی عهداً لایضیع و میثاق <br />یجدّده ذکر یطیب کما شدَت <br />و ریقاء کنتهامن الایک اوراق <br />لک الخلق الجذل الرفیع طرازه <br />و اکثر اخلاق الخلیقة اخلاق <br />لقد ضائلتنی یا اباالصلت مذ نأت <br />دیارک عن داری هموم و اشواق <br />اذا عزنی اطفاؤها بمدامعی <br />جرت و لها مابین جفنی ّ احراق <br />سحائب یحدوها زفیر یجره <br />خلال التراقی و الترائب تشهاق <br />و قد کان لی کنز من الصبر واسع<br />و لی منه فی صعب النوائب انفاق <br />و سیف اذا جردت بعض غراره <br />لجیش خطوب صدها منه ارهاق <br />الی ان ابان البین ان ّ غراره <br />غرور و ان الکنز فقر و املاق <br />اخی سیدی مولای دعوة من صفا<br />و لیس له من رق ودّک اعتاق <br />لئن بعدت مابیننا شقة النوی <br />و مطرد طامی الغوارب خفاق <br />و بید اذا کلفتها العیس قصرت <br />طلائح انضاها زحیل و اعناق <br />فعندی لک الودّ الملازم مثل ما<br />یلازم اعناق الحمائم اطواق .<br />واز غرر قصائد اوست :<br />لو کان بالصبر الجمیل ملاذه <br />ماسح وابل دمعه و رذاذه <br />مازال جیش الحب یغزو قلبه <br />حتی وهی و تقطعت افلاذه <br />لم یبق فیه من الغرام بقیة<br />الا رسیس یحتویه جذاذه <br />من کان یرغب فی السلامة فلیکن <br />ابداً من الحدق المراض عیاذه <br />لاتخدعنک بالفتور فانه <br />نظر یضرّ بقلبک استلذاذه <br />یا ایها الرشاء الذی من طرفه <br />سهم الی حب القلوب نفاذه <br />درّ یلوح بفیک من نظامه <br />خمر به قد جال من نباذه <br />و قناة ذاک القد کیف تقومت <br />و سنان ذاک اللّحظ ما فولاذه <br />هاروت یعجز عن مواقع سحره <br />و هو الامام فمن تُری استاذه <br />تاﷲ ماعلقت محاسنک امرءً<br />الا و عَز علی الوری استنقاذه <br />اغریت حبک بالقلوب فاذعنت <br />طوعاً و قد اودی بها استحواذه .<br />و نیز از اوست در وصف اقحوان :<br />انظر فقد ابدی الاقاحی مبسما<br />یغترّ ضحکاً فوق قدّ املد<br />کفصوص دُرّ لطفت اجرامه <br />و تنظمت من حول شمسة عسجد.<br />رجوع به معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>-<span class=\"hlight\" dir=\"rtl\">٢٨٠</span> و الاعلام زرکلی چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> و عیون الانباء چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و وفیات الاعیان چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> و قاموس الاعلام شود.<br /></font></div>'),
(178786, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) ابن محمدبن صالح بن ثابت الانصاری العدوی . وی مردی تهیدست و نیکوکار بود و نظمی نیکو داشت و شیخ ابوحیان از وی اخذ روایت کرده است . از اوست :<br />تمیس فتخجل الاغصان منها<br />و تزری فی التلفت بالغزال <br />و تحسب بالازار لقد تغطت <br />و قد ابدت به کل الجمال <br />سلوها لم تغطی البدر تیها<br />و تسمح للنواظر بالهلال <br />و لم تصلی الحشا بالعتب نارا<br />و فی الفاظها برد الزلال .<br />رجوع به الدّرر الکامنة چ حیدرآباد ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span> شود.<br /></font></div>'),
(178787, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) اسماعیل بن الحافظبن محمدبن المستنصربن الظاهربن الحاکم بن العزیزبن المعزبن المنصوربن القائم بن المهدی العبیدی، مکنی به ابی المنصور. مولد او به قاهره روز یکشنبه نیمه ٔ ربیعالاول <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> هَ . ق . به روز وفات الحافظ. بر حسب وصیت حافظ با پسر وی الظافر بیعت کردند و او به سال از همه ٔ فرزندان پدر کوچکتر و پیوسته به نشاط و لعب و لهو سرگرم بود و جز به معاشرت کنیزکان و استماع اغانی به هیچ نمی پرداخت و با نصر پسر عباس وزیر خویش مأنوس بود و نصر و ظافر هر دو در غایت حسن و جمال بودند و عباس به پسر خویش میگفت که تو با این مؤانست ظافر نام خویش تباه کردی و مردمان در حق شما چیزهاگویند و او شبی ظافر را چنانکه کس ندانست پنهانی به خانه ٔ پدر خواند و بدانجا به نیمه ٔ محرم <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> و به قولی پنجشنبه ٔ سلخ محرم همان سال بکشت و ابن خلکان گوید: «خانه ای که ظافر در آن کشته شد امروز مدرسه ٔ حنفیه ٔ معروف به سیوفیة است ». و مرگ او مخفی کرد و تنها به پدر خویش عباس بگفت و گویند عباس او را به کشتن ظافر امر کرده بود و صباح آن شب عباس برنشست و به باب قصر آمد و نمود که برای شغلی مهم دیدار ظافر میخواهد و چاکران مواضعی را که عادتاً ظافر در آن جای ها بیتوته می کرد بازجستند و او را نیافتند و عباس پیاده شد و با کسان خویش به قصر درآمد و به خادمان گفت دو برادر مولای ما را بیرون آرید تا از ایشان پرسیم و جبریل و یوسف دو پسر حافظ را بیاوردند و او پرسید امیر به کجاست، ایشان گفتند از پسر خویش پرس، چه او از مابهتر داند. عبداﷲ امر کرد تا گردن هر دو بزدند و گفت قاتل ظافر هم این دو برادر باشند. و رجوع به ترجمه ٔ عیسی بن الظافر ملقب به الفائز و رجوع به ابن خلکان چ فرهادمیرزا ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> و طبقات سلاطین اسلام چ اقبال ص <span class=\"hlight\" dir=\"rtl\">٦١</span> وعیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span> و<span class=\"hlight\" dir=\"rtl\">١١٠</span> و قاموس الاعلام ترکی شود.<br /></font></div>'),
(178788, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) اسماعیل بن عبدالرحمن بن اسماعیل بن عامربن مطرف بن ذی النون امیر طلیطله . مولد وی به اوائل قرن پنجم هجری است . ابن بغونش و دانشمندان دیگری از معاصرین او از وی فوائد جمه گرفته اند. رجوع به عیون الانباء چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨</span> و قاموس الاعلام شود.<br /></font></div>'),
(178789, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) صلاح الدین عامر الاول ابن طاهر، از بنی طاهر، جانشینان رسولیان یمن . وفات <span class=\"hlight\" dir=\"rtl\">٨٧٠</span> هَ . ق . رجوع به طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">٩١</span> شود.<br /></font></div>'),
(178790, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) صلاح الدین عامر الظافر الثانی، از بنی طاهر، جانشینان رسولیان یمن . وی از <span class=\"hlight\" dir=\"rtl\">٨٩٤</span> تا <span class=\"hlight\" dir=\"rtl\">٩٢٣</span> هَ . ق . حکم راند. در <span class=\"hlight\" dir=\"rtl\">٩٢٣</span> سلسله ٔ بنی طاهر به دست ممالیک و ترکان عثمانی برافتاد. رجوع به طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">٩١</span> شود. در قاموس الاعلام ترکی آمده است که : ظافر (ملک ... عمرو) امیر سرزمین یمن بود و در زمان سلطان سلیم و سلیمان مدتی با عساکر عثمانی جنگ کرد و به دست سنان پاشا فاتح یمن مغلوب شد. (قاموس الاعلام ).<br /></font></div>'),
(178791, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ )(الَ ...) محمدبن اسماعیل قاضی اشبیلیه . رجوع به ابوالقاسم محمد المعتمدعلی اﷲبن ابی عمرو عباد... شود.<br /></font></div>'),
(178792, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) ابن جابربن منصور السکری، مکنّی به ابوحکیم . او مسلمانی دین دار و عالم به صناعت طب و یکی از بزرگترین متمیزین این علم و در علوم حکمیه متقن و آراسته ٔ به فضائل و علم و ادب و دوستدار اشتغال و تضلع به علوم بود. وی در بغداد درک صحبت ابوالفرج بن الطیب کرد و با او به کار علم پرداخت . ظافر مانند پدر خویش عمری طویل یافت و تا سال <span class=\"hlight\" dir=\"rtl\">٤٨٢</span> هَ .ق . حیات داشت . اصل او از موصل است و از موصل به حلب شد و تا پایان عمر بدانجا اقامت گزید و پس از وی جماعتی در حلب به صناعت طب پرداختند. از اشعار اوست :<br />مازلت اعلم اولاً فی اوّل <br />حتی علمت بأننی لا علم لی <br />و من العجائب ان کونی جاهلاً<br />من حیث کونی اننی لم اجهل .<br />ظافربن جابر را مقالتی است در اینکه : «الحیوان یموت مع ان ّ الغذاء یخلف عوض ما یتحلل منه ». رجوع به عیون الانباء چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">١٤٣</span>-<span class=\"hlight\" dir=\"rtl\">١٤٤</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٤٥٣</span>-<span class=\"hlight\" dir=\"rtl\">٤٥٤</span> و قاموس الاعلام ترکی و تاریخ حلب چ حلب ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٢</span> شود.<br /></font></div>'),
(178793, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) ابن تمیم . رجوع به عیون الانباء چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span> شود.<br /></font></div>'),
(178794, 'ظافر', '<span class=\"hlight\">ظافر.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) نعت فاعلی از ظفر. ظفریابنده . فیروزی یابنده . فیروز.<br /></font></div>'),
(178795, 'ظاقور', '<span class=\"hlight\">ظاقور.</span> <font color=\"DarkGreen\"><b>[ ظاق ْ وَ ]</font></b> (اِ) لقلق . لکلک <span class=\"hlight\">:</span> <br />گر ندانی ز ظاقور بلبل <br />بنگرش گاه نغمه و غلغل .<br /> <font color=\"Red\">منوچهری (از حاشیه ٔ فرهنگ اسدی نخجوانی ).</font><br />این کلمه با ظاء مؤلف و قاف در فارسی عجیب است خاصه که دیگر فرهنگها از آن بیخبرند. در نسخه ای در کمال روشنی به همین صورت نوشته شده . برای معنی لکلک و لقلق، کلمات فالرغُس و فالرغوس و بلارج هم در فرهنگها ضبط شده، ولی ظاقور نمیتواند در این بیت تصحیف هیچیک باشد، واﷲ اعلم . در فرهنگ اسدی چاپی این کلمه را زاغور یعنی بازاء و غین نوشته اند و ظاهراً صحیح هم همان است .<br /></font></div>'),
(178796, 'ظالع', '<span class=\"hlight\">ظالع.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) نعت فاعلی از ظلع. ستور خمیده و لنگ . <BR><font color=\"Blue\">◄</font> مرد مائل از حق و جز آن . <BR><font color=\"Blue\">◄</font> مرد گنهکار و تهمت زده . مذکر و مؤنث در وی یکسان است . <BR><font color=\"Blue\">◄</font> سگ لنگ . <BR><font color=\"Blue\">◄</font> سگی که در شب خواب نکند. <BR><font color=\"Blue\">◄</font> سگ ماده ٔ آزمند نر که سگان درپی او افتاده و نگذارند که خواب کند. سگ گشنخواه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">لاانام حتی ینام ظالع الکلاب </span> ؛ این مثل را درباره ٔ مردی گویند که از امور خود غافل نشود.<br /></font></div>'),
(178797, 'ظالم', '<span class=\"hlight\">ظالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) نعت فاعلی از ظلم . کسی که چیزی را در غیر موضع خود نهد. بیداد. بیدادگر. ستمگر. ستمکار. جافی . جابر. متعدی . مردم آزار. جفاکار. غاشم . غشوم . قاسط. ظلم کننده <span class=\"hlight\">:</span> <br />هیچ نیاید که رنج بیند یک روز<br />ظالم در روزگار خویش و نه غافل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با آنچه ملک عادل انوشیروان کسری بن قباد را سعادت ذات ... و قمع ظالمان ... حاصل است ... می بینم که کارهای زمانه میل به ادبار دارد. (کلیله و دمنه ). اقوال پسندیده مدروس گشته ... و مظلوم محق ذلیل و ظالم مبطل عزیز. (کلیله و دمنه ). زن گفت ای ظالم متهور برخیز. (کلیله و دمنه ).<br />سخن که جز به مدیح تونظم داده شود<br />سخنسرای بود ظالم و سخن مظلوم .<br /> <font color=\"Red\">سوزنی .</font><br />ظالم که کباب از دل درویش خورد<br />چون درنگری ز پهلوی خویش خورد.<br /> <font color=\"Red\">محیی الدین یحیی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظالم دست کوتاه </span> ؛ تعبیری است مثلی، آنکه با وجودضعیف بودن ستمکار یا مایل به ستم کردن است .<br /><BR><font color=\"Blue\">◄</font> نعت از ظَلم . درخشان . آبدار (دندان ). <BR><font color=\"Blue\">◄</font> کسی که شیر را قبل از گرفتن سرشیر بنوشد. ج، ظالمون، ظالمین، ظُلَّم، ظَلَمة. <BR><font color=\"Blue\">◄</font> (اِ) نوعی از گیاه که شاخ تر و نرم دارد. عشبی است که آن را شاخهای طولانی باشد. <BR><font color=\"Blue\">◄</font> صوف را نیز گویند.<br /></font></div>'),
(178798, 'ظالم', '<span class=\"hlight\">ظالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) جدّ ابن میاده ابوشرحبیل رماح بن ابرد از شعراء مخضرمی است . رجوع به الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span> شود.<br /></font></div>'),
(178799, 'ظالم', '<span class=\"hlight\">ظالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن دُنیر. نام پدر ماریه مادر عبداﷲ و مجاشع و سدوس پسران دارم بن مالک بن حنظله است .<br /></font></div>'),
(178800, 'ظالم', '<span class=\"hlight\">ظالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن سراق یا مراق یا سارق بن ابی صفرة، یا مراق بن صبح کندی بالولاء، مکنی به ابی صفرة. یکی از تابعین که مهالبه به وی منسوبند . رجوع به تاج العروس ومنتهی الارب (ماده ٔ ص ف ر) و ترجمه ٔ قاموس ترکی شود.<br /></font></div>'),
(178801, 'ظالم', '<span class=\"hlight\">ظالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن محمد رحمه اﷲ. یکی از بزرگان مشایخ . نام او عبداﷲ لیکن <font color=\"DarkGreen\"><b>[ نام ]</font></b> خود را ظالم کرده بود، گفتی هرگز از من بندگی حق نیاید پس من ظالم باشم . و وی از اصحاب ابوجعفر حداد بود، و او گفته است : هرکه خواهد که راه وی گشاده شود سه کار را ملازمت باید کرد: آرام گرفتن با ذکر حق و از خلق گریختن و کم خوردن . رجوع به نفحات الانس جامی چ هند ص <span class=\"hlight\" dir=\"rtl\">٤٠</span> شود.<br /></font></div>'),
(178802, 'ظالم', '<span class=\"hlight\">ظالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن مکتوم کلابی انباری، مکنی به ابوزکریا. ابوالقاسم بن الثلاج حدیث کرد از احمدبن محمدبن مسروق الطوسی و او از ظالم بن مکتوم که وی مردی حداد بوده و در انبار سماع حدیث کرده است . رجوع به تاریخ بغداد چ مصر ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٩</span> شود.<br /></font></div>'),
(178803, 'ظالمانه', '<span class=\"hlight\">ظالمانه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) ستمگرانه . بیدادگرانه .<br /></font></div>'),
(178804, 'ظالمة', '<span class=\"hlight\">ظالمة.</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ]</font></b> (ع ص ) تأنیث ظالم .<br /></font></div>'),
(178805, 'ظالمة', '<span class=\"hlight\">ظالمة.</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ]</font></b> (اِخ ) نام زنی از هذیل . رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠</span> و <span class=\"hlight\" dir=\"rtl\">١١</span> شود.<br /></font></div>'),
(178806, 'ظالمون', '<span class=\"hlight\">ظالمون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) ج ِ ظالم .<br /></font></div>'),
(178807, 'ظالمی', '<span class=\"hlight\">ظالمی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) (کوه ...) نام کوهی به فارس . بلوک اسیر و بلوک گله دار در جانب جنوب این کوه و بلوک علامرودشت در جانب شمال آن واقع است .<br /></font></div>'),
(178808, 'ظالمین', '<span class=\"hlight\">ظالمین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) ج ِ ظالم .<br /></font></div>'),
(178809, 'ظام', '<span class=\"hlight\">ظام .</span> (ع اِ) آواز و غوغا. رجوع به ظأب شود.<br /></font></div>'),
(178810, 'ظامیة', '<span class=\"hlight\">ظامیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) نعت فاعلی از ظمی ٔ. شفة ظامیة؛ لبی هواسیده . (مهذب الاسماء)؛ لبی پژمرده .<br /></font></div>'),
(178811, 'ظان', '<span class=\"hlight\">ظان .</span> <font color=\"DarkGreen\"><b>[ ظان ن ]</font></b> (ع ص ) مرد بدگمان . <BR><font color=\"Blue\">◄</font> تهمت نهنده . گمان برنده .<br /></font></div>'),
(178812, 'ظانة', '<span class=\"hlight\">ظانة.</span> <font color=\"DarkGreen\"><b>[ ظان ْ ن َ ]</font></b> (ع ص ) تأنیث ِ ظان ّ.<br /></font></div>'),
(178813, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عمربن ابی زیدان (<span class=\"hlight\" dir=\"rtl\">١١٠٦</span> - <span class=\"hlight\" dir=\"rtl\">١١٩٦</span> هَ . ق .). مردی زیرک و شجاع بود. اصل وی از مدینه است و یکی از نیاکان او به فلسطین مهاجرت کرد و آنجا توطن گزید. پدرظاهر در روزگار ولایت امیر بشیر شهابی بر لبنان، حاکم صفد و توابع آن بود و پس از او پسرش ظاهر به حکومت صفد نشست . سلیمان پاشا والی دمشق در سال <span class=\"hlight\" dir=\"rtl\">١١٥٠</span> هَ . ق . به مقاتله ٔ وی برخاست و ظاهر در طبریه متحصن شد و چون سلیمان پاشا دفعةً وفات یافت و یا به قولی مسموم گشت، در کار ظاهر گشایشی پیدا آمد و بر عکه و ناصریه و طبریه دست یافت . و عثمان پاشا والی دمشق به سرکوبی وی مأمور شد ولی سپاهیان ظاهر او را منهزم ساختند و ولایات صیدا و عکه و حیفا و یافا و رمله و جبل نابلس و نواحی مشرق اردن و صفد و جبل عامل زیر فرمان او درآمد و حکومت عثمانی در ساحل حیفا نیز اضطراراً او را به حکومت آن نواحی بشناخت و پس از این وقایع مردی به نام ابوالذهب که از سران لشکر مصر بود بر وی خروج کرد و حکومت را از چنگ او بیرون کرد و کار ظاهر به خواری کشید. اما چون ابوالذهب ناگهانی در صیداء به سال <span class=\"hlight\" dir=\"rtl\">١١٨٨</span> بمرد، ظاهر بار دیگر ولایات وسیعه ٔ خود را تحت سلطه ٔ خویش درآورد و همچنان بر حکومت باقی بود تاآنگاه که دولت عثمانی دسته ای از کشتی ها برای فتح عکه مجهز کرد و ظاهر که سرگرم تهیه ٔ وسائل مقاومت بود گرفتار تزویر و خیانت یکی از سرداران مغربی خویش گردید و کشته شد. (الاعلام زرکلی چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٤٥٤</span>-<span class=\"hlight\" dir=\"rtl\">٤٥٥</span>).<br /></font></div>'),
(178814, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (الملک الَ ...) نوزدهمین سلطان ممالیک برجی . در <span class=\"hlight\" dir=\"rtl\">٩٠٤</span> هَ . ق . پس از ملک ناصر ابوالسعادات محمدبن قایت بیگ اشرف، به کوشش خواهر خویش به حکومت رسید، ولی حکومت وی تا اواخر سال <span class=\"hlight\" dir=\"rtl\">٩٠٥</span> بیش نپائید و پس از وی حکمداری به جنبلات اشرف رسید. رجوع به قاموس الاعلام ترکی و طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">٧٥</span> شود.<br /></font></div>'),
(178815, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن ابی منصور الحاکم، مکنی به ابوالحسن و ملقب به الظاهر لاعزاز دین اﷲ. هفتمین خلیفه ٔ فاطمی . او در <span class=\"hlight\" dir=\"rtl\">٢٧</span> شوال <span class=\"hlight\" dir=\"rtl\">٤١١</span> هَ . ق . به جای پدر به خلافت نشست و در نیمه ٔ شعبان <span class=\"hlight\" dir=\"rtl\">٤٢٧</span> پس از پانزده سال و نه ماه و هفده روز خلافت درگذشت . مدت عمر وی سی وسه سال بود. و او مردی نیکوسیرت و سائس و نسبت به رعیت منصف و خوشگذران بود و کارها بر وزیر ابی القاسم علی بن احمد الجرجرائی میرفت، چه ظاهر مقام کفایت وامانت وی دانسته بود. پس از ظاهر پسر او المستنصر باﷲ به خلافت نشست . (الکامل ابن اثیر چ مصر ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>).<br /></font></div>'),
(178816, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص )نعت فاعلی از ظهور. آشکار. پدیدار. هویدا. معلوم . واضح . روشن . عیان . باهر. مرئی . پدیدآینده . نمودار. بیان کننده . پدید. زمم <span class=\"hlight\">:</span> این قاضی شغلها و سفارتهای بانام کرده و در هریک از آن مناصحت و دیانت وی ظاهر گشته . (تاریخ بیهقی ). ما آن نصیحت قبول کردیم و خاتمت آن بر این جمله است که ظاهر است . (تاریخ بیهقی ). چون کار مرد از حد بگذشت و خیانتهای بزرگ وی مارا ظاهر گشت فرمودیم تا دست وی از شغل عرض کوتاه کردند. (تاریخ بیهقی ). این نامه ها نبشته آمد و معتمد دیوان وزارت رفت و سکونی ظاهر پیدا آمد. (تاریخ بیهقی ). آفریدگار را در آنچه آفریده است مصلحتی است عام وظاهر. (تاریخ بیهقی ). دلیل روشن و ظاهر است که از این پادشاه بزرگ سلطان ابراهیم آثار محمودی خواهند دید. (تاریخ بیهقی ). عالمی را شورانیدن از بهر یک تن کز وی خیانتی ظاهر گشت محال است . (تاریخ بیهقی ). امیرک را سلطان قوی دل کرد که شغلی بزرگتر فرمائیم ترا و از تو ما را خیانتی ظاهر نشده است . (تاریخ بیهقی ). کار دولت ناصری و یمینی و حافظی و معینی که امروز ظاهر است ... هم بر این جمله رفته است . (تاریخ بیهقی ).<br />ببین گرت باید ببینی به ظاهر<br />از او صورت و سیرت حیدری را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />همه ٔ نقود خانه پیش چشم من ظاهر آمدی . (کلیله و دمنه ). و رسیدن آن به خواص و عوام تعذری ظاهر دارد. (کلیله و دمنه ). و به معجزات ظاهر و دلایل واضح مخصوص گردانید. (کلیله و دمنه ). تفاوت میان ملاحظت دوستان ونفرت دشمنان ظاهر است . (کلیله و دمنه ). مرد هنرمند... در میان خلق ظاهر شود. (کلیله و دمنه ). و حمداﷲ تعالی که مخایل مزید قدرت و دلایل مزیت بسطت هرچه ظاهرتر است . (کلیله و دمنه ). هیچ اشارت نبوده است که نه در آن منفعتی و از آن فایده ای ظاهر بوده است . (کلیله و دمنه ). و چنانکه ظهور آن بی ادوات آتش زدن ممکن نگردد، اثر این بی تجربت و ممارست هم ظاهر نشود. (کلیله و دمنه ). و هر بنا که بر قاعده ٔ عدل و احسان قرارگیرد... اگر از تقلب احوال در وی اثری ظاهر نگردد ودست زمانه از ساحت سعادت آن قاصر ماند بدیع ننماید.(کلیله و دمنه ). گفتم زبان مصلحت آن است که کوتاه کنی که مرا کرامت ایشان ظاهر شد. (گلستان ). <BR><font color=\"Blue\">◄</font> غیرمعما. کشف . به کشف . که رمز نباشد <span class=\"hlight\">:</span> مسعدی را بخواند و خالی کرد و من نسخت کردم تا آنچه نبشتنی بود به ظاهر و معما نبشت و گسیل کرده آمد. (تاریخ بیهقی ). صاحب برید جز بر مراد ایشان چیزی نتواندنوشت به ظاهر. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> (اِ) مقابل باطن . مقابل معنی <span class=\"hlight\">:</span> درون من در این یکی است با بیرونم و باطنم یکی است با ظاهرم . (تاریخ بیهقی ). در بیم است از قهر خدای در نهان و آشکار و ظاهر و باطن . (تاریخ بیهقی ). یا برابر نباشد ظاهر گفته ام با باطن ... لازم باد بر من زیارت خانه ٔ خدا که در میان مکه است . (تاریخ بیهقی ). حال ظاهر میان امیر محمود و امیر ابوالعباس خوارزمشاه سخت نیکو بود. (تاریخ بیهقی ). خردمند به مشاهدت ظاهر هیئت باطن را بشناسد. (کلیله و دمنه ). و ظاهر و باطن من به علم و عمل آراسته گردد. (کلیله و دمنه ). یکی از بزرگان گفت پارسائی را چه گوئی در حق فلان عابد که دیگران به طعنه در او سخنها گفته اند، گفت بر ظاهرش عیب نمی بینم و در باطنش غیب نمی دانم . (گلستان ). گفت از پیش طایفه ای در جهان بودند به صورت پراکنده و به معنی جمع، امروز خلقی اند به ظاهر جمع و به معنی پراکنده . (گلستان ). مسکین در این سخن که پادشه پسری به صید از لشکریان دور افتاده بالای سر ایستاده همی شنید و در هیأتش نظر می کرد، صورت ظاهرش پاکیزه . (گلستان ). پیغمبر مأمور به ظاهر بود. شرع به ظاهر حکم میکند. <BR><font color=\"Blue\">◄</font> برون . بیرون . میدان عقب شهر و قصبه . حوالی شهر و قصبه . خارج ِ. در بیرون ِ: فیروزآباد، نام قریه ای است به ظاهرهرات <span class=\"hlight\">:</span> به جرجان رفت و بر ظاهر شهر بر جانب مشهد داعی فروآمد. (ترجمه ٔ تاریخ یمینی ). منتصر این اشارت قبول کرد و بعد از استخارت نهضت فرمود و بر ظاهرِ ری فرودآمد. (ترجمه ٔ تاریخ یمینی ). با لشکری تمام به ظاهر بُشت نزول فرمود. (ترجمه ٔ تاریخ یمینی ).به وقت حضور من نوشته های جماعتی که از ظاهر مرو هزیمت شده بودند برسید. (ترجمه ٔ تاریخ یمینی ). او را درقبه ای که به ظاهر جرجان بر راه خراسان ساخته بودند دفن کردند. (ترجمه ٔ تاریخ یمینی ). به ظاهر استرآباد جنگی سخت کردند. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای تعالی . پیدا به هستی . مقابل نهان . <BR><font color=\"Blue\">◄</font> (ع ص ) غالب . غلبه کننده . چیره . <BR><font color=\"Blue\">◄</font> زائل : هذا امر ظاهر عنک عاره ؛ أی زائل . <BR><font color=\"Blue\">◄</font> (اِ) آنچه دیده شود از چیزی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اهل ظاهر</span> ؛ شیعه <span class=\"hlight\">:</span> جماعت جدولیان خود را اهل علم باطن نام نهادند و دیگر شیعه را اهل ظاهر. (جهانگشای جوینی ). رجوع به ظاهریه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهر آسمان </span> ؛ آنسوی آسمان که روی به آسمان دیگر دارد. (دهار).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهرالروایة</span> ؛ آنچه در مبسوط و جامع کبیر و جامع صغیر و سیر کبیر است . ظاهرالمذهب نیز همان است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهر بَشره </span> ؛ روی پوست روئین از دو پوست بدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهر بلد</span> ؛ بیرون شهر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهر قدم </span> ؛ پشت پای .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهر کردن </span> ؛ مکشوف کردن . آشکار کردن . پدید کردن . پیدا کردن . اظهار کردن . اعلان کردن . به ظهور آوردن . ارائه . ابراز. اجلاء. ادهان . بحثرة. تبریز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظاهر کف </span> ؛ پشت پنجه . پشت دست .<br /> <BR><font color=\"Blue\">◄</font> سخن که سامع از ذات صیغه اراده کند. <BR><font color=\"Blue\">◄</font> در اصطلاح درایة، ظنی الدلالة را گویند چنانچه در نص خواهد آمد. <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون آرد: ظاهر، بالهاء فی اللغة الواضح .و عند النحاة هو الاسم الذی لیس بضمیر، و یسمی بالمظهر ایضاً کما عرفت فی لفظ الضمیر. و عند الاصولیین هولفظ ظهر المراد منه بنفس الصیغة؛ أی المراد المختص بالوضع الاصلی أو العرفی دون المراد المختص بالمتکلم لأنّه لو علم مراد المتکلم یکون نصاً لأن ّ مراد المتکلم هو ما سیق لاجله الکلام فبقید الظهور خرج الخفی و المشکل و المجمل و المتشابه . و بالقید الاخیر خرج النص . و هذا مبنی علی مذهب المتأخرین . فانهم شرطوا فی الظاهر ان لایکون معناه مقصوداً بالسوق اصلاً، فرقاًبینه و بین النص . فلو قیل ابتداء جائنی القوم کان نصاً فی مجی ٔ القوم لکونه مقصوداً بالسوق ففی النص زیادة ظهور و وضوح بالنسبة الی الظاهر لأنّه سیق للمقصود و لذا کانت عبارة النص راجحة علی الاشارة عند التعارض . و اما المتقدمون فقالوا المعتبر فی الظاهر ظهورالمراد منه سواء کان مسوقاً له أو لا و فی النص کونه مسوقاً له سواء احتمل التخصیص و التأویل أو لا. فالظاهر عندهم اعم من النص و فی بحرالنکات حاشیةالهدایة فی باب الحیض فی مسئلة جواز القربان عند انقطاع الدم الفرق بین الظاهر و الاشارة و بین النص و العبارة، هو ان السوق سوقان سوق مقصود و سوق غیرمقصود و السوق المقصود لایکون الا فی النص و العبارة و السوق الغیرالمقصود یکون فی الظاهر. فکل نص ظاهر و لیس کل ظاهرنصاً. و الاشارة لا سوق فیها اصلاً مقصوداً و لا غیرمقصود لأنها ابداً تکون مفهومة من لفظ مجرد من النظر الی الاسناد الذی فیه فتجردت عن السوق بالکلیة اذ لایتصور السوق فی لفظ مفرد خال عن الاسناد بخلاف الظاهر فانه ابداً یکون باسناد و کل کلام یتضمن اسناداً فهو لایخلو عن سوق ما قطعاً. غایته ان ذلک السوق قد لایکون مقصوداً و ذلک لایخل بکونه مسوقاً. فینتج ان ّ الظاهر لایخلو عن الاسناد اما مقصود أو غیرمقصود. ثم العبارة یشترط فیها مطلق السّوق مقصوداً کان أو لا. فهی اعم ّ من النَّص ّ مطلقاً و مساویة للظاهر و مباینة للاشارة. و الظّاهر اعم من النص ّ مطلقاً و مساو للعبارة و مباین للاشارة و النص ّ اخص ّ من الظاهر و العبارة مطلقاًو مباین للاشارة - انتهی کلامه . فعلم من هذا ان الظاهر و النص ّ من انواع الکلام . و قد وقع فی نورالانوار شرح المنار ایضاً: ان ّ الظاهر و النص و المفسر و المحکم و الخفی و المشکل و المجمل و المتشابه کلها من انواع الکلام لا من انواع الکلمة لکنه قال و کذا الحال فی العبارة و الاشارة و الدلالة و الاقتضاء و المفهوم من کشف البزدوی ان الظاهر و النص من انواع اللفظ مفرداً کان أو مرکباً حیث قال الظاهر ما دل ّ علی معنی بالوضع الاصلی أو العرفی و یحتمل غیره احتمالاً مرجوحاً. و قیل هو ما لایفتقر فی افادته لمعناه الی غیره . ثم قال ما قیل ان ّ قصد المتکلم اذا اقترن بالظاهر صار نصاً و شرط فی الظاهر ان لایکون معناه مقصوداً بالسوق اصلاً و ان کان حسناً لکنه مخالف لعامة الکتب . فان شمس الائمة ذکر فی اصول الفقه : الظاهر ما یعرف المراد منه بنفس السماع من غیر تأمل، کقوله تعالی : احل اﷲ البیع (قرآن <span class=\"hlight\" dir=\"rtl\">٢٧٥/٢</span>). و هکذا ذکر القاضی الامام ابوزید فی التقویم و صدرالاسلام ابوالیسر فی اصول الفقه . و رأیت فی نسخة من تصانیف اصحابنا الحنفیة فی اصول الفقه : الظاهر اسم لما یظهر المراد منه بمجرد السمع من غیر اطالة فکرة و لا اجالة رویة، کقوله تعالی : الزانیة و الزانی، الاَّیة (قرآن <span class=\"hlight\" dir=\"rtl\">٢/٢٤</span>). و ذکر ابوالقاسم السمرقندی : الظاهر ما ظهر المراد منه لکنه یحتمل احتمالاً کالامر یفهم منه الایجاب و ان کان یحتمل التهدید و کالنهی یدل ّ علی التحریم و ان کان یحتمل التنزیه . فثبت بما ذکرنا ان ّ عدم السوق فی الظاهر لیس بشرط، بل هو ما ظهر المراد منه سواء کان مسوقاً أو لم یکن . و لم یذکر احد من الاصولیین فی تحدیده للظاهر هذا الشرط. ولو کان منظوراً لماغفل عنه الکل - انتهی کلام کشف البزدوی .و هکذا یفهم من العضدی حیث قال : من اقسام المتن الظّاهر، و هو ما دل ّ علی معنی دلالة ظنیة فخرج النص لکون دلالته قطعیة. فالنص ّ ما دل ّ علی معنی دلالة قطعیة وقد یفسر الظاهر بأنه بما دل ّ دلالة واضحة فیشتمل النص ّ ایضاً اذ الدلالة الواضحة اعم ّ من القطعیة و الظنیة ثم الدلالة الظنیة امّا بالوضع کالاسد للحیوان المفترس و امّا بعرف الاستعمال کالغائط للخارج من الدُبر بعد ان کان فی الاصل للمکان المطمئن، فیشتمل التعریف للمجاز و هو اقرب - انتهی . و الاَّمدی قال : ان الظاهر ما دل ّ دلالة ظنیة بالوضع أو بالعرف . فیخرج المجاز عن الحدّ. و ذکر الغزالی فی المستصفی : ان الظاهر هو الذی یحتمل التأویل، و النص هو الذی لایحتمله . کذا فی کشف البزدوی .<br />فائدة - حکم الظاهر و النص ّ، عند الحنفیة وجوب العمل بما ظهر منهما قطعاً و یقیناً و اما احتمال المجاز فغیرمعتبر لأنّه احتمال غیرناش عن دلیل و اما عند تعارضهما فالنص ارجح لأن ّ الاحتمال الذی فی الظاهر تأید بمعارضة النص و عند الشافعیة وجوب العمل و اعتقاد حقیة المراد لا ثبوت الحکم قطعاً و یقیناً لأن ّالاحتمال و ان کان بعیداً قاطع للیقین . فالحنفیة اخذوا القطع بمعنی ما یقطع الاحتمال الناشی ٔ عن دلیل . و الشافعیة اخذوا القطع بمعنی ما یقطع الاحتمال اصلاً - انتهی .<br /></font></div>'),
(178817, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ناحیه ٔ بزرگی است در فسطاط مصر و وجه تسمیه آن است که چون عمروبن العاص از اسکندریه بازگشت و طرح فسطاط بریخت، جمعی از قبایل که در اسکندریه بازمانده بودند در فسطاط به وی پیوستند و چون مردم به طرح فسطاط اشتغال یافته بودند، جای بر آنان تنگ آمد و شکایت به عمروبن العاص بردند. عمروبن العاص به معاویةبن حدیج امر کرد تا در کار ایشان بنگرد و او بدیشان گفت که : «أری لکم ان تظهروا علی القبائل فتتخذوا منزلاً ظاهراً عنهم ». ایشان چنین کردند و بدین موضع فرودآمدند و آن را ظاهر نام نهادند. کردویه بن عمرو الازدی الرهنی گوید:<br />ظهرنا بحمداﷲ و الناس دوننا<br />کذلک مذ کنا الی الخیر نظهر.<br />رج-وع به معجم البلدان شود.<br /></font></div>'),
(178818, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن یوسف غزنوی . او راست : کتاب مجمل الاسماء که در پایان سال <span class=\"hlight\" dir=\"rtl\">٥٦١</span> هَ . ق . در دمشق به اتمام رسانیده و آن مشتمل بر ده کتاب است در فنون مختلف : کتاب اول در آفرینش انسان و بیان احوال و اوصاف او. کتاب دوم در شناخت آسمان و آنچه مربوط به شناخت هوا و مافیهاست از منازل و بادها و غیره . کتاب سوم در شناخت نام زمین ها و جمیع مافیها. کتاب چهارم در اسامی درختان و میوه ها و زروع . کتاب پنجم در شتر و اوصاف او. کتاب ششم در شناخت سم داران از اسب و استر و غیره . کتاب هفتم در شناخت ذوات الاظلاف (سم شکافتگان = زنگله داران ). کتاب هشتم در پرندگان و درندگان و حشرات و هوام . کتاب نهم در نامهای صنعتگران و ادوات ایشان . کتاب دهم در شناخت اصناف مردم . در این کتاب لغات عرب را یاد کرده و سپس به فارسی تفسیر کرده است . (کشف الظنون چ استانبول ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨٦</span>).<br /></font></div>'),
(178819, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) احمدبن علی بن العمربن محمدبن عبداﷲ، ابوعبداﷲ العلوی الحسینی . نقیب علویان به بغداد.وی حدیث بسیار استماع و روایت کرده است و به قول ابن اثیر مورخ مشهور از نیکان بغداد بود و هم بدانجا وفات یافت (<span class=\"hlight\" dir=\"rtl\">٥٦٩</span> هَ . ق .). رجوع به الاعلام زرکلی چ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span> و کامل التواریخ ابن اثیر چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span> شود.<br /></font></div>'),
(178820, 'ظاهر', '<span class=\"hlight\">ظاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) بیبَرس بن عبداﷲ، السلطان الاعظم قسیم امیرالمؤمنین رکن الدین ابوالفتح البندقداری الصالحی، ملقب به الملک الظاهر. از ممالیک بحری . مولد او به دشت قبچاق در حدود <span class=\"hlight\" dir=\"rtl\">٦٢٥</span> هَ . ق . بود. او سالهای اوّل عمر خویش را در مولد خود به سر برد و سپس در هجوم تاتار اسیر و در سیواس به غلامی فروخته شد و از آنجا وی را به حلب و سپس به قاهره بردند و امیر علاءالدین ایدکین بندقدار وی را بخرید و بیبرس نزد وی ببود تا اینکه الملک الصالح نجم الدین ایوب در شوال <span class=\"hlight\" dir=\"rtl\">٦٤٤</span> بر امیر علاءالدین دست یافت و بیبرس را نیز ضمن سایر مایملک وی تحت اختیار خویش آورد و چون همت و فطنت و ذکاء او بدید وی را رئیس یکی از فرق حَرس خاص خود کرد و بیبرس در سایه ٔ همت و فطنت خویش مدارج ترقی بپیمود تا به مرتبه ٔ حکومت رسید. در سال <span class=\"hlight\" dir=\"rtl\">٦٥٨</span> که الملک المظفر قُطز به قتل رسید امراء که کفایت و لیاقت بیبرس را دیده و پسندیده بودند او را به امارت برداشتند و در نزدیک صالحیه نخست فارس الدین و سپس دیگر امراء بدو بیعت کردند و چون به قاهره رسیدند بیبرس با لقب الملک القاهر رکن الدین به تخت نشست، ولی وزیر او زین الدین ابن الزبیر او را به تغییر این لقب واداشت و پس از مشورت به الملک الظاهر ملقب گردید. بیبرس در سر داشت که وسعت دولت مصر را به وسعت زمان صلاح الدین ایوبی رساند و به صلیبیون که بر سواحل دریای سفید دست یافته بودند اعلان جنگ دهدو با آنکه در پیش بردن این مقصود سعی بلیغ کرد ولی اجل مهلت نداد که به انجام همه ٔ آرزوهای خویش توفیق یابد و شهرهای ساحلی را از وجود صلیب و ناقوس پاک سازد. بیبرس مردی شجاع و جبار و سائس بود. در جنگها شخصاً حاضر میشد و شمشیر میزد. از جمله ٔ قتالهای هول انگیز او جنگهایی است که با مغول و فرنگیان کرد و فتوحات عظیمی او را دست داد که از آنجمله فتح بلاد نوبه ودنقله است که پیش از وی هیچیک از خلفا و سلاطین با همه ٔ لشکرکشیهای خود به فتح آن نواحی نائل نیامده بودند. چون بیبرس به سلطنت رسید گروهی از ولاة و حکام باوی از در غدر و مخاصمت درآمدند و از آنجمله بود علم الدین سنجر که در دمشق علم طغیان برافراشت و در <span class=\"hlight\" dir=\"rtl\">٦٥٨</span> با لقب الملک المجاهد خود را سلطان نامید و به نام خویش سکه زد. بیبرس لشکری تحت انقیاد علاءالدین ایدکین بندقداری به محاربه ٔ او فرستاد (<span class=\"hlight\" dir=\"rtl\">٦٥٩</span>) و حلبی از این لشکر شکست خورد و بگریخت . بیبرس مولای سابق خویش علأالدین را به ولایت دمشق گماشت و او این نواحی را در تحت فرمان آورد و به نام ظاهر خطبه خواند و سکه زد.<br />پس از این واقعه باز نهضتهائی در حلب و دمشق و دیگر نواحی بر ضد بیبرس رخ داد و بیبرس با فرستادن لشکری به سرداری جمال الدین محمودی آن فتنه ها فرونشاند و شمس الدین اقوش البرلی والی نابلس را که بر حلب دست یافته و فخرالدین حمصی والی آنجا را به حیله رانده بود و اضطراراً اطاعت ظاهر را گردن نهاده، امان داد و به حضور خواست و اکرام کرد، اما بعد بر او متغیر شد و در <span class=\"hlight\" dir=\"rtl\">٦٦١</span>به قبض او فرمان داد. در این میان گروهی از کردهای شهرزور بر اثر هجوم تتار به شهر کرک که مقر حکومت ملک مغیث از امراء ایوبی بود رسیدند و مغیث ایشان را در عداد لشکریان خویش درآورد و به غارت شوبک که جزء متصرفات ظاهر بود فرستاد. چون خبر افعال ایشان به مصررسید، ظاهر همت بر آن گماشت که به کرک رود و ایشان را سرکوبی کند. مغیث کس نزد او فرستاد و اظهار اطاعت کرد و برای اکراد امان خواست . ظاهر آن قوم را امان داد و از گناهشان درگذشت، ولی خود از جانب مغیث آسوده خاطر نبود و با آنکه به شفاعت و وساطت مادر مغیث اورا نیز امان داده بود، به عهد خود وفا نکرد و مغیث را دستگیر کرده به قاهره برد و محبوس و مقید بداشت تا آنگاه که کشته شد.<br />دیگر از اتفاقات زمان وی احیاء خلافت عباسی است در مصر. توضیح آنکه چون خلافت بنی عباس در بغداد به دست هلاکو در <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> هَ . ق . برافتاد بیبرس برای استحکام مبانی حکومت خویش و احراز تفوق بر سایر ممالیک درصدد برآمد که احکام خویش را آمیخته با فرامین شرع در ولایات تابعه تنفیذ دهد و چون این فکر قبل از وی نیز ریشه داشت و برخی از ولاة و حکام جزء در این راه گام زده بودند، بیبرس به زودی به مقصود نائل آمد و اندیشه ٔ خویش را جامه ٔ عمل پوشید، بدین طریق که دو تن از امراء وی یعنی امیر علأالدین طیبرس و علاءالدین بندقداری نامه ای بدو نوشتند که مردی به دمشق آمده و مدعی است که احمدبن الامام الظاهربن الامام الناصر عباسی است و گروهی از اعراب نیز بر وی گرد آمده اند. ظاهر دستور داد تا او را به مصر فرستند و خود جمعی را به استقبال روانه داشت و چون موکب احمد دررسید با وزیر بهاءالدین بن حنا و قاضی القضاة تاج الدین بن بنت الاعز و امراء و عساکر برنشست و به دیدار او رفت و چون برابر وی رسید پیاده شد و او را در آغوش گرفت و به اکرام تمام به قلعه درآورد و بدین اکرام نیز اقتصار نکرد بلکه مجلسی منعقد ساخت و قضاة و امراء و علماء و دیگر ارباب دولت را فراخواند تابه صحت نسب امام شهادت دهند و شیخ الاسلام عزّالدین بن عبدالسلام نیز در این مجلس حضور یافت و حاضران به صحت نسب احمد که از اولاد عباس بن عبدالمطلب است شهادت دادند و سپس به خلافت با وی بیعت کردند و نخست ظاهر با او بیعت کرد، علی کتاب اﷲ و سنة رسوله و الامر بالمعروف و النهی عن المنکر و الجهاد فی سبیل اﷲ و اخذ اموال اﷲ بحقها و صرفها فی مستحقها. قضاة نیز بدینگونه با وی بیعت کردند و او را المستنصر باﷲ لقب دادند و به نام او سکه زدند و عامه نیز موافق یا مخالف بیعت کردند. پس از چندی ظاهر خلیفه را بر آن داشت که به بغداد رود و کرسی خلافت ازدست رفته ٔ بغداد را به تصرف آرد و لشکری نیز با وی بفرستاد اما مغولان به مقابله ٔ او برخاستند و خلیفه را با گروه بسیار از لشکریان او به قتل آوردند (<span class=\"hlight\" dir=\"rtl\">٦٦٠</span> هَ . ق .). ظاهر پس از کشته شدن المستنصر باﷲ برای جلوگیری از فروریختن بنیان منظور و مقصود خود دستور داد که امیر ابوالعباس احمد را به مصر آرند (<span class=\"hlight\" dir=\"rtl\">٦٦١</span>) و پس از اثبات صحت نسب وی و اخذ شهادت او را با لقب الحاکم بامراﷲ به خلافت برداشت .<br />ظاهر جنگهای بسیار با صلیبیون و مغولان کرد و به فتوحات و پیروزی هائی نیز نائل آمد و سرانجام در رجب سال <span class=\"hlight\" dir=\"rtl\">٦٧٦</span> به دمشق درگذشت و یا به قول برخی از مورخین مسموم گردید، ولی ظاهراً قول مقریزی که مرگ وی را بر اثر اسراف نوشیدن قمز (نوعی از نبید) و بروز بیماری بدان سبب میداند درست مینماید. محیی الدین بن عبدالظاهر در رثاء او گفته است :<br />اﷲ اکبرانها لمصیبةٌ<br />منها الرواسی خیفة تتقلقل <br />لهفی علی الملک الذی کانت به الد- <br />دنیا تطیب فکل قفر منزل <br />الظاهر السلطان من کانت له <br />منن علی کل الوری و تطول <br />لهفی علی آرائه تلک التی <br />مثل السهام الی المصالح ترسل <br />لهفی علی تلک العزائم کیف قد<br />غفلت و کانت قبل ذا لاتغفل <br />ما للرمال تخولتها رعدة<br />لکنها اذ لیس تعقل نعقل <br />سهم ٌ اصاب و مارمی من قبله <br />سهم له فی کل قلب مقتل <br />أنا ان بکیت ُ دماً فعذری واضح <br />و لئن صبرت فاننی اتمثل <br />خلف الشهید لنا السعید فادمع<br />منهلة فی اوجه تتهلل .<br />و رجوع به کتاب الظاهر بیبرس و حضارة مصر فی عصره تألیف محمد جمال الدین سرور چ مصر و وفیات الاعیان چ مصر ص <span class=\"hlight\" dir=\"rtl\">٨٥</span> به بعد و الاعلام چ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span> شود.<br /></font></div>'),
(178821, 'ظاهرالصلاح', '<span class=\"hlight\">ظاهرالصلاح .</span> <font color=\"DarkGreen\"><b>[ هَِ رُص ْ ص َ ]</font></b> (ع ص مرکب ) که ظاهری بر طبق و ملائم شرع یا اخلاق دارد.<br /></font></div>'),
(178822, 'ظاهرالعلم', '<span class=\"hlight\">ظاهرالعلم .</span> <font color=\"DarkGreen\"><b>[ هَِ رُل ْ ع ِ ]</font></b> (ع اِ مرکب ) نزد اهل تحقیق، عبارت است از اعیان ممکنات . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178823, 'ظاهرالمذهب', '<span class=\"hlight\">ظاهرالمذهب .</span> <font color=\"DarkGreen\"><b>[ هَِ رُل ْ م َ هََ ]</font></b> (ع اِ مرکب ) ظاهرالروایة. مراد از این دو آن چیزی است که در جامعالکبیر و جامعالصغیر و سیرالکبیر است و مراد از غیر ظاهر المذهب و الروایة، جرمانیات <font color=\"DarkGreen\"><b>[ کذا و شاید جرجانیات ]</font></b> و کیسانیات و هارونیات است . کذا فی الجرجانی . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178824, 'ظاهرالممکنات', '<span class=\"hlight\">ظاهرالممکنات .</span> <font color=\"DarkGreen\"><b>[ هَِ رُل ْ م ُم ْ ک ِ ]</font></b> (ع اِ مرکب ) هو تجلی الحق بصور اعیانها و صفاتها. و هو المسمی بالوجود الالهی . وقد یطلق علیه ظاهرالوجود. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178825, 'ظاهرالوجود', '<span class=\"hlight\">ظاهرالوجود.</span> <font color=\"DarkGreen\"><b>[ هَِ رُل ْ وُ ]</font></b> (ع اِ مرکب ) عبارة عن تجلیات الاسماء. فان ّ الامتیاز فی ظاهرالعلم حقیقی و الوحدة نسبیّة. و اما فی ظاهرالوجود فالوحدة حقیقیة و الامتیاز نسبی . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178826, 'ظاهربین', '<span class=\"hlight\">ظاهربین .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (نف مرکب ) آنکه فقط صورت ظاهر را بیند و از باطن بیخبر ماند. ظاهری . قشری . خُشک .<br /></font></div>'),
(178827, 'ظاهربینی', '<span class=\"hlight\">ظاهربینی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (حامص مرکب ) دیدن صورت ظاهر و بیخبر ماندن از باطن .<br /></font></div>'),
(178828, 'ظاهرساز', '<span class=\"hlight\">ظاهرساز.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (نف مرکب ) مُرائی . آنکه با صور ظاهر امور مردمان را به خود جلب کند یا فریبد.<br /></font></div>'),
(178829, 'ظاهرسازی', '<span class=\"hlight\">ظاهرسازی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (حامص مرکب ) عمل ظاهرساز.<br /></font></div>'),
(178830, 'ظاهرنگر', '<span class=\"hlight\">ظاهرنگر.</span> <font color=\"DarkGreen\"><b>[ هَِ ن ِ گ َ ]</font></b> (نف مرکب ) آنکه به معنی امور ننگرد و به صور اکتفا کند.<br /></font></div>'),
(178831, 'ظاهرپرست', '<span class=\"hlight\">ظاهرپرست .</span> <font color=\"DarkGreen\"><b>[ هَِ پ َ رَ ]</font></b> (نف مرکب ) ظاهربین <span class=\"hlight\">:</span> <br />زاهد ظاهرپرست از حال ما آگاه نیست <br />در حق ما هرچه گوید جای هیچ اکراه نیست .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(178832, 'ظاهرپرستی', '<span class=\"hlight\">ظاهرپرستی .</span> <font color=\"DarkGreen\"><b>[ هَِ پ َ رَ ]</font></b> (حامص مرکب ) ظاهربینی . رجوع به ظاهربینی شود.<br /></font></div>'),
(178833, 'ظاهری', '<span class=\"hlight\">ظاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) لقب ابن حزم ابومحمد علی بن احمدبن سعیدبن حزم اموی اندلسی . رجوع به ابن حزم ... شود.<br /></font></div>'),
(178834, 'ظاهری', '<span class=\"hlight\">ظاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی ) مذهب فقهی منسوب به ابوسلیمان داودبن علی بن خلف اصفهانی متوفی به سال <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> هَ . ق . که به ظاهر آیات و احادیث عمل میکرد. این مذهب عبارت است از اخذ به کتاب و سنت و الغاء رأی و قیاس و تأویل و این کلمه گاهی مقابل باطنی آید، یعنی مذهب سبعیه و باطنیان <span class=\"hlight\">:</span> <br />فاطِمیم فاطمیم فاطمی <br />تا تو بدرّی ز غم ای ظاهری <br />فاطمه را عایشه مایندر است <br />پس تو مرا شیعت مایندری <br />شیعت مایندری ای بدنشان <br />شاید اگر دشمن دختندری .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> مقابل صوفی نیز آید و شاید این معنی از همان لقب داودبن علی آمده باشد. <BR><font color=\"Blue\">◄</font> قشری . خشک . رجوع به الانساب سمعانی و الفهرست ابن ندیم و المیزان الشعرانی و دائرةالمعارف اسلام و رجوع به ظاهریة شود.<br /></font></div>'),
(178835, 'ظاهریه', '<span class=\"hlight\">ظاهریه .</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (اِخ ) رجوع به ظاهری شود.<br /></font></div>'),
(178836, 'ظاهریه', '<span class=\"hlight\">ظاهریه .</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (اِخ ) نام دو قریه در مصر منسوب به الظاهر لاعزاز دین اﷲ از خلفای فاطمی است . رجوع به معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span> شود.<br /></font></div>'),
(178837, 'ظاهریه', '<span class=\"hlight\">ظاهریه .</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (ص نسبی، اِ) نام دراهمی که در مصر شایع بوده است .<br /></font></div>'),
(178838, 'ظب', '<span class=\"hlight\">ظب .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) ج ِ ظبی .<br /></font></div>'),
(178839, 'ظبات', '<span class=\"hlight\">ظبات .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظُبة.<br /></font></div>'),
(178840, 'ظباظب', '<span class=\"hlight\">ظباظب .</span> <font color=\"DarkGreen\"><b>[ ظَ ظِ ]</font></b> (ع اِ) ج ِ ظبظاب .<br /></font></div>'),
(178841, 'ظبة', '<span class=\"hlight\">ظبة.</span> <font color=\"DarkGreen\"><b>[ ظُ ب َ ]</font></b> (ع اِ) دَم شمشیر یا طرف تیزی آن یا دَم سنان و مانند آن .ج، اَظْب (اَظْبی )، ظُبات، ظُبون، ظِبون، ظُبی ̍.<br /></font></div>'),
(178842, 'ظبظاب', '<span class=\"hlight\">ظبظاب .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) بیماری، هرچه باشد. رنج . درد. عیب .ما به ظبظاب ؛ باکیش نیست . <BR><font color=\"Blue\">◄</font> آبله ریزه ای که در چشم و رخسار ملاحان حادث شود. رجوع به جوش شود. <BR><font color=\"Blue\">◄</font> بانگ و فریاد. <BR><font color=\"Blue\">◄</font> سخن ترساننده به شرّ و بدی . <BR><font color=\"Blue\">◄</font> (مص ) تب زده گردیدن . <BR><font color=\"Blue\">◄</font> (اِخ ) نام پادشاهی از یمن . ج، ظباظب .<br /></font></div>'),
(178843, 'ظبظبة', '<span class=\"hlight\">ظبظبة.</span> <font color=\"DarkGreen\"><b>[ ظَ ظَ ب َ ]</font></b> (ع مص ) تب زده گردیدن .<br /></font></div>'),
(178844, 'ظبون', '<span class=\"hlight\">ظبون .</span> <font color=\"DarkGreen\"><b>[ ظُ <span class=\"hlight\" dir=\"rtl\">/</span> ظِ ]</font></b> (ع اِ) ج ِ ظُبة.<br /></font></div>'),
(178845, 'ظبی', '<span class=\"hlight\">ظبی .</span> <font color=\"DarkGreen\"><b>[ ظُب ْ با ]</font></b> (اِخ ) ناحیه ای است از سواد عراق نزدیک مداین .<br /></font></div>'),
(178846, 'ظبی', '<span class=\"hlight\">ظبی .</span> <font color=\"DarkGreen\"><b>[ ظَب ْی ْ ]</font></b> (ع اِ) آهو. غزال . ابووَثاب . ج، ظِباء، ظَبیات، ظب، ظُبی . و رجوع به صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span> شود. <BR><font color=\"Blue\">◄</font> اسب فربه . <BR><font color=\"Blue\">◄</font> نشان و داغی بعضی عرب را. <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است . <BR><font color=\"Blue\">◄</font> نام وادیی است متعلق به بنی تغلب در ساحل فرات . <BR><font color=\"Blue\">◄</font> نام موضعی است . <BR><font color=\"Blue\">◄</font> نام ریگزاری است و برخی گفته اند نام شهری است نزدیک ذی قار و قول امروءالقیس را بدان تفسیر کنند <span class=\"hlight\">:</span> <br />و تعطوا برخص غیر شَثْن کأنّه <br />اساریع ظبی أو مساویک اسحل .<br /><BR><font color=\"Blue\">◄</font> قرن ظبی ؛ کوهی است در دیار بنی اسد بین سعدیه و مُعاذة. <BR><font color=\"Blue\">◄</font> نام آبی است از غطفان و بنی جحاش بن سعدبن ذبیان . <BR><font color=\"Blue\">◄</font> عین ظبی ؛ موضعی است بین کوفه و شام . (معجم البلدان ).<br /></font></div>'),
(178847, 'ظبی', '<span class=\"hlight\">ظبی .</span> <font color=\"DarkGreen\"><b>[ ظُ ب َی ی ]</font></b> (اِخ ) آبی است در خاک حجاز که دور از جاده ٔ حاج ّعراق واقع و میان آن تا النقرة یک روز فاصله است .<br /></font></div>'),
(178848, 'ظبی', '<span class=\"hlight\">ظبی .</span> <font color=\"DarkGreen\"><b>[ ظُ بی ی ]</font></b> (ع اِ) ج ِ ظَبی .<br /></font></div>'),
(178849, 'ظبی', '<span class=\"hlight\">ظبی .</span> <font color=\"DarkGreen\"><b>[ ظَب ْی ْ ]</font></b> (اِخ ) کنیزکی ازآن ِ سعید فارسی که بر عصابه ٔ وی به زر نوشته بود:<br />العین ُ قارئةٌلِما کتبت <br />فی وَجْنتی ّ اَنامِل ُ الشجن .<br /><font color=\"Red\">(عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>).</font><br /></font></div>'),
(178850, 'ظبیات', '<span class=\"hlight\">ظبیات .</span> <font color=\"DarkGreen\"><b>[ ظَ ب َ ]</font></b> (ع اِ) ج ِ ظَبی و ظَبیة.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178851, 'ظبیان', '<span class=\"hlight\">ظبیان .</span> <font color=\"DarkGreen\"><b>[ ظَب ْ ]</font></b> (اِخ ) پدر عالیه است که به قولی از ازواج رسول بود و پیامبر او را طلاق گفت .<br /></font></div>'),
(178852, 'ظبیان', '<span class=\"hlight\">ظبیان .</span> <font color=\"DarkGreen\"><b>[ ظَ ب َ ]</font></b> (اِخ ) (رأس ...) کوهی است در یمن .<br /></font></div>'),
(178853, 'ظبیانی', '<span class=\"hlight\">ظبیانی .</span> <font color=\"DarkGreen\"><b>[ ظَب ْ ]</font></b> (اِخ ) ابوعبیداﷲ. تابعی است .<br /></font></div>'),
(178854, 'ظبیب', '<span class=\"hlight\">ظبیب .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) ظُبة.دَم شمشیر یا طرف تیزی آن یا دم سنان و مانند آن .<br /></font></div>'),
(178855, 'ظبیة', '<span class=\"hlight\">ظبیة.</span> <font color=\"DarkGreen\"><b>[ ظَب ْ ی َ ]</font></b> (اِخ ) مادر ابوموسی اشعری . و به روایتی نام وی طفیه است . (قاموس الاعلام ).<br /></font></div>'),
(178856, 'ظبیة', '<span class=\"hlight\">ظبیة.</span> <font color=\"DarkGreen\"><b>[ ظَب ْ ی َ ]</font></b> (اِخ ) بنت وزیر الباهلیة. یکی از زنان ادیبه است و در اغانی نام وی آمده است .<br /></font></div>'),
(178857, 'ظبیة', '<span class=\"hlight\">ظبیة.</span> <font color=\"DarkGreen\"><b>[ ظُ ب َی ْ ی َ ]</font></b> (اِخ ) نام جایگاهی و ظاهراً نام بلاد قوم حاجزالازدی است . (معجم البلدان ).<br /></font></div>'),
(178858, 'ظبیة', '<span class=\"hlight\">ظبیة.</span> <font color=\"DarkGreen\"><b>[ ظَب ْ ی َ ]</font></b> (اِخ )مادر ابوقتاده ٔ انصاری و او از صحابیان است . حدیث عدم وجوب جهاد و نماز جمعه بر زنان از پیغمبر اکرم (ص ) بدو خطاب شده و از وی مروی ّ است . (قاموس الاعلام ).<br /></font></div>'),
(178859, 'ظبیة', '<span class=\"hlight\">ظبیة.</span> <font color=\"DarkGreen\"><b>[ ظَب ْ ی َ ]</font></b> (ع اِ) تأنیث ظبی . آهوی ماده . ام الخشف . ام شادن . ام الطلا. <BR><font color=\"Blue\">◄</font> گوسفند ماده . <BR><font color=\"Blue\">◄</font> شَرم زن . <BR><font color=\"Blue\">◄</font> شرم ناقه (اصمعی گویدآن هر صاحب حافری راست و فراء گوید تنها در سگ ماده مستعمل است ). <BR><font color=\"Blue\">◄</font> انبان یا انبان خُرد. انبانک سیم . کیسه ٔ چرمین . خریطه . <BR><font color=\"Blue\">◄</font> خم ِ وادی . <BR><font color=\"Blue\">◄</font> زهدان . <BR><font color=\"Blue\">◄</font> (اِخ ) چاه زمزم . <BR><font color=\"Blue\">◄</font> نام سه اسب . <BR><font color=\"Blue\">◄</font> نام دو وادی . <BR><font color=\"Blue\">◄</font> نام زنی . <BR><font color=\"Blue\">◄</font> نام دو موضع:یکی بین ینبع و غیقه به ساحل دریا و ذوظَبْیة منسوب بدین مکان است و دیگری موضعی است در دیار جُهینة.<br /></font></div>'),
(178860, 'ظج', '<span class=\"hlight\">ظج .</span> <font color=\"DarkGreen\"><b>[ ظَج ج ]</font></b> (ع مص ) بانگ و فریادخواهی کردن در جنگ، و در غیر جنگ بیشتر به ضاد معجمه (ضَج ّ) گویند.<br /></font></div>'),
(178861, 'ظر', '<span class=\"hlight\">ظر.</span> <font color=\"DarkGreen\"><b>[ ظِرر ]</font></b> (ع اِ) اُظرور. سنگ یا سنگ گرد تیزاطراف . ج، ظِرار، ظِرّار.<br /></font></div>'),
(178862, 'ظر', '<span class=\"hlight\">ظر.</span> <font color=\"DarkGreen\"><b>[ ظَرر <span class=\"hlight\" dir=\"rtl\">/</span> ظُرر ]</font></b> (اِخ ) نام آبی است .<br /></font></div>'),
(178863, 'ظراب', '<span class=\"hlight\">ظراب .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) ج ِ ظَرِب .<br /></font></div>'),
(178864, 'ظرابی', '<span class=\"hlight\">ظرابی .</span> <font color=\"DarkGreen\"><b>[ ظَ بی ی ]</font></b> (ع اِ) ج ِ ظَربان و ظِرباء.<br /></font></div>'),
(178865, 'ظرابین', '<span class=\"hlight\">ظرابین .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) ج ِ ظَربان .<br /></font></div>'),
(178866, 'ظرار', '<span class=\"hlight\">ظرار.</span> <font color=\"DarkGreen\"><b>[ ظِ <span class=\"hlight\" dir=\"rtl\">/</span> ظِرْ را ]</font></b> (ع اِ) ج ِ ظِر.<br /></font></div>'),
(178867, 'ظراف', '<span class=\"hlight\">ظراف .</span> <font color=\"DarkGreen\"><b>[ ظُرْ را ]</font></b> (ع ص ) زیرک . ج، ظُرافون .<br /></font></div>'),
(178868, 'ظراف', '<span class=\"hlight\">ظراف .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع ص، اِ) ج ِ ظریف .<br /></font></div>'),
(178869, 'ظراف', '<span class=\"hlight\">ظراف .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع ص ) زیرک . دانا. ج، ظُرفاء.<br /></font></div>'),
(178870, 'ظراف', '<span class=\"hlight\">ظراف .</span> <font color=\"DarkGreen\"><b>[ ظَرْ را ]</font></b>(ع ص ) شخصی که به درجه ٔ کمال زیرک و خوش طبع باشد.<br /></font></div>'),
(178871, 'ظرافة', '<span class=\"hlight\">ظرافة.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (ع اِمص ) رجوع به ظرافت شود.<br /></font></div>'),
(178872, 'ظرافت', '<span class=\"hlight\">ظرافت .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (ع اِمص ) زیرکی . تیزدل شدن . زیرک شدن . <BR><font color=\"Blue\">◄</font> ماهر گردیدن . <BR><font color=\"Blue\">◄</font> ظرف . رجوع به ظرف شود. <BR><font color=\"Blue\">◄</font> چابکی . <BR><font color=\"Blue\">◄</font> سبکروحی . <BR><font color=\"Blue\">◄</font> سبکروح شدن . خوش طبعی . مزاح <span class=\"hlight\">:</span> درویشی به مقامی درآمد که صاحب آن بقعه کریم النفس بود، طایفه ای اهل فضل و بلاغت در صحبت او هریک بذله و لطیفه ای همی گفتند، درویش راه بیابان قطعکرده بود و مانده و چیزی نخورده، یکی از آن میان به طریق ظرافت گفت ترا هم چیزی بباید گفت . (گلستان ).<br />تو بر سر قدر خویشتن باش و وقار<br />بازی و ظرافت به ندیمان بگذار.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> زیبائی . (بحرالجواهر) <span class=\"hlight\">:</span> این طغرل غلامی بود که از میان دوهزار غلام چنو بیرون نیاید به دیدار و قد و رنگ و ظرافت و لیاقت . (تاریخ بیهقی ). حال ذلاقت و لیاقت و ظرافت و لطافت او بر رأی سلطان عرض کردند. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون آرد: ظرافت بفتح ظاء و راء مهمله، در لغت به معنی زیرک شدن . الظریف ؛ زیرک و زیبا وخوش طبع. کذا فی کشف اللغات و الصراح . قال ابوالبقاء فی حاشیةالکافیة فی بحث خبر لاء التی لنفی الجنس : و ظرافت اطلاق میشود بر ملکه ای که میباشد مبداء صدور الفاظی که از ظرافت و ایهامی خالی نباشند و نیز ظرافت بر عین آن الفاظ هم اطلاق گردد. پس معلوم میگردد که هرکه دارای چنین ملکه ای باشد او را ظریف توان نامید - انتهی .<br /></font></div>'),
(178873, 'ظرافت نمودن', '<span class=\"hlight\">ظرافت نمودن .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) تظرف .<br /></font></div>'),
(178874, 'ظرافت کردن', '<span class=\"hlight\">ظرافت کردن .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ک َ دَ ]</font></b> (مص مرکب ) تکیﱡس . به تکلف زیرکی نمودن . (منتهی الارب ).<br /></font></div>'),
(178875, 'ظرافون', '<span class=\"hlight\">ظرافون .</span> <font color=\"DarkGreen\"><b>[ ظُرْ را ]</font></b> (ع ص، اِ) ج ِ ظُرّاف .<br /></font></div>'),
(178876, 'ظران', '<span class=\"hlight\">ظران .</span> <font color=\"DarkGreen\"><b>[ ظُرْ را ]</font></b> (ع اِ) ج ِ ظُرَر و ظریر.<br /></font></div>'),
(178877, 'ظران', '<span class=\"hlight\">ظران .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) الماس . صاحب الجماهر گوید: و یظن بعضهم ان الظران هوالألماس و لیس به و انما هو اسم مأخوذ من الظر و هو القطع الذی منه تسمی الظران ظراناً و هو ماءالحدیدالذکر المسقی (؟). رجوع به الجماهر ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> و <span class=\"hlight\" dir=\"rtl\">٩٣</span> شود.<br /></font></div>'),
(178878, 'ظران', '<span class=\"hlight\">ظران .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(178879, 'ظرایف', '<span class=\"hlight\">ظرایف .</span> <font color=\"DarkGreen\"><b>[ ظَ ی ِ ]</font></b> (ع ص، اِ) ظَرائِف . ج ِ ظریفه <span class=\"hlight\">:</span> <br />به زیورها و گوهرهای شهوار<br />ظرایفها و دیباهای بسیار.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />امیر مسعود را بسیار نزل فرستاده بود <font color=\"DarkGreen\"><b>[ منوچهربن قابوس ]</font></b> پوشیده به خطها و نامه ها و ظرایف گرگان و دهستان . (تاریخ بیهقی ). و مواضعت نهاده <font color=\"DarkGreen\"><b>[ عیسی ]</font></b> هر سالی که خراج فرستد برادرزاده را هزار دینار هریوه باشد بیرون از جامه و ظرایف . یک سال آورده بودند و بدین رضا افتاد. (تاریخ بیهقی ).<br />و رجوع به ظرائف شود. <br /></font></div>'),
(178880, 'ظرب', '<span class=\"hlight\">ظرب .</span> <font color=\"DarkGreen\"><b>[ ظَ رِ ]</font></b> (ع اِ) سنگ برآمده ٔ تیزاطراف یا کوه پست گسترده یا کوه خرد و پشته . ج، ظِراب . <BR><font color=\"Blue\">◄</font> کوه تیزقُلّه در آسمان که نه وادی دارد و نه شکاف و همه ٔ آن سیاه است . <BR><font color=\"Blue\">◄</font> (اِخ ) برکه ای است میان قرعاء و واقصه درراه مکّة. (معجم البلدان ). <BR><font color=\"Blue\">◄</font> نام اسب رسول اکرم صلوات اﷲ علیه . <BR><font color=\"Blue\">◄</font> نام مردی است .<br /></font></div>'),
(178881, 'ظرب', '<span class=\"hlight\">ظرب .</span> <font color=\"DarkGreen\"><b>[ ظُ رُب ب ]</font></b> (ع ص ) کوتاه بالای درشت و پرگوشت .<br /></font></div>'),
(178882, 'ظرب', '<span class=\"hlight\">ظرب .</span> <font color=\"DarkGreen\"><b>[ ظَ رَ ]</font></b> (ع مص ) چفسیدن . التصاق . ملصق شدن . دوسیدن .<br /></font></div>'),
(178883, 'ظرب لبن', '<span class=\"hlight\">ظرب لبن .</span> <font color=\"DarkGreen\"><b>[ ظَ رِ ب ُ ل ُ ]</font></b> (اِخ ) موضعی که در آن یکی از جنگهای عرب بوده است . (معجم البلدان ).<br /></font></div>'),
(178884, 'ظربان', '<span class=\"hlight\">ظربان .</span> <font color=\"DarkGreen\"><b>[ ظَرِ ]</font></b> (ع اِ) جانورکی است بدبوی مانند گربه گوشتخوارو موذی است و برای طعمه به لانه های مرغ و خروس و سایر پرندگان اهلی حمله میکند. مرادف های دیگر ظربان : مفرق النعم . خز. شغاره . (زمخشری ). انگورخوار. (دهار). ج، ظرابی ّ، ظرابین، ظِرباء و ظِربی اسم جمع آن است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">فسا بینهم الظربان </span> ؛ از یکدیگر بریدند و پراکنده شدند.<br /></font></div>'),
(178885, 'ظربی', '<span class=\"hlight\">ظربی .</span> <font color=\"DarkGreen\"><b>[ ظِ با ]</font></b> (ع اِ) اسم جمع ظربان .<br /></font></div>'),
(178886, 'ظرر', '<span class=\"hlight\">ظرر.</span> <font color=\"DarkGreen\"><b>[ ظُ رَ ]</font></b> (ع اِ) سنگ تیز. ج، ظُرّان .<br /></font></div>'),
(178887, 'ظرظور', '<span class=\"hlight\">ظرظور.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) سنگ یا سنگ گرد تیزاطراف . ظِرّ. اظرور. ظُرر. ظررة.<br /></font></div>'),
(178888, 'ظرف', '<span class=\"hlight\">ظرف .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) جای چیزی . آنچه در آن چیزی نهند. آوند. باردان . (مهذب الاسماء). حیّز. خنور. اِناء. وِعاء. ج، ظروف <span class=\"hlight\">:</span> در وقت گویائی من به این سوگند یا ملک من شود در بازمانده ٔ عمرم از زر یا رزق یا جوهر یا ظرف یا پوشیدنی یا فرش . (تاریخ بیهقی ).<br />بنده کی گردد آنکه باشد حُر<br />نتوان کرد ظرف پُر را پُر.<br /> <font color=\"Red\">سنائی .</font><br />معانی هرگز اندر حرف ناید<br />که بحر قلزم اندر ظرف ناید.<br /> <font color=\"Red\">شبستری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظرف دررفته </span> ؛ خالص . که وزن ظرف آن موضوع شده باشد، چنانکه چون چیزی را وزن کنند و وزن مظروف را از وزن ظرف جدا سازند گویند وزن آن، ظرف دررفته فلان مقدار است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظرف زمان </span> ؛ اسمی که دلالت بر زمان وقوع چیزی کند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظرف مکان </span> ؛ اسمی که دلالت بر مکان وقوع و استقرار چیزی کند.<br /> <BR><font color=\"Blue\">◄</font> (اِمص ) زیرکی . کیاست . <BR><font color=\"Blue\">◄</font> نقی الظرف ؛ امین راست باز نه خائن دغل باز. <BR><font color=\"Blue\">◄</font> رأیته بظرفه ؛ ای بنفسه . <BR><font color=\"Blue\">◄</font> ماهر گردیدن . <BR><font color=\"Blue\">◄</font> در محاوره ٔ فارسی زبانان مجازاً به معنی حوصله است، چنانکه شخص کم حوصله را کم ظرف و تنگ ظرف گویند. و ظرف در این شعر ملا وحشی نیز از همان قبیل است <span class=\"hlight\">:</span> <br />این ظرف بین که تشنه لبان را به قطره ای <br />صد احتیاج هست و تمنا نمی کنند.<br /><font color=\"Red\">(از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> ظرف و ظرافت در زبان باشد و گیرندگی در دو چشم و ملاحت در دهان و نیکوئی در بینی یا خوبروئی و خوش هیئتی : وجه ظریف . هیئةٌ ظریفة. یا ظرف در روی و زبان است . و ظرف در زبان، بلاغت و حسن عبارت است و در روی، خوبی و نیکوئی و یا ظرف بزاعت و ذکاء قلب و یا ظرف حذق است وبه ظرف و ظرافت جز جوانان سبکروح را از مرد و زن صفت نکنند و راغب گوید ظرف حالتی است جامع عموم فضائل نفسانیه و بدنیه و خارجیه و از این رو صاحب علم و شجاعت و نیکو لباس و ریاش . <BR><font color=\"Blue\">◄</font> (اِ) صاحب کشاف اصطلاحات الفنون آرد: ظرف، بالفتح و سکون الراء عنداهل العربیة یطلق علی معان منها اسم ما یصح ان یقعفیه فعل زماناً کان أو مکاناً و الاول ظرف زمان کالیوم و الدهر و الثانی ظرف مکان کالیمین و الشمال . و فی الهدایة حاشیة الکافیة: ظرف الزمان ما یصلح جواباً لمتی . و ظرف المکان ما یصلح جواباً لأین - انتهی . أی ّ اسم ما یصلح الخ، یقال له اسم الظرف ایضاً. قال فی التوضیح من اسماء الظروف مع - انتهی . و من اقسام اسماء الظروف اسماء الزمان و المکان و هی الاسماء الموضوعة للزمان و المکان و باعتبار وقوع الفعل فیهما مطلقاً، أی من غیر تقیید بشخص أو زمان أو مکان فاذا قلت مخرج فمعناه موضع الخروج المطلق أو زمان الخروج المطلق و لم یعملوها فی مفعول و لا ظرف فلایقولون مقتل زیداً و لا مخرج الیوم لئلایخرج من الاطلاق الی التقیید. کذا فی جاربردی شرح الشافیة. و الفرق بین اسم الزمان و المکان و بین الوصف المشتق یجی ٔ فی فصل الفاء من باب الواو. و الاحسن هو ما قال فی اصول الاکبری من ان اسم الظرف ما یبنی من فعل لیدل علی مکانه أو زمانه و وزنه فی الثلاثی مفعل بفتح العین أو کسرها، ومفعلة بفتح المیم و العین، کمأسدة، و فعال بالکسر و فی غیر الثلاثی المجرد یکون علی وزن اسم مفعوله - انتهی . فعلم من هذا ان اسم الظرف یقال علی معنیین احدهما اعم و الثانی اخص . و بالمعنی الاعم یکون لفظ مع وعند و الیمین و الیوم و نحوها من اسماء الظروف و بالمعنی الاخص لایکون منها. ثم الظرف سواء کان ظرف زمان أو مکان علی نوعین، مبهم و موقت و یسمی محدوداً ایضاً. و اتفق القوم علی ان المبهم من الزمان ما لم یعتبر له حد و لا نهایة کالحین . و المحدود منه ما اعتبر فیه ذلک کالیوم و الشهر. و اما المبهم و المحدود من المکان فقد اختلف فی تفسیرهما فقال اکثر المتقدمین ان المبهم من المکان هو الجهات الست ّ. و هی أمام و خلف و یمین و شمال و فوق و تحت . و المحدود منه بخلافه . ای ما سوی تلک الجهات و یرد علیه عند و لدی و لفظ مکان و ما بمعناه من ذوات المیم و ما بعد دخلت و المقادیر الممسوحة کالفرسخ و المیل . فانها تکون منصوبة بتقدیر فی و لا تکون المحدودات منصوبة بتقدیر فی . فینبغی ان تکون مبهمات مع انه لایصدق حد المبهم علیها. و اجیب بانها محمولة علی الجهات الست ّ لمشابهتها ایاها. اما فی الابهام کعند و لدی و دون و سوی و اما فی کثرةالاستعمال کلفظ مکان و ما بعد دخلت و اما فی الانتقال کالمقادیر الممسوحة فان تعین ابتداء الفرسخ مثلاً لایختص مکاناً دون مکان بل یتحول ابتداء کتحول الخلف قداماً و الیمین شمالاً. فان قلت المکان المبهم کاسمه یتناول کل مکان لیس له حد یحصره فما بال المتقدمین فسروه بالجهات الست ّ التی هی بعض الامکنة المبهمة ثم احتاجوا الی حمل غیرها علیها. قلت کأنهم جعلوا الجهات الست ّ اصلاً لتوغّلها فی الابهام لایحاذیها غیرها فیه، حتی انها لاتتعرف بالاضافة الی المعرفة و قیل المبهم هو النکرة و المحدود بخلافه . و یرد علی هذا التفسیر خلفک و امامک فانهما من المبهمات و ایضاً لا خلاف فی انتصابهما علی الظرفیة بتقدیر فی . مع انه لایصدق حد المبهم علیهما. و اجیب بان ّ الجهات لاتتعرف بالاضافة فلایخرج عن تفسیر المبهم بالنکرة خلفک و امامک و نحوهما وقیل المبهم هو غیر المحصور و المحدود هو المحصور. ویرد علیه نحو فرسخ فانه من المبهمات لانتصابه علی الظرفیة بل یقال ان المکان الذی ینصب بتقدیر فی نوعان المبهم و المحدود الذی یتبدل ابتدائه و انتهائه لمشابهتهما الزمان الذی هو مدلول الفعل و وجه المشابهة التغیر و التبدل فی نوعی المکان کما فی الازمنة الثلاثةفخروج المحدود کالفرسخ من تفسیر المبهم لایضره . و قال ابن الحاجب و صاحب اللباب : المبهم ما ثبت له اسم بسبب امر خارج عن مسماه . فالفرسخ داخل فیه . لان المکان لم یصر فرسخاً بذاته بل بالقیاس المساحی الذی هو خارج عن مسماه و کذا الجهات . فانها تطلق علی هذه الامکنة باعتبار ما یضاف الیه لا بذاته . و الموقت ما له اسم باعتبار ما دخل فی مسماه کاعلام المواضع نحو البلد و السوق و الدار. فانها اسماء لتلک المواضع باعتبار اشیاء داخلة فیها کدور فی البلد و البیت فی الدّار ثُم هذا التفسیر یشتمل نحو جوف البیت و خارج الدار و داخلها و نحو المغرب و المقتل و المأکل و المشرب مع انها لاتنتصب بالظرفیة. فلایقال زید خارج الدار و جوف البیت بل فی خارجها و فی جوفه . و کذا لایقال قمت مضرب زید و مقتله . و ایضاً یشکل بانهم صرّحوا ان الدار اسم للعرصة دون البناء، حتی لو حلف لایدخل هذه الدار، فدخل فیها بعدما صارت صحراء یحنث . فلاتکون البیوت التی استحقت اسم الدار ابتداء باعتبارها داخلة فی مسماه . ثُم کل من المبهم و الموقت، اما مستعمل اسماً بان یقع مرفوعاً و منصوباً علی غیر الظرفیة و مجروراً و ظرفاً بان یقع منصوباً علی الظرفیة و یسمی حینئذ منصرفاً. و هو ما جاز اَن تعقب علیه العوامل کالیوم و الحین، یقال هذا حین و رأیت حیناً و عجبت من حین . أو مستعمل ظرفاً لا غیر و یسمی غیرمنصرف و هو ما لزم فیه النصب بتقدیر فی، مثل سوی و کل من الصنفین یجوز ان یکون منصرفاً و غیرمنصرف . هذا کله خلاصة ما فی شروح الکافیة و العباب . و منها المفعول فیه . قال فی الضوء: المفعول فیه یسمی ظرفاً - انتهی . و هذا المعنی اخص من الاول مطلقاً کما لایخفی . و منها المفعول به بواسطة حرف الجر. قال فی العباب : المفعول به الذی بواسطة حرف الجر فی اصطلاحهم یسمی ظرفاً ایضاً. ثم الظرف سواء کان مفعولاً فیه أو مفعولاً به بواسطة حرف الجر قسمان : لغو و مستقر. فاللغو ما کان عامله شیئاً خارجاً عن مفهوم الظرف، أی لیس الظرف بمتضمن له، سواء کان ذلک الشی ٔ فعلاً أو معناه و سواء کان مذکوراً نحو مررت بزید أو مقدراً نحو من لک أی من یضمن لک . و انما سمی به لأنّه زائد غیر محتاج الیه . و المستقر ما کان عامله بمعنی الاستقرار و الحصول و نحوهما من الافعال العامة، کالثبوت و الوجود مقدراً غیر مذکور، نحو زید فی الدار. و انما سمی به لان الفعل و هو استقر أو معناه مقدر قبله نحو کان زید فی الدار أو استقر فی الدار. فالظرف مستقر فیه بحذف عامل الظرف و سد الظرف مسده . و استتر الضمیر فیه . و قیل لابد فی المستقر من ثلاثة امور. الاول کون المتعلق متضمناً فیه . فخرج بهذا نحو مررت بزید، لان المرور لیس متضمناً فی الجار بل هو امر خارج . و الثانی ان یکون المتعلق من الافعال العامة. فخرج زید فی الدار، اذا قدر متعلقه خاصاً. و الثالث ان یکون المتعلق غیر مذکور. فخرج زید حاصل فی الدار. و قال ابن جنی : یجوز اظهار عامله و لا حجة له . و اما قوله تعالی : فلما رآه مستقراً عنده، فلیس مستقراً فی هذا القول بمعنی کائناً حتی یکون حجة له . و هذا هو المشهور فیمابین النحاة. و ذکر السید السند فی حواشی الکشاف : ان المستقر ما کان متعلقه مقدراً سواء کان عاماً نحو زید فی الدار أی حاصل فیها أو خاصاً نحو زید فی البصرة أی مقیم فیها. و اللغو ما یقابله - انتهی . اعلم ان المشهور فی تقدیر عامل الظرف الفعل أو الاسم المنکر. و قد یقدر عامله اسماً معرفاً بسبب ما، ککونه صفة معرفة. و علی هذا قیل قولهم : الفصاحة فی المفرد بمعنی الفصاحة الکائنة فی المفرد کما فی حواشی المطول . الظرف عند الاصولیین ما کان محلاً لشی ٔ و فضل علی ذلک الشی ٔ کالوقت للصلوة فان ساواه سمی معیاراً لا ظرفاً کوقت الصوم فانه الذی یستقر فیه . و لایفضل عنه فیتقدر به فیطول بطوله و یقصر بقصره . هکذا یستفاد من التلویح و حواشی المنار. و فی کلیات ابی البقاء: الظرف الزمانی نحوامس و الاَّن و متی و ایان و قط المشددة و اذا و اذ المقتضیة جواباً. و الظرف المکانی، نحو لدن و حیث و أین و هنا و ثمة و اذا المستعملة بمعنی ثمة. و المشترک نحو قبل و بعد و اذا قصد فی باء المصاحبة مجرد کون معمول الفعل مصاحباً للمجرور زمان تعلق ذلک الفعل به من غیر قصد مشارکتها فی الفعل، فمستقر فی موضع الحال . سمی مستقراً لتعلقه بفعل الاستقرار و هو مستقر فیه حذف للاختصار و اذا قصد کونه مصاحباً له فی تعلق الفعل فلغو. ففی قوله اشتر الفرس بسرجه علی الاول، السرج غیر مشتری و لکن الفرس کان مصاحباً للسرج حال الشراء و التقدیر اشتر الفرس مصاحباً للسرج . و علی الثانی کان السرج مشتری و المعنی اشترهما معاً. و الظرف المستقر اذا وقع بعد المعرفة یکون حالاً، نحو مررت بزید فی الدار، أی کائناً فی الدار و یقع صلة نحو: و له من فی السموات و الارض و من عنده لایستکبرون . و خبراً نحو فی الدار زید ام عندک . و بعداً لقسم بغیر الباء نحو و اللیل اذا یغشی . و یکون متعلقه مذکوراً بعده علی شریطة التفسیر، نحو: یوم الجمعة صمت . و یشترطفی الظرف المستقر ان یکون المتعلق متضمناً فیه . و ان یکون من الافعال العامة. و ان یکون مقدراً غیر مذکور. و اذا لم توجد هذه الشروط فالظرف لغو. و قال بعضهم ما له حظ من الاعراب و لایتم الکلام بدونه، بل هو جزء الکلام فهو مستقر و لیس اللغو کذلک لأنّه متعلق لعامله المذکور و الاعراب لذلک العامل و یتم الکلام بدونه، و حق اللغو التأخیر لکونه فضلة و حق المستقر التقدیم لکونه عمدة و محتاجاً الیه . و مما ینبغی ان ینبه علیه هو ان ّ مثل کان أو کائن المقدر فی الظروف المستقرة لیس من الافعال الناقصة بل من التامة، بمعنی ثبت و حصل أو ثابت و حاصل و الظرف بالنسبة الیه لغو. و الا لکان الظرف فی موقع الخبر له، فیکون بالنسبة الیه مستقراً لا لغواً، لان اللغو لایقع موقع متعلقه فی وقوعه خبراً، فیلزم ان یقدر کان او کائن آخر - انتهی .<br /></font></div>'),
(178889, 'ظرف', '<span class=\"hlight\">ظرف .</span> <font color=\"DarkGreen\"><b>[ ظُ رُ ]</font></b> (ع ص، اِ) ج ِ ظریف .<br /></font></div>'),
(178890, 'ظرف زرحل', '<span class=\"hlight\">ظرف زرحل .</span> <font color=\"DarkGreen\"><b>[ ظَ ف ِ زَ ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) ظرفی که زر محلول در آن انداخته و در نقش کتابت به کار برند. ملامفید راست <span class=\"hlight\">:</span> <br />نقاش من که هر دو جهان زو مشکّل است <br />مه در نگارخانه ٔ او ظرف زرحل است .<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(178891, 'ظرف شب', '<span class=\"hlight\">ظرف شب .</span> <font color=\"DarkGreen\"><b>[ ظَ ف ِ ش َ ]</font></b> (ترکیب اضافی، اِ مرکب ) اصیص . ظرفی که در اطاق شب هنگام برای ادرار بول پیران و بیماران به کار است .<br /></font></div>'),
(178892, 'ظرفش لبریز شدن', '<span class=\"hlight\">ظرفش لبریز شدن .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ل َ ش ُ دَ ]</font></b> (مص مرکب ) عمرش به سر رسیدن . پیمانه اش پر شدن . <BR><font color=\"Blue\">◄</font> طاقت و شکیب او به پایان رسیدن . طاقتش طاق شدن .<br /></font></div>'),
(178893, 'ظرفیت', '<span class=\"hlight\">ظرفیت .</span> <font color=\"DarkGreen\"><b>[ ظَ فی ی َ ]</font></b> (ع مص جعلی، اِمص ) گنجایش . بارگیر. وُسع. <BR><font color=\"Blue\">◄</font> آب گیر. <BR><font color=\"Blue\">◄</font> استعداد. قوّة.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظرفیت الکتریکی </span> ؛ مقدار الکتریسیته ای است که باید به یک جسم داد تا سطح آن از صفر به یک وُلت برسد. واحد آن فاراد است . رجوع به فاراد شود.<br /></font></div>'),
(178894, 'ظرفیت نداشتن', '<span class=\"hlight\">ظرفیت نداشتن .</span> <font color=\"DarkGreen\"><b>[ ظَ فی ی َ ن َ ت َ ]</font></b> (مص مرکب منفی ) حوصله نداشتن . <BR><font color=\"Blue\">◄</font> استعداد نداشتن . محسن تأثیر گوید <span class=\"hlight\">:</span> <br />مغلوب گشت دلبر غالب حریف من <br />ظرفیتی نداشت نگار ظریف من .<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(178895, 'ظروری', '<span class=\"hlight\">ظروری .</span> <font color=\"DarkGreen\"><b>[ ظَ رَ را ]</font></b> (ع ص ) زیرک و ماهر.<br /></font></div>'),
(178896, 'ظروف', '<span class=\"hlight\">ظروف .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظَرف <span class=\"hlight\">:</span> و چندان نثارها و هدیه ها و ظروف و ستور آورده بودند که از حد و اندازه بگذشت . (تاریخ بیهقی ).<BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ ظریف . رجوع به ظریف شود.<br /></font></div>'),
(178897, 'ظروف مرتبطه', '<span class=\"hlight\">ظروف مرتبطه .</span> <font color=\"DarkGreen\"><b>[ ظُ ف ِ م ُ ت َ ب ِ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (ترکیب وصفی، اِمرکب ) ظروفی که از قسمت تحتانی به توسط مجرائی به یکدیگر متصل باشند به نحوی که چون در یکی مایعی ریزند به دیگر ظروف درآید و با وجود اختلاف شکل آنان در همگی به یک سطح قرار گیرد.<br /></font></div>'),
(178898, 'ظری', '<span class=\"hlight\">ظری .</span> <font color=\"DarkGreen\"><b>[ ظَرْی ْ ]</font></b> (ع مص ) جاری و روان گردیدن : ظری بطنه ؛ رفت شکم او.<br /></font></div>'),
(178899, 'ظری', '<span class=\"hlight\">ظری .</span> <font color=\"DarkGreen\"><b>[ ظَ را ]</font></b> (ع مص ) زیرک گردیدن .<br /></font></div>'),
(178900, 'ظریب', '<span class=\"hlight\">ظریب .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) نام موضعی که قبیله ٔ طی ّ پیش از فرودآمدن به جبلین درآنجا سکونت داشته اند. معبدبن قرط گوید <span class=\"hlight\">:</span> <br />الایا عین جودی بالصبیب <br />و بکّی ان بکیت بنی عجیب <br />و کانوا اِخوة لبنی عداء<br />ففرق بینهم یوم عصیب <br />فقد ترکوا منازلهم و بادوا<br />کمنزل ظبی مبنی ّ ظریب .<br />دیگری گوید <span class=\"hlight\">:</span> <br />اجعل ظریباً کحبیب ینسی <br />لکل ّ قوم مصبح و ممسی .<br /><font color=\"Red\">(معجم البلدان ).</font><br /></font></div>'),
(178901, 'ظریبة', '<span class=\"hlight\">ظریبة.</span> <font color=\"DarkGreen\"><b>[ ظُ رَ ب َ ]</font></b> (اِخ ) ناحیتی است در طائف . (معجم البلدان ).<br /></font></div>'),
(178902, 'ظریر', '<span class=\"hlight\">ظریر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) زمین سنگناک . <BR><font color=\"Blue\">◄</font> زمین درشت . <BR><font color=\"Blue\">◄</font> مناره ای که بدان راه شناسند. ج، ظُرّان، اَظِرّة. اناصیب .<br /></font></div>'),
(178903, 'ظریف', '<span class=\"hlight\">ظریف .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) سبکروح . (مهذب الاسماء). خوش طبع. <BR><font color=\"Blue\">◄</font> تیزدل . (مهذب الاسماء). زیرک . کیّس . (منتهی الارب ). دانا <span class=\"hlight\">:</span> <br />دست بر هم زند طبیب ظریف <br />چون خرف بیند اوفتاده حریف .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> خوشروی . زیبا. <BR><font color=\"Blue\">◄</font> بلیغ. <BR><font color=\"Blue\">◄</font> چابک . مزلّم . خوش لباس . خوش جامه . ریاش <span class=\"hlight\">:</span> و او جوانی ظریف بود و جامه های نیکو پوشیده داشت . (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).شیخ ما را پرسیدند در شهر ما ظریف کیست ؟ گفت لقمان .گفتند... در شهر ما خود هیچکس بشولیده تر از او نیست . شیخ گفت ... ظریف پاکیزه باشد و پاکیزه کسی بود که ... (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>). <BR><font color=\"Blue\">◄</font> خوش گفتار. شیرین زبان . شیرین گفتار. خوش زبان . بزیع. لطیفه گوی . بذله گوی <span class=\"hlight\">:</span> ظریفان گفته اند به سیری مردن به که گرسنگی بردن . (گلستان ). یکی آنکه گمان بردم که آفتاب برآمده و دیگر آنکه ظریفان گفته اند... (گلستان ). ج، ظُرفاء، ظُرُف، ظریفون، ظِراف، ظروف .<br /></font></div>'),
(178904, 'ظریف زادن', '<span class=\"hlight\">ظریف زادن .</span> <font color=\"DarkGreen\"><b>[ ظَ دَ ]</font></b> (مص مرکب ) اظراف . (تاج المصادر).<br /></font></div>'),
(178905, 'ظریف شدن', '<span class=\"hlight\">ظریف شدن .</span> <font color=\"DarkGreen\"><b>[ ظَ ش ُ دَ ]</font></b>(مص مرکب ) (... کودک ) تبزّع . (تاج المصادر). بزع .<br /></font></div>'),
(178906, 'ظریف منظر', '<span class=\"hlight\">ظریف منظر.</span> <font color=\"DarkGreen\"><b>[ ظَ م َ ظَ ]</font></b> (ص مرکب ) صاحب دیدار نیکو <span class=\"hlight\">:</span> و در موضع سقاة هر خوش پسری ظریف منظری ... کمر بر میان بسته . (جهانگشای جوینی ).<br /></font></div>'),
(178907, 'ظریفانه', '<span class=\"hlight\">ظریفانه .</span> <font color=\"DarkGreen\"><b>[ ظَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) باظرافت . به وضع خوش . به سبکروحی . به تیزدلی . به شیرین زبانی .<br /></font></div>'),
(178908, 'ظریفة', '<span class=\"hlight\">ظریفة.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (ع ص ) تأنیث ظریف .<br /></font></div>'),
(178909, 'ظریفة', '<span class=\"hlight\">ظریفة.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) کاهنه ٔ حمیریّة زوجه ٔ عمروبن مرتقیابن عامر ماءالسماء. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(178910, 'ظریفون', '<span class=\"hlight\">ظریفون .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص، اِ) ج ِ ظریف .<br /></font></div>'),
(178911, 'ظریفی', '<span class=\"hlight\">ظریفی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) رجوع به حسن چلبی شود.<br /></font></div>'),
(178912, 'ظریفی', '<span class=\"hlight\">ظریفی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) (محمدبیگ ) از مردم ساوه و مرید حریفی است به زمان شاه طهماسب صفوی . وی به هندوستان رفت و بدانجا حرمت بسیار دید. این بیت از اوست :<br />دوش غوغای سگان تو به گوشم آمد<br />مُردم از رشک که آیا که گذشت از کویت .<br /></font></div>'),
(178913, 'ظریفی', '<span class=\"hlight\">ظریفی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) (شیخ عمرافندی ) از شعرای متأخر عثمانی و از مشایخ طریقت سعدیّة، از مردم روسچق . وفات <span class=\"hlight\" dir=\"rtl\">١٢١٠</span> هَ . ق .<br /></font></div>'),
(178914, 'ظریفی', '<span class=\"hlight\">ظریفی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) از شعرای دوره ٔ سلطان بایزیدخان ثانی، از مردم قصبه ٔ کوینک . (قاموس الاعلام ).<br /></font></div>'),
(178915, 'ظریفی', '<span class=\"hlight\">ظریفی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) شاعری از مردم چورلی شاگرد بهشتی . او را دیوانی است به ترکی .<br /></font></div>'),
(178916, 'ظریفی', '<span class=\"hlight\">ظریفی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (حامص ) ظریف بودن . رجوع به ظریف شود.<br /></font></div>'),
(178917, 'ظش', '<span class=\"hlight\">ظش .</span> <font color=\"DarkGreen\"><b>[ ظَش ش ]</font></b> (ع ص ) جای سخت و درشت .<br /></font></div>'),
(178918, 'ظعام', '<span class=\"hlight\">ظعام .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) رسن هودج، یا رسن که بار به وی بندند.<br /></font></div>'),
(178919, 'ظعان', '<span class=\"hlight\">ظعان .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) رسن که بار و هودج به وی بندند.<br /></font></div>'),
(178920, 'ظعاین', '<span class=\"hlight\">ظعاین .</span> <font color=\"DarkGreen\"><b>[ ظَ ی ِ ]</font></b> (ع اِ) رجوع به ظَعائن شود.<br /></font></div>'),
(178921, 'ظعن', '<span class=\"hlight\">ظعن .</span> <font color=\"DarkGreen\"><b>[ ظَ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ظَ ]</font></b> (ع مص ) رفتن . کوچ کردن . از جائی به جائی شدن <span class=\"hlight\">:</span> <br />او نیفتد درگمان از طعنشان <br />او نگردد دردمند از ظعنشان .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(178922, 'ظعن', '<span class=\"hlight\">ظعن .</span> <font color=\"DarkGreen\"><b>[ ظُ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ظُ ]</font></b> (ع اِ) ج ِ ظَعینة. رجوع به ظعینة شود.<br /></font></div>'),
(178923, 'ظعون', '<span class=\"hlight\">ظعون .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) شتر کار کشت و باربردار و شتر هودج کش . شتری که بدان بار بردارند و به کار دارند و هودج بر آن کنند. <BR><font color=\"Blue\">◄</font> اشتر که سفر را دارند.<br /></font></div>'),
(178924, 'ظعین', '<span class=\"hlight\">ظعین .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) رونده و کوچ کننده . (آنندراج ).<br /></font></div>'),
(178925, 'ظعینة', '<span class=\"hlight\">ظعینة.</span> <font color=\"DarkGreen\"><b>[ ظَ ن َ ]</font></b>(ع اِ) هودج . کجابه . کجاوه . <BR><font color=\"Blue\">◄</font> زن مادام که در هودج باشد. ج، ظُعن، ظُعُن، ظعائن، اَظْعان .<br /></font></div>'),
(178926, 'ظف', '<span class=\"hlight\">ظف .</span> <font color=\"DarkGreen\"><b>[ ظَف ف ]</font></b> (ع ص، اِ) زندگانی تلخ و ناخوش . <BR><font color=\"Blue\">◄</font> (اِمص ) پیوسته گرانی نرخ . <BR><font color=\"Blue\">◄</font> (مص ) ظف قوائم بعیر؛ بستن هر چهار پای شتر و فراهم آوردن .<br /></font></div>'),
(178927, 'ظفار', '<span class=\"hlight\">ظفار.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) اظفار. و آن نوعی از بوی خوش است بر شکل ناخن برکنده و در حدیث است : و علیها عقد من جزع ظفار و ارید به العطر المذکور کأنّه یثقب و یجعل فی العقد و القلادة.<br /></font></div>'),
(178928, 'ظفار', '<span class=\"hlight\">ظفار.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) شهری است به یمن نزدیک صنعاء که عود و جزع یمانی بدانجا منسوب است و مسکن ملوک حِمْیَر آنجا بود و «ملک یمن در عهد منوچهر، شمسو بن الاملوک بود بر طاعت او و پسر همچنین و مدینه ٔ ظفار نهاد به یمن اندر». (مجمل التواریخ و القصص ). برخی ظفار را همان صنعاء دانسته اند. اصمعی گوید: مردی از عرب بر ملکی از ملوک حِمْیَر درآمد و او بر سطحی مشرف نشسته بود، عرب را گفت «ثِب ْ» و ثِب ْ به لغت حمیر به معنای اُقعد باشد. آن مرد لغت ایشان نمیدانست، از آنجای بجهید و بیفتاد و اعضایش بشکست . ملک گفت پیش ما عربیت نیست و «من دخل ظَفارِ حَمّرَ»، و این گفته مثل شد. نام این شهر در قدیم ریدان بوده است .<br /></font></div>'),
(178929, 'ظفار', '<span class=\"hlight\">ظفار.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) شهری است از اعمال شحر نزدیک مرباط که قسط را به وی منسوب کنند بدان جهت که از هند اول آنجا برند. این شهر در ساحل دریای هند واقع و بین آن و مرباط پنج فرسنگ است .<br /></font></div>'),
(178930, 'ظفاری', '<span class=\"hlight\">ظفاری .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ص نسبی ) منسوب به ظفار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عود ظفاری یا جزع ظفاری </span> ؛ عود یا جزعی که از ظفار آرند.<br /></font></div>'),
(178931, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف ِ ]</font></b> (ع ص ) ظفیر.ظِفّیر. مردی که به هرچه اراده کند دریابد آن را.<br /></font></div>'),
(178932, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) موضعی است نزدیک شُمیط بین مدینه و شام از دیار فزاره و در آنجاست که ام قرفة، فاطمة بنت ربیعةبن بدر کشته شد. (معجم البلدان ).<br /></font></div>'),
(178933, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع مص ) فروبردن ناخن را در رخسار کسی . <BR><font color=\"Blue\">◄</font> ظفر عین ؛ ناخنه برآوردن چشم . <BR><font color=\"Blue\">◄</font> ماظفرتک عینی منذ زمان ؛ دیری است که ترا ندیده ام . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است .<br /></font></div>'),
(178934, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (ع اِمص ) پیروزی . فیروزی . نصرت .فتح . غلبه . کامروائی . دست یافتن . کامیابی . نجاح . به مراد رسیدن . استیلا. پیروز شدن . پیشرفت <span class=\"hlight\">:</span> <br />به صدر اندر نشسته شهریاری <br />ظفریاری به کنیت بوالمظفر.<br /> <font color=\"Red\">لبیبی .</font><br />کاروان ظفر و قافله ٔ فتح و مراد<br />کاروانگاه به صحرای رجای تو کند.<br /> <font color=\"Red\">منوچهری .</font><br />و به دولت عالی ظفر و نصرت روی خواهد نمود. (تاریخ بیهقی ).با اینهمه در جنگی که کنند ظفر ایشان را باشد. بدا قوما که مائیم که ایزد عزّ ذکره چنین قوم را بر ما مسلط کرده و نصرت میدهد. (تاریخ بیهقی ). چنان دانم که بدان تدبیر راست که کردم ما را ظفر باشد. (تاریخ بیهقی ). قوت پیغامبران معجزات آمد... و قوت پادشاهان ... درازی دست و ظفر و نصرت . (تاریخ بیهقی ).<br />الا انثنیت و فی اظفارک الظفر.<br /> <font color=\"Red\">ابوسهل زوزنی (از تاریخ بیهقی ).</font><br />بساز رزم عدو را که از برای ترا<br />قضا گرفته به کف نامه ٔ ظفر دارد.<br /> <font color=\"Red\">مسعودسعد.</font><br />تا به هر طرف که نشاط حرکت فرماید ظفر و نصرت رایت او را تلقی و استقبال واجب بیند. (کلیله و دمنه ). ظالمان مکار چون هم پشت شوند ظفر یابند. (کلیله و دمنه ). و در اتمام آنچه بر دوستان اقتراع کنند ظفریابد. (کلیله و دمنه ). سباشی تکین بر او ظفر یافت و او را بگرفت و به دونیم کرد. (ترجمه ٔ تاریخ یمینی ). خوارزمیان بر امید ظفر و نصرت پای بیفشردند. (ترجمه ٔتاریخ یمینی ). از آن سفر با موکب ظفر بازگردید. (ترجمه ٔ تاریخ یمینی ). آخر کار، بکتوزون ظفر یافت و سیمجوری هزیمت شد. (ترجمه ٔ تاریخ یمینی ).<br />هست مر هر صبر را آخر ظفر<br />هست روزی بعد هر تلخی شکر.<br /> <font color=\"Red\">مولوی .</font><br />تا رنج نبری گنج برنداری و تا جان در خطر ننهی بر دشمن ظفر نیابی . (گلستان ).<br /><BR><font color=\"Blue\">◄</font> (اِ) زمین هموار و پست گیاهناک .<br /></font></div>'),
(178935, 'ظفر', '<span class=\"hlight\">ظفر.</span><font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) میرزا کاظم کرمانی، خلف میرزا محمدتقی کرمانی . از اکابر محققین است . وی در شباب تحصیل علوم متداوله کرد و در حکمت طبیعی که فن موروثی اوست ماهر و قادر است . هم از آغاز جوانی طالب مطالب عرفانی و به خدمت جمعی از اهل حال و ارباب کمال رسیده و معاشرت ایشان را گزیده . همانا به میرزا محمدحسین رونق کرمانی اخلاص داشته . در کرمان صحبتش اتفاق افتاد درهنگامی که فقیر در آن شهر مریض بود در علاج نهایت دقت فرمود. قصائد خوب و غزلیات مرغوب دارد. از اوست :<br />تو و خار مغیلان زاهدا در طی ّ منزلها<br />من و راه خرابات و طواف کعبه ٔ دلها<br />در این منزل که پرخوف است ما درخواب و همراهان <br />ز خوف رهزنان بستند پیش از وقت محملها.<br /><font color=\"Red\">(از ریاض العارفین رضاقلیخان هدایت ).</font><br /></font></div>'),
(178936, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (ظفرالدین ) شاعری از اهل همدان و در خدمت ملکشاه سلجوقی بوده است . این شعر از اوست :<br />به هنر باش هرچه خواهی کن <br />نه بزرگی به مادر و پدر است <br />نافه ٔ مشک را ببین به مثل <br />کاین قیاسی بدیع و معتبر است .<br /><font color=\"Red\">(از قاموس الاعلام ).</font><br /></font></div>'),
(178937, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (شیخ ...) ابن همام بن سعد الاردستانی . شیخ منتجب الدین در فهرست خویش وی را امام لغت گفته است . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(178938, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (السید ابی الفضل ...) ابن الداعی بن مهدی العلوی العمری الاسترآبادی . فقیه ثقه ٔ صالح از شاگردان شیخ ابوالفتح کراجکی . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(178939, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (شیخ ...) ابن الداعی بن ظفر الحمدانی القزوینی، مکنی به ابوسلیمان . فقیه صالح از شاگردان ابی علی بن شیخ ابی جعفر طوسی است و او را نظمی لطیف است . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(178940, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) ابن احمدبن الحسین الجلیلی النیسابوری . از صوفیه ٔ کبار است و او به اصفهان رفت و درمحرم سال <span class=\"hlight\" dir=\"rtl\">٣٨٢</span> هَ . ق . وفات کرد. حدیث کرد احمدبن الحسین جبیلی النیسابوری : قدم علینا... حدیث کرد ما راابوجعفر محمدبن الحسن بن علی بن عمار المؤدّب در نیشابور، که حدیث کرد ما را عبداﷲبن الحارث الصنعانی ازعبدالرّزاق بن همام از مَعمَر از زُهری از عُروة از عائشه از پیغمبر (ص ) که فرمود: النفح ُ فی الطعام یذهب بالبرکة. رجوع به ذکر اخبار اصفهان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> شود.<br /></font></div>'),
(178941, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف ِ ]</font></b> (اِخ ) قلعه ای است به یمن . (منتهی الارب ).<br /></font></div>'),
(178942, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) نام قلعه ای است از اعمال صنعاء.<br /></font></div>'),
(178943, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (قراح ...) محله ای است به بغداد.<br /></font></div>'),
(178944, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (... الفنج ) از اعمال زبید است .<br /></font></div>'),
(178945, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) دهی است به حجاز.<br /></font></div>'),
(178946, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) موضعی است نزدیک حَوأب در راه بصره به مدینه .<br /></font></div>'),
(178947, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) (بنو...) بطنی از انصار و بطنی از بنی سُلیم .<br /></font></div>'),
(178948, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظُ <span class=\"hlight\" dir=\"rtl\">/</span> ظُ ف ُ <span class=\"hlight\" dir=\"rtl\">/</span> ظِ ]</font></b> (ع اِ) ناخن . ج، اظفار، اظافیر. <BR><font color=\"Blue\">◄</font> کلیل الظُفر و مقَلّم ُالظُفر؛ مرد سست بددل و ذلیل خوار. <BR><font color=\"Blue\">◄</font> ناخنه ٔ چشم . <BR><font color=\"Blue\">◄</font> کمان سوای بستنگاه زه کمان و یا گوشه و نوک کمان . پس گوشه ٔ کمان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ما بالدّار ظُفر؛ احدی در خانه نیست . <BR><font color=\"Blue\">◄</font> رأیته ُ بظفره، أی بنفسه ؛ دیدم خود او را. <BR><font color=\"Blue\">◄</font> کل ذی ظُفر (قرآن <span class=\"hlight\" dir=\"rtl\">١٤٦/٦</span>). در قرآن کریم، شامل ذوات المناسم از انعام و ابل باشد، چه منسم به جای ناخن آنان باشد. ذوظفر؛ صاحب مخلب و چنگال از مرغان و صاحب حافر از دواب و صاحب ناب از سباع . (مهذب الاسماء).<br /></font></div>'),
(178949, 'ظفر', '<span class=\"hlight\">ظفر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) ظفره . فودنج بری . پودنه ٔ بری .<br /></font></div>'),
(178950, 'ظفر دادن', '<span class=\"hlight\">ظفر دادن .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ دَ ]</font></b> (مص مرکب ) اِظفار. تظفیر. مظفر کردن بر. افلاح . (تاج المصادر).<br /></font></div>'),
(178951, 'ظفر یافتن', '<span class=\"hlight\">ظفر یافتن .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ت َ ]</font></b> (مص مرکب ) اِفلاج . اِظفار. بَلل . فَلج . استیلاء. کامیاب شدن . مظفر شدن . غلبه کردن . دست یافتن <span class=\"hlight\">:</span> <br />دلشاد زی و کامروا باش و ظفر یاب <br />بر کام و هوای دل و بر دشمن غدار.<br /> <font color=\"Red\">فرخی .</font><br />مال شد در جهان چو منهزمی <br />تا بر او یافت جود تو ظفری .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(178952, 'ظفرآباد', '<span class=\"hlight\">ظفرآباد.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) قریه ای است به چهارفرسنگی جنوب شیراز. <BR><font color=\"Blue\">◄</font> محله ای است در همدان . <BR><font color=\"Blue\">◄</font> نام محلی کنار راه سنندج و ساوجبلاغ میان دیوان دره و گول تپه در <span class=\"hlight\" dir=\"rtl\">١٠٨٠٠٠</span>گزی سنندج .<br /></font></div>'),
(178953, 'ظفرالطیب', '<span class=\"hlight\">ظفرالطیب .</span> <font color=\"DarkGreen\"><b>[ ظُ رُطْ طی ]</font></b> (ع اِ مرکب ) رجوع به اظفارالطیب و ظفرالعفریت شود.<br /></font></div>'),
(178954, 'ظفرالعفریت', '<span class=\"hlight\">ظفرالعفریت .</span> <font color=\"DarkGreen\"><b>[ ظُ رُل ْ ع ِ ]</font></b> (ع اِ مرکب ) عطر و چ-وب عطری است که ظفرالطیب نیز خوانده شده است و یکی از اجزای روغن مقدس است . (قاموس کتاب مقدس ). اظفارالطیب . <br /></font></div>'),
(178955, 'ظفرالعقاب', '<span class=\"hlight\">ظفرالعقاب .</span> <font color=\"DarkGreen\"><b>[ ظُ رُل ْ ع ُ ]</font></b> (ع اِ مرکب ) «ظفرالعقاب بستانی » شجره ٔ ابی مالک و «ظفرالعقاب بری » ظفرالقِطّ است . رجوع به ظفرالقط شود.<br /></font></div>'),
(178956, 'ظفرالقط', '<span class=\"hlight\">ظفرالقط.</span> <font color=\"DarkGreen\"><b>[ ظُ رُل ْ ق ِطط ]</font></b> (ع اِ مرکب ) قلومانن . نباتی است ساقش مربع مثل ساق باقلی و برگش مثل برگ بارتنگ و در ساق او غلافهای سرکج و آمیخته با گلهائی شبیه به گل سوسن کبود برّی است . در دوم سرد و خشک و باقبض و قاطع رعاف وخون زخمهای تازه و نزف الدم اعضاء باطنی و سینه و اسهال و ذرورِ برگ او جهت التیام جراحات مؤثر است و مضر سفل و مصلحش صمغ و شربتش یک مثقال و بدلش اقاقیاست . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178957, 'ظفرالنسر', '<span class=\"hlight\">ظفرالنسر.</span> <font color=\"DarkGreen\"><b>[ ظُ رُن ْ ن َ ]</font></b> (ع اِ مرکب ) گیاهی است داروئی و آن را قاطانیقی و قاطاننقی نیز نامند. کف العقاب . رجوع به ظفرةالنسر شود.<br /></font></div>'),
(178958, 'ظفران', '<span class=\"hlight\">ظفران .</span> <font color=\"DarkGreen\"><b>[ ظَف ِ ]</font></b> (اِخ ) قلعه ای است در نواحی کاد به یمن . <BR><font color=\"Blue\">◄</font> قلعه ای است در کوه وصاب در یمن نزدیک زبید.<br /></font></div>'),
(178959, 'ظفرانگیز', '<span class=\"hlight\">ظفرانگیز.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ اَ ]</font></b> (نف مرکب ) پیروزی آورنده <span class=\"hlight\">:</span> <br />تیغ حلم از تیغ آهن تیزتر<br />بل ز صد لشکر ظفرانگیزتر.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(178960, 'ظفرتوز', '<span class=\"hlight\">ظفرتوز.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (نف مرکب ) صفت است شمشیر و امثال آن را به معنی ظفراندوز.<br /></font></div>'),
(178961, 'ظفرجوی', '<span class=\"hlight\">ظفرجوی .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (نف مرکب ) طلبنده و جوینده ٔ ظفر و پیروزی <span class=\"hlight\">:</span> <br />بر شخص ظفرجوی فتد لرزه ٔ مفلوج <br />بر لفظ سخنگوی زند لکنت تمتام .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(178962, 'ظفرخان', '<span class=\"hlight\">ظفرخان .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) مظفرشاه اول، از سلاطین گجرات . پسر یکی از افراد طایفه ٔ رجپوت است که اسلام آورد و در سال <span class=\"hlight\" dir=\"rtl\">٧٩٤</span> هَ . ق . به حکومت گجرات نامزد گردید. او در <span class=\"hlight\" dir=\"rtl\">٧٩٩</span> مستقل شد ولی راجه های رجپوت و قبیله ٔ وحشی بیل او را دور کردند و متصرفات وی محدود گردید به قطعه ای کم عرض از خشکی مابین مرتفعات و دریا و با این احوال باز یک قسمت مهم از ساحل غربی هند را تا شبه جزیره ٔ سورت در تصرف داشت . ظفرخان به زودی به وسیله ٔ تسخیر ایدَر و دیو مملکت خود را وسعت بخشید، و جالور را غارت کرد و یک بار هم در سال <span class=\"hlight\" dir=\"rtl\">٨١٠</span>مالوه را متصرف شد. احمدشاه اول جانشین او شهر احمدآباد را ساخت و این شهر بعدها پایتخت سلسله ٔ او و مرکز ولایات احمدآباد در عهد مغول گردید و حالیه نیز ازبلاد معتبر است . (طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span>).<br /></font></div>'),
(178963, 'ظفرخان', '<span class=\"hlight\">ظفرخان .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (اِخ ) رجوع به حسن گانگو علاءالدین ظفرخان شود.<br /></font></div>'),
(178964, 'ظفرقطورا', '<span class=\"hlight\">ظفرقطورا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) شریف گوید: کلمه ای است سریانی . نام گیاهی شعری که بیشتر در اراضی سنگلاخ و کوهستانی و سواحل ماسه ای و هم در بیابانها روید با ساقی درشت و خشن و پوستی نازک و زبر به درازای یک بدَست و نیم و آن را ریشه ای خشبی است که قسمت عمده ٔ آن بر ظاهر زمین پیداست و درون ریشه سرخ و بیرون آن را پوستی سیاه پوشیده است و بر ساق آن شاخهائی روید پراکنده و برگ آن تنک باشد چون برگ درمنه دور از یکدیگر و گل وی به گل اناغالس سرخ شبیه باشد و ثمر آن چون ثمر هوفاریقون است و به زمستان نیز خشک نشود. و تنها پوست و ریشه ٔ آن در داروها به کار است . و آن سرد و خشک باشد دردرجه ٔ سیم و خاصیت آن گوشت آوردن جراحتها باشد و چون نرم بسایند و ببیزند و با انگبین کفک برگرفته بسرشند و از آن معجونی کنند بهترین داروی ریش ها و سحج امعاء و بازداشتن خون بواسیر باشد. (از ابن البیطار).<br /></font></div>'),
(178965, 'ظفری', '<span class=\"hlight\">ظفری .</span><font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) اسم صنفی از اقلیمیای معدنی است که از معدن قدیم و کهنه برمی آید. (فهرست مخزن الادویه ).<br /></font></div>'),
(178966, 'ظفری', '<span class=\"hlight\">ظفری .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ص نسبی ) (عظم ...) رجوع به دمعه ٔ (عظم ...) شود.<br /></font></div>'),
(178967, 'ظفری', '<span class=\"hlight\">ظفری .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ری ی ]</font></b> (ص نسبی ) منسوب به ظفر و هو بطن من الانصار و هو کعب بن الخزرج بن عمروبن مالک بن الاوس واسم ظفر کعب و المشهور بالنسبة الیه یونس بن محمدبن انس بن فضالة الظفری من اهل المدینة روی عن ابیه له صحبة روی عنه فضیل بن سلیمان النمری و حفیده ادریس بن محمدبن یونس الظفری و هو ابومحمد روی عن ادریس یعقوب بن محمد الزهری و ابن ابی فدیک . و قتادةبن النعمان الظفری من بنی ظفر ایضاً من الانصار و ابودرة الحرب بن سمعان بن زرارة البصری شهد مع النبی صلی اﷲ علیه و سلم احداً ذکر ذلک محمدبن جریر الطبری و فی بنی سلیم بنوظفربن الحرب بن لهبةبن سلیم و المنتسب الی الانصار ولاء حطاب بن صالح الظفری الانصاری مولی بنی ظفر یروی عن امه سلامة بنت معقل امراءة من قیس غیلان روی عنه البصریون و قیل ان ظفر بطن من حمیر قاله ابوسعیدبن یونس و قال معاف بن عمران الظفری و ظفر بطن من حمیر هو ظفربن معاویة و المعافی من اهل حمص قدم مصر و کتب عنه و جماعة ببغداد ینتسبون بشرقیها یقال لها الظفریة احدی المحال المعروفة فشیخنا ابوبکر احمدبن ظفربن احمد الغازلی الظفری الشیبانی منها روی لنا عن ابی الغنایم بن المأمون الهاشمی و ابی علی بن البنا المقری و غیرهما مات سنة و ابونصر احمدبن محمدبن عبدالملک الاسدی الظفری دخلت علیه داره بالظفریة و لم یحضر اصلاً قراء علیه (؟) و کان مریضاً فعدته واستجزت منه و کان سمع ابابکر الخطیب الحافظ و ابی الفرج بن المحزقی (؟) و غیرهما و مات سنة <span class=\"hlight\" dir=\"rtl\">٤٣٢</span> و ابومحمدسلیمان بن الحسین الشحام الظفری سمع مع والدی رحمه اﷲ من اصحاب ابی القاسم بن بشران و ابی علی بن شاذان سمعت منه بالظفریة و ابوطلیحة قیس بن عاصم الظفری التمیمی السعدی بصری له صحبة روی عنه الحسن و ابنه حکیم بن قیس و ابن ابنه خلیفةبن حصن و منهم من یروی عن خلیفةبن حصین عن ابیه عن جده قیس بن عاصم و روی عنه شعبةبن النوم . هکذا ذکره ابوحاتم الرازی . (انساب سمعانی ).<br /></font></div>'),
(178968, 'ظفریة', '<span class=\"hlight\">ظفریة.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َری ی َ ]</font></b> (اِخ ) مسجدی است به بغداد. (عیون الانباء).<br /></font></div>'),
(178969, 'ظفریة', '<span class=\"hlight\">ظفریة.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ری ی َ]</font></b> (اِخ ) محله ای است بزرگ در مشرق بغداد و نزدیک آن محله ٔ بزرگ دیگری و بدان قراح ظفر گفته میشود و جماعتی بدانجا منسوبند، از آنجمله ابونصر احمدبن محمدبن عبدالملک الاسدی الظفری که از خطیب ابابکر سماع حدیث دارد و در سال <span class=\"hlight\" dir=\"rtl\">٥٣٢</span> هَ . ق . وفات کرده است و ابوسعد در شیوخ خویش ذکر او آورده است . (از معجم البلدان ).<br /></font></div>'),
(178970, 'ظفف', '<span class=\"hlight\">ظفف .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (ع اِمص ) بسیاری عیال یا تنگی زیست .<br /></font></div>'),
(178971, 'ظفیر', '<span class=\"hlight\">ظفیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) مردی که به هرچه اراده کند دریابد. <BR><font color=\"Blue\">◄</font> نامی از نامهای مردان عَرَب .<br /></font></div>'),
(178972, 'ظفیر', '<span class=\"hlight\">ظفیر.</span> <font color=\"DarkGreen\"><b>[ ظِف ْ فی ]</font></b> (ع ص ) ظَفیر.<br /></font></div>'),
(178973, 'ظفیر', '<span class=\"hlight\">ظفیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) قلعه ای است به یمن .<br /></font></div>'),
(178974, 'ظل', '<span class=\"hlight\">ظل .</span> <font color=\"DarkGreen\"><b>[ ظُل ل ]</font></b> (ع ص، اِ) ج ِ اَظَل ّ.<br /></font></div>'),
(178975, 'ظل', '<span class=\"hlight\">ظل .</span> <font color=\"DarkGreen\"><b>[ ظَل ل ]</font></b> (ع مص ) ظلول . ظَل َّ نهاره یفعل کذا؛ یعنی تمام روز میکند چنین .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178976, 'ظل', '<span class=\"hlight\">ظل .</span> <font color=\"DarkGreen\"><b>[ ظِل ل ]</font></b> (ع اِ) سایه . فی ٔ. مقابل ضِخ ّ و آفتاب و برخی گفته اند ظل سایه ٔ اول روز است و فی ٔ سایه ٔ آخر روز. <BR><font color=\"Blue\">◄</font> پناه . کنف . ج، ظِلال، ظُلول، اظلال، اَظِلّة. (متن اللغة) <span class=\"hlight\">:</span> <br />در ظل فتح یابد عالم لباس امن <br />چون شد برهنه چهره ٔ خورشیدوار تیغ.<br /> <font color=\"Red\">مسعودسعد.</font><br />ز بس بلندی، ظل زمین به من نرسد<br />نه ام سپید صباح است و نه سیاه مسا.<br /> <font color=\"Red\">مسعودسعد.</font><br />کاَّخر بکشد فلک مرا چون من <br />در ظل قبول صدر احرارم .<br /> <font color=\"Red\">مسعودسعد.</font><br />چهار سال در ظل رفاهیت در آن بقعه بنشست . (ترجمه ٔ تاریخ یمینی ). ظل عاطفت الهی زائل . (ترجمه ٔ تاریخ یمینی ).<br />این حلیمه ی ْ سعدی از امّید تو<br />آمد اندر ظل ّ شاخ بید تو.<br /> <font color=\"Red\">مولوی .</font><br />گفتندش کنون که به ظل حمایتش درآمدی و به شکر نعمتش اعتراف کردی چرا نزدیکتر نیائی . (گلستان ). <BR><font color=\"Blue\">◄</font> جنّت . بهشت . مقابل حرور، دوزخ و آتش آن . <BR><font color=\"Blue\">◄</font> راحت . آسودگی . <BR><font color=\"Blue\">◄</font> نعمت . <BR><font color=\"Blue\">◄</font> منفعت . <BR><font color=\"Blue\">◄</font> دود. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> تاریکی . <BR><font color=\"Blue\">◄</font> خیال که از دیو و پری و جز آن پیدا شود. <BR><font color=\"Blue\">◄</font> ارجمندی . <BR><font color=\"Blue\">◄</font> استواری . <BR><font color=\"Blue\">◄</font> ریشه و پرزه ٔ جامه . <BR><font color=\"Blue\">◄</font> شب یا بهره ای از شب . پاره ای از شب . <BR><font color=\"Blue\">◄</font> کالبد و شخص هر چیزی یا پوشش آن . <BR><font color=\"Blue\">◄</font> اول جوانی . <BR><font color=\"Blue\">◄</font> ظل القیظ؛ سختی گرما. <BR><font color=\"Blue\">◄</font> ظل السحاب ؛ آنچه بپوشد آفتاب را از ابر یا سیاهی آن . <BR><font color=\"Blue\">◄</font> ظل السیف ؛ کنایه از قرب و دُنُوّ شمشیر است چندانکه شمشیر بر سر او باشد. <BR><font color=\"Blue\">◄</font> ظل العرش ؛ رحمت خدا یا سایه ٔ طوبی یا سایه ٔ عرش . <BR><font color=\"Blue\">◄</font> ظل النهار؛ رنگ روز است وقتی که آفتاب غالب باشد (شاید ظل گرما یا ظل آفتاب که در میان فارسی زبانان مشهور است همین کلمه باشد، یا آن زِل ّ است با تواردی در معنی بین دو لغت ). <BR><font color=\"Blue\">◄</font> ظل اللیل ؛ تاریکی شب . <BR><font color=\"Blue\">◄</font> و فی المثل : اترکه ترک الظبی ظله ؛ در حق کسی گویند که بسیار نفور و رمنده باشد؛ لان الظبی اذا نفر من شی ٔ لایعود الیه ابداً. <BR><font color=\"Blue\">◄</font> پوشش . اسم است اظلال را.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خاطف ظله </span> . رجوع به خاطف ... شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظل ّ ظلیل </span> ؛ سایه ٔ تمام . رجوع به ظلیل شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظل ّ مبسوط</span> ؛ سایه ٔ گسترده و دراز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظل ممدود</span> ؛ سایه ٔ دراز و همیشه . رجوع به ممدود شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظل و جیب (اصطلاح هندسه )</span> .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ملاعب ظله </span> . رجوع به ملاعب ... شود.<br />صاحب کشاف اصطلاحات الفنون آرد: الظل ّ قیل هو الضوء الثانی و هو الحاصل من مقابلة المضی ٔ بغیره . و قیل هو الضوء الثانی الحاصل من مقابلة الهواء المضی ٔ. فالضوء الحاصل علی وجه الارض حال الاسفار و عقیب الغروب ظل ّ بالتفسیرین . فانه مستفاد من مقابلة الهواء المضی ٔ بالشمس و الحاصل علی وجه الارض من مقابلة القمر ظل علی التفسیر الاول لکون القمر مُضیئاً بالغیر دون التفسیر الثانی، لعدم کون المضی ٔ بالغیر هواء. فالتفسیر الاول اعم مطلقاً من الثانی . ثُم للظّل ّ مراتب کثیرة متفاوتة بالشدة و الضّعف و طرفاه النور و الظلمة فالحاصل فی فناء الجدار اقوی و اشدّ من الحاصل فی البیت، لکونه مستفاداً من الامور المستضیئة من مقابلة الشمس الواقعة فی جوانبه . ثم ّ الحاصل فی البیت اقوی من الحاصل فی المخدع وهو الخزانة، لأن الاول مستفاد من المضی ٔ بالشمس و الثانی مستفاد من الاول فاختلفت احوال هذه الاظلال لاختلاف معداتها قوة و ضعفاً. و کذا الحال فی البیت تختلف شدة و ضعفاً لصغر الکُوّة أی الثقبة و کبرها. فانه کلّما کانت الکوة اکبر کان الظّل ّ الحاصل فی البیت اشدّ و کلما کانت اصغر کان الظل اضعف . فینقسم الظل فی داخل البیت بحسب مراتبه فی الشدة و الضّعف الی غیر النهایة. و لایزال الکل یضعف بسبب صغر الکوة حتی ینعدم بالکلیة و هو الظلمة. کذا فی شرح المواقف فی المبصرات . و قال الریاضیون الظّل ّ هو الخط المستقیم فی السّطح الذی قام علیه المقیاس عموداً بین مرکز قاعدة المقیاس و طرف الخط الشعاعی المار برأس المقیاس عندما یکون مرکز النیر و سهم المقیاس فی سطح واحد. و النّیّر یشتمل الشّمس و القمر. فما فی کلام البعض من التخصیص بالشمس فبناء علی الغالب . و ما وقع من الخط الشعاعی المذکور بین رأس الظّل ّ و بین رأس المقیاس یسمّی قُطرالظّل ّ و خطّالظّل ّ ایضاً و المقیاس هو العمودالقائم علی سطح یکون الظّل ّ فی ذلک السطح سواء کان عموداً علی الافق أو یکون موازیاً للافق . ثُم الظّل ّ قسمان، لأنّه امّا مأخوذ من المقیاس المنصوب علی موازاة سطح الافق کوتد قائم عموداً علی لوح أو جدار قائمین عمودین علی سطح الافق و یسمّی بالظّل ّ الاول، لابتدائه فی اول طلوع النَّیّر و بالظّل ّ المعکوس و المنکوس ایضاً لکونه معکوساً فی الوضع، رأسه الی تحت و بالمنتصب ایضاً لکونه قائماً علی سطح الافق منتصباً علیه و بالظّل ّ المستعمل ایضاً کما فی بعض رسائل الاسطرلاب و بالظّل ّ المطلق ایضاً کما فی الزّیج الایلخانی حیث قال : ظل اول در اعمال نجومی به کار آید و ظل ّ مطلق آن را خوانند. و ظل ّ دوم در معرفت اوقات به کار آید - انتهی . لکن این در عرف منجمان است، اما در عرف اهل هیئت چون ظل ّ مطلق گویند مراد ظل ّ دوم بود غالباً، بلکه ظل ّ دوم غایت ارتفاع . مثلاً گویند که چون عرض بَلَد زیاده از میل کلی بود ظل ّ همیشه در جانب شمال بود، مراد از ظل ّ دوم غایت ارتفاع است . کذا ذکر عبدالعلی البیرجندی فی شرح زیج الغبیکی . و اما مأخوذ من المقیاس القائم عموداً علی الافق، و یسمی بالظّل ّ الثّانی لکونه ثانیاً بالقیاس الی الاوّل و بالظّل المستوی ایضاً لاستوائه فی الوضع و انطباقه علی سطح الافق و بالظّل ّ المبسوط لانبساطه علی سطح الافق . هذا هو المشهور. و بعضهم یسمی الظّل ّ المستوی اوّلاً و المعکوس ثانیاً، لان ّ المستوی یعرف اول الامر بلا تأمّل بخلاف المعکوس فانه یحتاج فی معرفته الی مزید تأمل . و الظّل ّ الاول یبتدی فی اوّل طلوع النّیّر یزید شیئاً فشیئاً و غایة زیادته فی نصف النهار ثم ّ یتناقص تدریجاً حتی ینعدم عند وصول النّیّر الی الافق عند الغروب . فان کان النّیّر فی نصف النّهار علی سمت الرّأس کان الظّل ّ الاوّل غیر متناه، یعنی انّه لو کان بازائه جسم غیر متناه قابل للنور لکان مستظلاً بظل ّ غیر متناه . و الظل الثّانی یکون عند طلوع النّیّر غیر متناه ثم یتناقص الی بلوغ النیر نصف النهار فهناک غایة النقصان . ثم یتزاید شیئا فشیئاً الی ان یصیر غیر متناه عند غروب النّیّر. فان کان النیر فی نصف النهار علی سمت الرأس لم یوجد الظل الثانی اصلاً. و قد یقسم مقیاس الظل الثانی باثنی عشر قسماً و یسمّی اقسامه اصابع، لان ّاثناعشر اصبعاً مقدار شبر. و هو غالب مقدار المقیاس . فان ّ من اراد ان ینصب عموداً علی سطح الافق أو علی سطح قائم علیه فانّه فی الغالب یتوخی ان یکون مقداره شبراً. و قد یقسم سبعة اقسام أو ستة و نصفاً. و تسمّی اقسامه حینئذ اقداماً، لان ّ طول معتدل القامة ستَّة اقدام و نصف قدم الی سبعة اقدام . مع ان ّ الانسان عند معرفة ان ّ ظل الشی ٔ هل هو مثله یعتبر ذلک بقامته ثم باقدامه . و قد یقسم بستّین قسماً و تسمّی اقسامه حینئذ اجزاء. و قد تؤخذ درجة واحدة تجوزاً. و هذا من مخترعات الاستاذ ابی ریحان البیرونی . فانّه قد اخذ المقیاس ستین دقیقة لاجل سهولة الضّرب و القسمة. و اما مقیاس الظل الاول فقد جرت العادة بتقسیمه ستّین قسماً. و اما اصحاب صنعة الاسطرلاب فکما یقسمون مقیاس الظل الثانی بالاصابع و الاقدام کذلک یقسمون مقیاس الظل الاول بالاصابع و الاقدام بلا تفاوت . ثم الظل ابداً یقدر بما یقدر به المقیاس . فعلی الاول یسمی ظل ّ الاصابع و علی الثّانی ظل ّ الاقدام و علی الثالث ظل ّ الستّینی . ثم ّالظّل ّ الثانی اذا انتهی فی النّقصان و ذلک امّا بان ینتفی الظّل ّ بالکلیة ان کان النّیّر فی غایة ارتفاعها علی سمت الرأس ثم یبتدی فی الحدوث و امّا بان یبقی منه مقدار هو اقل مقادیره فی ذلک الیوم، ثم ّ یشرع فی الزّیادة فهو اول الزوال و هذا الظّل ّ الحادث او الزائد یسمی قدر الزّوال و فی ٔ الزوال . و اعلم ان الظّل ّ الاول لکل قوس هو الخط الذی یماس احد طرفی تلک القوس مابین نقطة التماس و بین تقاطع ذلک الخط مع قطر یمر بالطرف الاَّخر من تلک القوس . هکذا یستفاد من کلام عبدالعلی البیرجندی فی تصانیفه و السّید السّند فی شرح الملخص . و ظل سُلّم عبارت است از مربعی که حادث شود در پشت حجره ٔ اسطرلاب در ربعی که در آن اجزاء ظل نقش کنند. و آن ربع مقابل ربع ارتفاع میباشد. و کیفیت احداث آن مربع این است که این ربع را به دو قسم متساوی منقسم سازند، پس از ملتقای قسمین یعنی از نصف آن ربع دو عمود اخراج کنند، یکی بر خط علاقه، دوم بر خط مشرق و مغرب، اول عمود اقسام ظل مستوی، دوم عمود اقسام ظل ّ معکوس . و هر دو عمود را به اصابع یا به اقدام و یا به اجزاء قسمت کنند و علامات بر آن نبشته دارند. یکی را ابتدا از خط علاقه باشد و آن ظل مستوی بود و دیگری را ابتدا از خط مشرق و مغرب و این ظل معکوس بود. پس شکلی متوازی الاضلاع المتساویة که حاصل شود از این دو عمود و بعض خط علاقه و بعض خط مشرق و مغرب آن را ظل ّ سُلّم خوانند، از جهت انحراف که در قسمت این دو عمود واقع میشود. کذا قیل و الظّل ّ فی اصطلاح المشایخ هو الوجود الاضافی الظاهر بتعینات الاعیان الممکنة و احکامها التی هی معدومات ظهرت باسمه النّور الذی هو الوجود الخارجی المنسوب الیها. فیستر ظلمة عدمیّتها النور الظاهر بصورها صار ظلاً لظهور الظل بالنور و عدمیته فی نفسه . قال اﷲ تعالی : اء لم تر الی ربک کیف مد الظل (قرآن <span class=\"hlight\" dir=\"rtl\">٤٥/٢٥</span>)؛ أی بسط الوجود الاضافی علی الممکنات . فالظلمة بازاء هذا النور هو العدم . و کل ظلمة فهو عبارة عن عدم النور عما من شأنه ان ینور. و لهذا سمی الکفر ظلمة لعدم نور الایمان عن قلب الانسان الذی من شأنه ان یتنور به . قال اﷲ تعالی : اﷲ ولی الذین آمنوا یخرجهم من الظلمات الی النور. الاَّیة.(قرآن <span class=\"hlight\" dir=\"rtl\">٢٥٧/٢</span>). کذا فی اصطلاحات الصوفیة - انتهی .<br />ابوریحان بیرونی در کتاب التفهیم درباره ٔ ظل (سایه ) آرد: سایه چند گونه است ؟ دو گونه است : یکی آنک مقیاس او عمودی باشد بر روی زمین راست و هموار کرده، و او را بسیط خوانند و نیز مستوی، زیرا که سایه از وی بر سطح افق گسترده بود. و گونه ٔ دوم آنک مقیاس او عمودی بود بر دیواری، رویش برابر روی آفتاب و او را منتصب خوانند، زیرا که این سایه همچون بر پای ایستاده بود بر زمین، و نیز اورا معکوس خوانند، ازیراک سر او سوی زمین بود نگون . و نیز درباره ٔ ظل نصف النهار گوید: چند گونه است سایه ٔ نیمروزان و ارتفاع او؟ سر سایه ٔ نیمروزان همیشه سوی شمال بود اندر آن شهرهائی که عرضشان افزونتر بود از میل بزرگ . و بدین شهرهاارتفاع نیمروزان جنوبی بود، چنانک تمام ارتفاع دوری آفتاب بود از سمت الرأس سوی جنوب و به فلک نصف النهار آفتاب را سه ارتفاع بود، یکی بزرگترین به تابستان چون به سرطان رسد، و سایه ٔ او خردترین سایه ها. و دیگر خردترین ارتفاع به زمستان چون به سر جدی رسد و سایه ٔ او درازترین سایه های نیمروزان . و سیم واسطه است میان آن دو ارتفاع و با تمام عرض البلد راست بود و سایه ٔ او را ظل الاستواء و ظل الاعتدال خوانند، زیرا که او و ارتفاعش آنگاه باشند که آفتاب به سر حمل یا به سر میزان رسد. و اما بدان شهرها که عرض با میل بزرگ راست بود همان است که گفتیم، مگر ارتفاع سر سرطان که نود راست بود، نه شمالی و نه جنوبی و آن هنگام سایه ٔ نیمروزان هیچ نبود و نیست شود. و اما بدان شهرها که عرضشان کمتر است از میل بزرگ، حال ارتفاع و سایه ٔ زمستان و بهارگاه هم بر این قیاس بود که پیش گفتیم . فاما ارتفاع سر سرطان از شمال بود نه از جنوب، زیرا که چون آفتاب از سوی شمال آغازد برآمدن و نیز چون از شمال آغازد فرودآمدن و میلش همچند آن شهر شود، بر سر ایشان بیستد و سایه ٔ نیمروزان باطل گردد و چون میلش از عرض شهر بیفزاید از سمت الرأس سوی شمال بگذرد و ارتفاع نیمروزان از سوی شمال گردد. و تمامش بعد آفتاب بود از سمت الرأس بدان جهت . و آن وقت ارتفاع نصف النهار بفزاید، چنانک از جنوب همی فزود، و لکن کمتر همی شود تا به سر سرطان، آنگاه از آنجا آغازد فزودن . و چون ارتفاع از سوی شمال بود سر سایه سوی جنوب بود. و زین قِبَل آن شهرها را دوسایه خوانند، زیرا که سر سایه ٔ نیمروزان هم به شمال بود و هم به جنوب . ظل نماز دیگر کدام است ؟ این به حسب رأی و مذهب امامان است اندر آخر وقتهای نماز پیشین و اول وقتهای نماز دیگر و آخرش، چون روزی مقدار سایه ٔ نیمروزان دانی و او را فی ءالزوال خوانند و آنگاه بر وی یک بار چند مقیاس بفزایی و سایه ٔ او بیابی و رصد کنی تا بدان مقدار رسد که حاصل کردی آن اول نماز دیگر باشد اندر آن روز نزدیک امامان حجاز. و این سایه را زیادةالمثل خوانند و به وی اندر آلتها نویسند اول وقت نماز دیگر. و اگر برفی ٔ زوال دو بار همچند مقیاس بفزایی و آنگاه سایه رصد کنی تا بدان مقدار شود، آن وقت نماز دیگر بود نزدیک امامان عراق . و او را زیادةالمثلین خوانند و اندرروی آلتها نویسند آخر نماز دیگر.<br /></font></div>'),
(178977, 'ظل ا', '<span class=\"hlight\">ظل ا.</span> <font color=\"DarkGreen\"><b>[ ظِل ْ لُل ْ لاه ]</font></b> (ع اِ مرکب ) سایه ٔ خدا.صفتی است که شاهان را دهند و صاحب آنندراج گوید: و به اصطلاح پادشاه را گویند، چه سایه ٔ هر شیئی صاحب اوست و حکایت میکند از ذات آن شخص . پادشاه نیز همین حال را دارد به ذات الهی که انتظام مملکت به ذات اوست چنانکه انتظام وجود ممکنات به وجود باری تعالی است .<br /></font></div>'),
(178978, 'ظل السلطان', '<span class=\"hlight\">ظل السلطان .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ لُس ْ س ُ ]</font></b> (اِخ ) مسعودمیرزا، فرزند ناصرالدین شاه (<span class=\"hlight\" dir=\"rtl\">١٢٦٦</span>- <span class=\"hlight\" dir=\"rtl\">١٣٣٦</span> هَ . ق .).<br /></font></div>'),
(178979, 'ظل اله', '<span class=\"hlight\">ظل اله .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ُ اِ لاه ]</font></b> (ع اِ مرکب ) هو الانسان الکامل المتحقّق بالحضرة الذاتیة. کذا فی اصطلاحات الصوفیة. (کشاف اصطلاحات الفنون ). و شاید کلمه ظل اﷲ بوده و طابع غلط کرده است .<br /></font></div>'),
(178980, 'ظل اول', '<span class=\"hlight\">ظل اول .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ِ اَوْ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) هو العقل الاول لأنّه اول عین ظهرت بنوره تعالی و قبلت صورة الکثرة التی هی شؤون الوحدة الذاتیة. کذا فی اصطلاحات الصوفیة. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178981, 'ظل تمام', '<span class=\"hlight\">ظل تمام .</span> <font color=\"DarkGreen\"><b>[ظِل ْ ل ِ ت َ ]</font></b> (ترکیب وصفی، اِ مرکب ) خط مماس با دایره که متمم زاویه باشد.<br /></font></div>'),
(178982, 'ظل حق', '<span class=\"hlight\">ظل حق .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ِ ح َق ق <span class=\"hlight\" dir=\"rtl\">/</span> ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از خلیفه و پادشاه باشد.<br /></font></div>'),
(178983, 'ظل خدا', '<span class=\"hlight\">ظل خدا.</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ِ خ ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) ظل ّ حق . (برهان قاطع).<br /></font></div>'),
(178984, 'ظل زمین', '<span class=\"hlight\">ظل زمین .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ِ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از شب است . (برهان قاطع).<br /></font></div>'),
(178985, 'ظل ظلیل', '<span class=\"hlight\">ظل ظلیل .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ِ ظَ ]</font></b>(ترکیب وصفی، اِ مرکب ) سایه که دایم ماند و سایه ٔ کشیده و دراز و سایه ٔ تمام و کمال . رجوع به ظل شود.<br /></font></div>'),
(178986, 'ظلاع', '<span class=\"hlight\">ظلاع .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) بیماریی است در پای ستور نه از جهت رنج راه .<br /></font></div>'),
(178987, 'ظلال', '<span class=\"hlight\">ظلال .</span> <font color=\"DarkGreen\"><b>[ ظَل ْ لا <span class=\"hlight\" dir=\"rtl\">/</span> ظَ ]</font></b> (اِخ ) آبی است نزدیک ربذة و به قول بعضی وادیی است در شربّة. ابوعبید گوید: ظلال ُ سَوان، به جانب چپ طخفة وقتی که به سوی مکه روی کنی و متعلق به بنی جعفربن کلاب است . این کلمه را به طاء مهمله نیز نوشته اند. رجوع به معجم البلدان شود.<br /></font></div>'),
(178988, 'ظلال', '<span class=\"hlight\">ظلال .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) هر آنچه سایه افکند بر تو مثل ابر و کوه و غیره . <BR><font color=\"Blue\">◄</font> سایه ٔ ابر.(آنندراج ). <BR><font color=\"Blue\">◄</font> جای سایه دار. (آنندراج ).<br /></font></div>'),
(178989, 'ظلال', '<span class=\"hlight\">ظلال .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) سایبان . <BR><font color=\"Blue\">◄</font> بهشت . <BR><font color=\"Blue\">◄</font> بستان . <BR><font color=\"Blue\">◄</font> سایه ٔ ابر. <BR><font color=\"Blue\">◄</font> ظلال البحر؛ موجهای دریا. <BR><font color=\"Blue\">◄</font> ج ِ ظِل ّ و ظُلّة <span class=\"hlight\">:</span> <br />عشق ربانی است خورشید کمال <br />امر نور اوست خلقان چون ظلال .<br /> <font color=\"Red\">مولوی .</font><br />آدم و نوح و خلیل و موسی و عیسی <br />آمده مجموع در ظلال محمد.<br /> <font color=\"Red\">سعدی .</font><br />ظلال و ظلالات، صاحب کشاف اصطلاحات الفنون گوید: عند الصوفیة عبارة عن الاسماء الالهیة. کذا فی کشف اللغات . و در لطائف اللغات میگوید که : ظلال در اصطلاح صوفیه عبارت است از وجود اضافی ظاهر به تعینات ممکنات .<br /></font></div>'),
(178990, 'ظلالة', '<span class=\"hlight\">ظلالة.</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ ]</font></b> (ع اِ) ابر که سایه ٔ آن را بر زمین بینی، یا ابر که تنهانماید. <BR><font color=\"Blue\">◄</font> کالبد. <BR><font color=\"Blue\">◄</font> دامت ظلالةالظل بالکسر و ظُلّتُه بالضّم ؛ أی ما یستظل به من شجر أو حجر أو غیر ذلک ؛ پاینده باد آنچه در سایه ٔ آن زیستن توان . <BR><font color=\"Blue\">◄</font> ظلة. رجوع به ظل شود.<br /></font></div>'),
(178991, 'ظلام', '<span class=\"hlight\">ظلام .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظُلم .<br /></font></div>'),
(178992, 'ظلام', '<span class=\"hlight\">ظلام .</span> <font color=\"DarkGreen\"><b>[ظَ ]</font></b> (ع اِ) تاریکی، یا تاریکی اول شب <span class=\"hlight\">:</span> <br />خفته از آنی که نبینی ز جهل <br />در دل تاریک همی جز ظلام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />وز دل به چراغ دین و علم حق <br />نتواند برد مر ظلامش را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا مه و مهر فلک والی روزند و شبند<br />تا شب و روز جهان اصل ظلام است و ضیاست .<br /> <font color=\"Red\">مسعودسعد.</font><br />چون زلف تو هواش ظلام از پس ظلام <br />چون کار من زمینش عقاب از پس عقاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />مهری و هرگز مباد هیچ کسوفت <br />دهری و هرگز مباد هیچ ظلامت .<br /> <font color=\"Red\">مسعودسعد.</font><br />از پی یک نور مبین صد ظلام <br />وز پی یک نوش مخور صد شرنگ .<br /> <font color=\"Red\">مسعودسعد.</font><br />چون مهر باد روز بقای تو بی ظلام <br />چون چرخ باد ساعت عمر تو بی غیر.<br /> <font color=\"Red\">مسعودسعد.</font><br />شاه ستارگان ... جمال جهان آرای را به نقاب ظلام بپوشانید. (کلیله و دمنه ).<br />داد به گیتی ظلام سایه ٔ خاک سیاه <br />یافت ز انجم فروغ انجمن کهکشان .<br /> <font color=\"Red\">خاقانی .</font><br />غره ٔ بامداد بر صفحه ٔ ادهم ظلام پیدا گشت . (ترجمه ٔ تاریخ یمینی ).<br />گر تو نشناسی کسی را از ظلام <br />بنگر او را کوش سازیده ست امام .<br /> <font color=\"Red\">مولوی .</font><br />کجا نور باشد چه جای ظلام <br />کجا ماه باشد چه جای سهاست .<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> (مص ) تاریک شدن شب . (تاج المصادر بیهقی ). تاریک شدن . (زوزنی ).<br /></font></div>'),
(178993, 'ظلام', '<span class=\"hlight\">ظلام .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) نوعی از گیاه نرم که شاخ تر و دراز دارد. <BR><font color=\"Blue\">◄</font> آسان و اندک از هر چیزی . <BR><font color=\"Blue\">◄</font> (مص ) به چشم بد دیدن در. و منه : نظر الی ّ ظِلاماً؛ أی شزراً. <BR><font color=\"Blue\">◄</font> مظالمه . ستم کردن .<br /></font></div>'),
(178994, 'ظلام', '<span class=\"hlight\">ظلام .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) ج ِ ظلمت <span class=\"hlight\">:</span> <br />تا نگردی او ندانی اش تمام <br />خواه آن انوار باشد یا ظلام .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(178995, 'ظلام', '<span class=\"hlight\">ظلام .</span> <font color=\"DarkGreen\"><b>[ ظَل ْ لا ]</font></b> (ع ص ) ظِلّیم . بسیارستم . ظلوم . ستمکارسخت . ستمکاره . <BR><font color=\"Blue\">◄</font> مطلق ظالم <span class=\"hlight\">:</span> وان اﷲ لیس بظلام للعبید. (قرآن <span class=\"hlight\" dir=\"rtl\">١٨٢/٣</span>). ج، ظلامون . <BR><font color=\"Blue\">◄</font> (اِ) گیاهی است نرم دارای شاخ تر و تازه و دراز و بدان ظِلام (به تخفیف لام ) نیز گفته میشود.<br /></font></div>'),
(178996, 'ظلامة', '<span class=\"hlight\">ظلامة.</span> <font color=\"DarkGreen\"><b>[ ظُ م َ ]</font></b> (ع اِمص ) داد. مظلمة. دادخواهی . <BR><font color=\"Blue\">◄</font> ستم کردن . <BR><font color=\"Blue\">◄</font> (اِ) آنچه به زور ستده باشند. <BR><font color=\"Blue\">◄</font> ستم . ظُلم . ج، ظلمات . (مهذب الاسماء).<br /></font></div>'),
(178997, 'ظلامة', '<span class=\"hlight\">ظلامة.</span> <font color=\"DarkGreen\"><b>[ ظَل ْ لا م َ ]</font></b> (اِخ ) قریه ای از قرای بحرین است .<br /></font></div>'),
(178998, 'ظلامة', '<span class=\"hlight\">ظلامة.</span> <font color=\"DarkGreen\"><b>[ ظَل ْ لا م َ ]</font></b> (اِخ ) دختر ابی النجم الراجز. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>).<br /></font></div>'),
(178999, 'ظلة', '<span class=\"hlight\">ظلة.</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل َ ]</font></b> (ع اِ)سایبان . آله . آله گاه . باران گریز. عالة <span class=\"hlight\">:</span> <br />چون بت سنگین شما را قبله شد<br />لعنت و کوری شما را ظله شد.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179000, 'ظلة', '<span class=\"hlight\">ظلة.</span> <font color=\"DarkGreen\"><b>[ ظَل ْ ل َ ]</font></b> (ع اِمص )اقامت به جائی . <BR><font color=\"Blue\">◄</font> صحت . سلامت . تندرستی .<br /></font></div>'),
(179001, 'ظلة', '<span class=\"hlight\">ظلة.</span> <font color=\"DarkGreen\"><b>[ ظُل ْ ل َ ]</font></b> (ع اِ) سایه بان . سایه وان . سایبان تنگ که فراخ نباشد. سایه پوش . باران گریز. آله . آله گاه . عالة. <BR><font color=\"Blue\">◄</font> سقف . <BR><font color=\"Blue\">◄</font> اول ابر که سایه افکند بر تو. <BR><font color=\"Blue\">◄</font> هر درخت که سایه افکند بر تو. <BR><font color=\"Blue\">◄</font> هرچه بدان از حرارت و برودت پناه برند. <BR><font color=\"Blue\">◄</font> صُفّة. <BR><font color=\"Blue\">◄</font> صفه مانندی که در گرما و سرما بدان پناه گیرند. <BR><font color=\"Blue\">◄</font> یوم الظلة؛ روز هلاکت ملوک مدین به زمان شعیب پیغمبر. عذاب یوم الظلة؛ گفته اند ابری که زیر آن سموم بود یا ابری که به آنان سایه افکند و به زیر آن گرد آمدند و پناه بردند از حرارت بسیار که بدیشان رسیده بود و آن ابر بر آنان فرودآمد و در میان گرفت . قوله تعالی : عذاب یوم الظلة (قرآن <span class=\"hlight\" dir=\"rtl\">١٨٩/٢٦</span>). قالوا غیم تحته سموم او سحابةٌ اظلتهم فاجتمعوا تحتها مستجیرین بها مما نالهم من الحرّ الشدید فاطبقت علیهم <span class=\"hlight\">:</span> <br />تو دو قله نیستی یک قله ای <br />غافل از قصّه ی ْ عذاب ظله ای .<br /> <font color=\"Red\">مولوی .</font><br />ج، ظُلَل، ظِلال . <BR><font color=\"Blue\">◄</font> دامت ظلةالظِل ّ؛ أی ما یُستظل ﱡ به .<br /></font></div>'),
(179002, 'ظلظل', '<span class=\"hlight\">ظلظل .</span> <font color=\"DarkGreen\"><b>[ ظُ ظُ ]</font></b> (ع اِ) کشتی ها.<br /></font></div>'),
(179003, 'ظلظلة', '<span class=\"hlight\">ظلظلة.</span> <font color=\"DarkGreen\"><b>[ ظُ ظُ ل َ ]</font></b> (ع اِ) واحد ظُلظُل . یک کشتی .<br /></font></div>'),
(179004, 'ظلع', '<span class=\"hlight\">ظلع.</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (اِخ ) کوهی است بنی سلیم را.<br /></font></div>'),
(179005, 'ظلع', '<span class=\"hlight\">ظلع.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) شأن . حالت . وفی المثل : لایربع علی ظلعک من لیس یحزنه امرک ؛ یعنی به اهتمام شأن تو نرسد مگر غمخوار تو. اربع علی ظلعک َ؛ بازدار خود را از کاری که طاقت آن نداری زیرا که ناتوانی . ارْق َ علی ظَلعک َ؛ جهد در کاری کن که توانی و نرمی و رفق کن با تن خود. ق ِ علی ظَلعک َ؛ نگاه دار و افشا مکن عیب خود را. <BR><font color=\"Blue\">◄</font> (مص ) خمیدن ستور و جز آن در رفتار. لنگیدن : ظَلع البعیر؛ لنگید شتر در رفتن و خمید. <BR><font color=\"Blue\">◄</font> ظلعت الکلبة؛ گُشنخواه شد سگ ماده . <BR><font color=\"Blue\">◄</font> ظلع عن الحق ؛ بچسبید از حق . میل کرد از حق . <BR><font color=\"Blue\">◄</font> تهمت زده شدن .<br /></font></div>'),
(179006, 'ظلع', '<span class=\"hlight\">ظلع.</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ ]</font></b> (ع مص ) تنگ آمدن جای از بسیاری مردم : ظلعت الارض ُ بأهلها؛ أی ضاقت .<br /></font></div>'),
(179007, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع اِ) سُم شکافته مانند سُم گاو و گوسفند و بز و جز آن . ژنگله . زنگله ٔ گاو و گوسفند و آهو و امثال آن . کفشک . (التفهیم ). ج، ظُلوف، اَظلاف .<br />ارجانی گوید: چون سم ستور شکافته بسوزند و با سرکه به هم بیامیزندو بر داءالثعلب طلی کنند منفعت کند و بعض اطباء گفته اند سُنب بز را در خانه بخور کنند به واسطه ٔ او گزندگان از خانه بگریزند. (از ترجمه ٔ صیدنه ٔ ابوریحان ). و نیز سوخته ٔ مجموع سم حیوانات ذوات الظلف مسهل ماء اصفر و ضماد او با شراب جهت گزیدن هوام و با عسل جهت نقرس و مفاصل نافع <font color=\"DarkGreen\"><b>[ باشد ]</font></b> . (مخزن الادویة).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذوات الظلف </span> ؛ زنگله داران از گاو و گوسفند و آهو و آنچه بدان ماند.<br /><BR><font color=\"Blue\">◄</font> حاجت و نیاز. <BR><font color=\"Blue\">◄</font> پیروی در رفتار و جز آن . <BR><font color=\"Blue\">◄</font> مراد و مقصد و مقصود: وجد ظلفه ؛ أی مراده . <BR><font color=\"Blue\">◄</font> چراگاه موافق : وجدت الشاة ظلفها؛ أی مرعی موافقاً فلاتبرح منه . <BR><font color=\"Blue\">◄</font> ظِلف النفس ؛ نزهها؛ أی نزه النفس . ظلیف النفس . <BR><font color=\"Blue\">◄</font> ظلف الخبز؛ کران نان . (مهذب الاسماء).<br /></font></div>'),
(179008, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظُ ل ُ <span class=\"hlight\" dir=\"rtl\">/</span> ظُ ]</font></b> (ع ص، اِ) ج ِ ظلیف .<br /></font></div>'),
(179009, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ظُل ْ ل َ ]</font></b> (ع ص ) ظلوف ٌ ظُلَّف ؛ سُمهای درشت و سخت .<br /></font></div>'),
(179010, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ظَ ]</font></b> (ع ص ) ناچیز. <BR><font color=\"Blue\">◄</font> مباح . روا. <BR><font color=\"Blue\">◄</font> هدر. مفت . باطل . رایگان : ذهب دَمه ظلفاً؛ أی هدراً؛ یعنی رایگان رفت خون او. <BR><font color=\"Blue\">◄</font> (اِمص ) تنگی زندگانی . <BR><font color=\"Blue\">◄</font> ظَلْف . پارسائی . زهادة.<br /></font></div>'),
(179011, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ ]</font></b> (ع ص ) ظلف النفس ؛ عزیز در نفس خویش . پارسا. زاهد.<br /></font></div>'),
(179012, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع مص ) ظلف القوم ؛ پیروی کردآنها را. <BR><font color=\"Blue\">◄</font> ظلف الشاة؛ بر سُم زد گوسفندرا. <BR><font color=\"Blue\">◄</font> ظلف اثره ؛ پوشیده و ناپدید کرد اثر پای را تا راه بدو نبرند، یا در زمین درشت رفت تا اثر نماند. <BR><font color=\"Blue\">◄</font> ظلفت الارض ؛ درشت گردید. <BR><font color=\"Blue\">◄</font> ظلف عنه ؛ بازایستاد از آن . <BR><font color=\"Blue\">◄</font> بازایستادن تن از چیزی . (تاج المصادر بیهقی ). ظلف نفسه عنه ؛ بازداشت نفس را از آنکه کند یا بیارد آن را، یا بازداشت آن را از وی . <BR><font color=\"Blue\">◄</font> زهد ورزیدن .<br /></font></div>'),
(179013, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ ]</font></b> (ع اِ) همه . جملگی . تمام . کامل . <BR><font color=\"Blue\">◄</font> (ص ) مکان ظلف ؛ جای بلند از آب و گل و لای .<br /></font></div>'),
(179014, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ ]</font></b> (ع ص ) جای بلند از آب و گل و لای .<br /></font></div>'),
(179015, 'ظلف', '<span class=\"hlight\">ظلف .</span> <font color=\"DarkGreen\"><b>[ ظِ ل َ ]</font></b> (ع اِ) ج ِ ظَلِفة.<br /></font></div>'),
(179016, 'ظلف التیس', '<span class=\"hlight\">ظلف التیس .</span> <font color=\"DarkGreen\"><b>[ ظِ فُت ْ ت َ ]</font></b> (ع اِ مرکب ) سُم تکه .طبیعتش به ظلف المعز نزدیک تر است . چون بسوزانند و سحق کنند و با عسل بسرشند و به آب بیاشامند نافع بود جهت گمیز کردن در جامه ٔ خواب و اگر در خانه دود کنند مار بگریزد و چون به بول اطفال و عسل سرشته بر شکم ضماد کنند قولنج بلغمی و ریحی را بگشاید. اگر سُم معزبسوزانند و سحق کنند و بر ریشها که در اعضایی که یابس المزاج بود افشانند نافع بود. (اختیارات بدیعی ).<br /></font></div>'),
(179017, 'ظلف الخبز', '<span class=\"hlight\">ظلف الخبز.</span> <font color=\"DarkGreen\"><b>[ ظِ فُل ْ خ ُ ]</font></b> (ع اِ مرکب ) کران نان .<br /></font></div>'),
(179018, 'ظلف المعز', '<span class=\"hlight\">ظلف المعز.</span> <font color=\"DarkGreen\"><b>[ ظِ فُل ْ م َ ]</font></b> (ع اِ مرکب )سُم بز. سرد و خشک بود در سیم، داءالثعلب و داءالحیه را نافع بود چون خاکستر آن با سرکه طلا کنند و اگر سحق کنند با شراب و بر گزیدگی مجموع جانوران یا سباع نهند نافع بود و اگر سحق کنند با عسل و طلا کنند دردمفاصل و نقرس را نافع بود و اگر با بول کودکان بپزند و بر شکم ضماد کنند قولنج که از بلغم لزج و ریاح بود نافع است و مسهل آب زرد بود. (اختیارات بدیعی ).<br /></font></div>'),
(179019, 'ظلفات', '<span class=\"hlight\">ظلفات .</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ ]</font></b> (ع ص، اِ) ج ِ ظَلِفة.<br /></font></div>'),
(179020, 'ظلفة', '<span class=\"hlight\">ظلفة.</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ظَ ل ِ ف َ ]</font></b> (ع اِ) نشانی است مرشتر را. <BR><font color=\"Blue\">◄</font> (ص ) ارض ظلفة (بالفتح و التحریک )؛ زمین درشت که اثر نگیرد. <BR><font color=\"Blue\">◄</font> امراءة ظلفةالنفس ؛ أی عزیزة عند نفسها. <BR><font color=\"Blue\">◄</font> (اِ) یکی از چهار چوب که بر پالان بر دو پهلوی شتر بندند و اطراف زیرین آن به زمین رسد وقتی که بر زمین نهند.<br /></font></div>'),
(179021, 'ظلفتان', '<span class=\"hlight\">ظلفتان .</span> <font color=\"DarkGreen\"><b>[ ظَ ف َ ]</font></b> (ع اِ) هر دو سوی پالان شتر. (مهذب الاسماء).<br /></font></div>'),
(179022, 'ظلل', '<span class=\"hlight\">ظلل .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (ع اِ) ج ِ ظُلَّة.<br /></font></div>'),
(179023, 'ظلل', '<span class=\"hlight\">ظلل .</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ ]</font></b> (ع اِ) آب زیر درختان که بر آن آفتاب نرسد.<br /></font></div>'),
(179024, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظُ]</font></b> (ع اِمص ) به ناجایگاه نهادن چیزی را. وضع شیئی درغیر موضع خود. ستم . بیداد. ستم کردن . ستمگری . بیدادی . بیدادگری . جور. جفا. عسف . اعتساف . حیف . بغی . ضیم .عدوان . آزار. زور. مظلمه . کفر. ج، ظلام <span class=\"hlight\">:</span> <br />در صفات تو ظلم نتوان گفت <br />با سگی در جوال نتوان خفت .<br /> <font color=\"Red\">سنائی .</font><br />هر کجا عدل روی بنموده ست <br />نعمت اندر جهان بیفزوده ست <br />هر کجا ظلم رخت افکنده ست <br />مملکت را ز بیخ برکنده ست .<br /> <font color=\"Red\">سنائی .</font><br />ظلم از هرکه هست نیک بدست <br />وانکه او ظالم است نیک بدست .<br /> <font color=\"Red\">سنائی .</font><br />من از ظلم او بیزارم . (کلیله و دمنه ). و به رعیت ظلمی روا ندارد. (کلیله و دمنه ). ملکا اگرمیدانی که شوی بر من ظلم کرد... تو به فضل خویش ببخشای . (کلیله و دمنه ).<br />نهاد بد نپسندد خدای نیکوکار<br />امیر خفته و مردم ز ظلم او بیدار.<br /> <font color=\"Red\">سعدی .</font><br />ظلم تاریک و دل سیه کندت <br />عدل رخشنده تر ز مه کندت .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> عبادت غیر خدای . <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون گوید: ظُلم بالضم و الفتح و سکون اللام، لغة وضعالشی ٔ فی غیر محله و فی الشریعة عبارة عن التعدی عن الحق الی الباطل و هو الجور و قیل هو التصرف فی ملک الغیر و مجاوزة الحد. کذا فی الجرجانی . و هو مستحیل علی اﷲ تعالی اذ هو التصرف فی حق الغیر بغیر حق أومجاوزة الحد. و کلاهما محال اذ لا ملک و لا حق لاحد معه بل هو الذی خلق المالکین و املاکهم و تفضل علیهم بهاو عهد لهم الحدود و حرم و احل فلا حاکم یتعقبه و لا حق یترتب علیه . و ما ذکر من استحالة الظلم علیه تعالی هو قول الجمهور. و قیل بل هو متصور منه لکنه لایفعله عدلاً منه و تنزهاً عنه، لأنّه تعالی تمدح بنفیه فی قوله : و ما انا بظلام للعبید. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٩/٥٠</span>). و الحکیم لایتمدح الا بما یصح منه . فان الاعمی لو تمدح نفسه بانه لاینظر الی المحرمات، استهزی ٔ به . و هذا غیر سدید. لما تقرر ان حقیقة الظلم وضع الشی ٔ فی غیر محله بالتصرف فی ملک الغیر أو مجاوزة الحد و مع النظر بهذا یجزم کل من له ادنی لُب ّ باستحالته علیه سبحانه اذ لایتعقل وقوع شی ٔ من تصرفه فی غیر محله . و کان مدعی تصوره منه سبحانه یفسره بما هو ظلم عند العقل لو خلی و نفسه من حیث عدم مطابقته لقضیة. فحینئذ یکون لکلامه نوع احتمال بخلاف ما اذا فسره بالاول . فان دعوی تصوره منه سبحانه فی غایة. و یجاب عن التمدح المذکور بان هذا خارج عن قضیة الخطاب العادی، المقصود به زجر عباده عنه و اعلامهم بامتناعه علیهم بالاولی فهو علی حدّ «لئن اشرکت لیحطبن عملک ». (قرآن <span class=\"hlight\" dir=\"rtl\">٦٥/٣٩</span>). و هذا فن بلیغلاینکره الا کل جامدالطبع. فامتنع القیاس علی قول الاعمی . کذا ذکر ابن الحجر فی شرح الاربعین للنووی فی الحدیث الرابع و العشرین . و فی التفسیر الکبیر قالت المعتزلة ان قوله تعالی : ان اﷲ لایظلم مثقال ذرّة... الاَّیة (قرآن <span class=\"hlight\" dir=\"rtl\">٤٠/٤</span>)، دال علی ان العبد یستحق الثواب علی طاعته و انه تعالی لو لم یثبه لکان ظالماً. و الجواب انه تعالی لما وعدهم الثواب علی تلک الافعال فلو لم یثبهم علیها لکان ذلک فی صورة الظلم فلهذا اطلق علیه اسم الظلم - انتهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">ظلم امروز ظلمت فرداست </span> .<br /> <span class=\"hlight\">ظلم به تساوی عدل است </span> ؛ یعنی : المصیبة اذا عمت طابت .<br /> <span class=\"hlight\">ظلم ظالم بر سر اولاد ظالم میرود</span> .<br /><span class=\"hlight\">ظلم عاقبت ندارد</span> .<br /></font></div>'),
(179025, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع مص ) ستم کردن . <BR><font color=\"Blue\">◄</font> به ناجایگاه نهادن چیزی را. <BR><font color=\"Blue\">◄</font> کم و نقص کردن حق کسی را. <BR><font color=\"Blue\">◄</font> ظلم ارض ؛ کندن زمین در غیر جای کندیده . <BR><font color=\"Blue\">◄</font> ظَلم بعیر؛ کشتن شتر را بی علت و بیماری . <BR><font color=\"Blue\">◄</font> ظَلم وادی ؛ از حد زیاده شدن آب رودکده . <BR><font color=\"Blue\">◄</font> ظلم الوَطب ؛ پیش از جُغرات شدن خورد شیر را. <BR><font color=\"Blue\">◄</font> ظَلم َ الحمار الأتان ؛ بر ماده ٔ باردار جهید خر. <BR><font color=\"Blue\">◄</font> ظَلم َ القوم ؛ خورانید قوم را شیر پیش از جغرات شدن . <BR><font color=\"Blue\">◄</font> ماظَلمک ان تفعل ؛ کدام چیز بازداشت ترا از کردن آن کار. <BR><font color=\"Blue\">◄</font> ظَلم الطریق ؛ میل کرد از راه .<br /></font></div>'),
(179026, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) برف . <BR><font color=\"Blue\">◄</font> (اِمص ) آبداری و صفا و درخشندگی دندان که از شدت سپیدی به سیاهی زند همچون جوهر شمشیر. برق . بریق . ج، ظلوم . <BR><font color=\"Blue\">◄</font> (اِخ ) نام شمشیر هذیل تغلبی . <br /></font></div>'),
(179027, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ ]</font></b> (ع اِ) کالبد. <BR><font color=\"Blue\">◄</font> کوه . ج، ظُلوم . <BR><font color=\"Blue\">◄</font> لَقیته ادنی ظَلم أو ادنی ذی ظَلم ؛ أی اول کل شی ٔ أو حین اختلط الظلام أو ادنی ظلم القرب أو القریب .<br /></font></div>'),
(179028, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظُ ل ُ ]</font></b> (ع اِمص ) ظُلم .<br /></font></div>'),
(179029, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (ع اِ) ج ِ ظلمت . تاریکی ها <span class=\"hlight\">:</span> <br />شادمان باد و به شادی ّ و طرب نوش کناد<br />باده از دست بتی خوبتر از بدر ظلم .<br /> <font color=\"Red\">فرخی .</font><br />همیشه تا نفروزد قمر چو شمس ضحی <br />همیشه تا ندرخشد سها چو بدر ظلم .<br /> <font color=\"Red\">فرخی .</font><br />ظلمت این شعر رای روشن تو دور کرد<br />هر کجا آثار نور آمد شود روشن ظلم .<br /> <font color=\"Red\">مسعودسعد.</font><br />مرا بیع کرم و ینابیع حکم و مصابیح ظُلَم و مجاریح امم بودند. (ترجمه ٔ تاریخ یمینی ).<br />پای کفش خود شناسد در ظلم <br />جان تن خود چون نداند ای صنم .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179030, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (ع اِ) سه شب متصل به شبهای دُرع، یعنی نوزدهم و بیستم و بیست ویکم . <BR><font color=\"Blue\">◄</font> ج ِ ظَلماء .<br /></font></div>'),
(179031, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظِ ل َ ]</font></b> (ع اِ) گیاهی است که شاخ نرم و تر و دراز دارد. (منتهی الارب ).<br /></font></div>'),
(179032, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ ]</font></b> (ع مص ) تاریک شدن .<br /></font></div>'),
(179033, 'ظلم', '<span class=\"hlight\">ظلم .</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ ]</font></b> (اِخ ) وادیی است از وادیهای قبلیة. قال الأصمعی : ظلم جبل اَسود لعمروبن عبدبن کلاب و هو و خَوّ فی حافتی بلاد بنی ابی بکربن کلاب فبلاد ابی بکر بینهما ظَلِم مما یلی مکة جنوبی الدفینة... و قال نصر: ظَلم جبل بالحجاز بین اضم و جبل جهینة. (معجم البلدان ).<br /></font></div>'),
(179034, 'ظلم', '<span class=\"hlight\">ظلم .</span><font color=\"DarkGreen\"><b>[ ظَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ظِ ل َ ]</font></b> (اِخ ) موضعی است در شعر زُهیر.<br /></font></div>'),
(179035, 'ظلم آباد', '<span class=\"hlight\">ظلم آباد.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) در مغرب بیش قلعه و شمال غربی بجنورد.<br /></font></div>'),
(179036, 'ظلم کردن', '<span class=\"hlight\">ظلم کردن .</span> <font color=\"DarkGreen\"><b>[ ظُ ک َ دَ ]</font></b> (مص مرکب ) تعدی . ایذاء. ستم کردن . اعتساف . محروم از حق خود کردن .<br /></font></div>'),
(179037, 'ظلماء', '<span class=\"hlight\">ظلماء.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) تاریکی . ظلمت . <BR><font color=\"Blue\">◄</font> واحده ٔ ظُلم، یعنی سه شب متصل به شبهای دُرع که نوزدهم و بیستم و بیست ویکم باشد. <BR><font color=\"Blue\">◄</font> (ص ) لیلة ظَلماء؛ شب نیک تاریک .<br /></font></div>'),
(179038, 'ظلمات', '<span class=\"hlight\">ظلمات .</span> <font color=\"DarkGreen\"><b>[ ظُ ل ُ <span class=\"hlight\" dir=\"rtl\">/</span> ظُ ل َ ]</font></b> (ع اِ) ج ِ ظلمت . <BR><font color=\"Blue\">◄</font> قسمتی از زمین به شمال که به عقیده ٔ قدما بدانجا دائماً شب باشد و آب حیوان بدانجاست و به زمین آن گوهرها پراکنده است و اسکندر و خضر به طلب آب حیات بدانجا شدند و خضر آب زندگی بخورد و زنده ٔ جاوید ماند <span class=\"hlight\">:</span> هر گوهر که ذوالقرنین قلم او از ظلمات دوات بیرون کشید درّی بود در واسطه ٔ قلاده ٔ روزگار. (ترجمه ٔ تاریخ یمینی ).<br />شنیده ای که سکندر برفت تا ظلمات <br />به چند محنت و خورد آنکه خورد آب حیات .<br /><font color=\"Red\">سعدی (گلستان ).</font><br />قطع این مرحله بی همرهی خضر مکن <br />ظلمات است بترس از خطر گمراهی .<br /> <font color=\"Red\">حافظ.</font><br />بنا بر نوشته های مورخین یونانی و پس از تصحیح آن موافق اطلاعات جغرافیائی کنونی، ظاهراً داستان به ظلمات رفتن اسکندر چنین است که وی از سیستان به طرف گودزره و رُخّج رفته، بعد به طرف شمال افغانستان، که در همسایگی باختر بوده، متوجه گشته و از کوههای مملکت گذشته، تا به باختر درآید. در موقع صعود به کوهها، قشون اسکندر به برف و یخ بسیار برخورده و عده ٔ کثیری از سپاهیانش تلف شدند. تاریکی هم از مه بوده که مانع میشده سپاهیان یکدیگر را ببینند. احتمال قوی میرود که سرداران اسکندر برای جلب توجه مردمان قدری هم در توصیف این راه و عبور از کوهها مبالغه کرده اند و این اغراقگوئی در کتب مورخین قرون بعد انعکاس یافته و سرچشمه ٔ روایات راجع به رفتن اسکندر پسر فیلیپ به قطب و ظلمات گردیده است . رجوع به ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٩٠</span> شود. <BR><font color=\"Blue\">◄</font> ظلمات بحر در بیت ذیل خاقانی کنایه از شب است <span class=\"hlight\">:</span> <br />صبحدم آب خضر نوش از لب جام گوهری <br />کز ظلمات بحر جست آینه ٔ سکندری .<br /> <font color=\"Red\">خاقانی .</font><br />و تحقیق فوق ازآنندراج است .<br /></font></div>'),
(179039, 'ظلمات ثلاث', '<span class=\"hlight\">ظلمات ثلاث .</span> <font color=\"DarkGreen\"><b>[ ظُ ل ُ ت ِ ث َ ]</font></b> (ترکیب وصفی، اِ مرکب ) ظلمات سه گانه که در قرآن کریم آمده است، کنایه از سه تاریکی است که یونس علیه السلام را پیش آمد، یکی تاریکی شب، دوم تاریکی شکم ماهی، سوم تاریکی قعر دریا و برخی گویند کنایه از کدورت طبعی و هوای نفسانی و خاصیت حیوانی باشد، یا کنایه از کدورات طول و عرض و عمق عالم سفلی است . و به اعتقاد بعضی قوله تعالی : فی ظلمات ثلاث (قرآن <span class=\"hlight\" dir=\"rtl\">٦/٣٩</span>)، کنایه از تاریکی مشیمه و تاریکی شکم مادر و تاریکی رحم باشد. (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />می کند در طبایع اربع<br />ظلمات ثلاث را انوار.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179040, 'ظلمان', '<span class=\"hlight\">ظلمان .</span> <font color=\"DarkGreen\"><b>[ ظِ <span class=\"hlight\" dir=\"rtl\">/</span> ظُ ]</font></b> (ع ص، اِ) ج ِ ظلیم .<br /></font></div>'),
(179041, 'ظلمانی', '<span class=\"hlight\">ظلمانی .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع ص ) تار. تاری . تاریک . مُظلم . مُظلمة. تیره <span class=\"hlight\">:</span> <br />همه درذات انسان هست حاصل <br />گِلش ظلمانی و نورانیش دل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />صبح جهان افروز... کله ٔ ظلمانی از پیش برداشت . (کلیله و دمنه ). آن روز جوانان لشکر چالش میکردند تا بساط ظلمانی شب گسترده شد. (ترجمه ٔ تاریخ یمینی ). اگر آفتاب وار چراغی در خانه ٔ ظلمانی محنتم داری چون آفتاب به مشعله داری درگهت بازایستم . (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> اجود انواع زمرّد است و آن مشبعالخضره است .(بیرونی ). ظلمانی زمردی است که برخلاف صیقلی بود و خفت وزن و سرعت انکسار و شدت نعومت و عدم مصابرت بر نار از جمله ٔ صفات و علامات آن است . (جواهرنامه ).<br /></font></div>'),
(179042, 'ظلمة', '<span class=\"hlight\">ظلمة.</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ م َ ]</font></b> (ع ص، اِ) ج ِ ظالم .<br /></font></div>'),
(179043, 'ظلمة', '<span class=\"hlight\">ظلمة.</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ م َ ]</font></b> (ع ص ) لیل-ةٌ ظلمة؛ شبی تاریک .<br /></font></div>'),
(179044, 'ظلمة', '<span class=\"hlight\">ظلمة.</span> <font color=\"DarkGreen\"><b>[ ظُ م َ ]</font></b> (اِخ ) (بحرالَ ...) بحرالاسود الشمالی . بحر ورنگ .<br /></font></div>'),
(179045, 'ظلمة', '<span class=\"hlight\">ظلمة.</span> <font color=\"DarkGreen\"><b>[ ظِ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ظُ م َ ]</font></b> (اِخ ) فاجره ای است از قوم هُذَیل و در مَثل است : اقود من ظِلمةَ.<br /></font></div>'),
(179046, 'ظلمت', '<span class=\"hlight\">ظلمت .</span> <font color=\"DarkGreen\"><b>[ ظُ م َ ]</font></b> (ع اِ) ظُلمة. تاریکی . ظلماء. دجی . تیرگی . مقابل روشنا و روشنائی <span class=\"hlight\">:</span> <br />شبی دیرند ظلمت را مهیا<br />چو نابینا در او، دو چشم بینا.<br /> <font color=\"Red\">رودکی .</font><br />کجا نور و ظلمت بدو اندر است <br />ز هر گوهری گوهرش برتر است .<br /> <font color=\"Red\">فردوسی .</font><br />از ظلمت قلعتی بدان تاری ... روشن گردانید. (تاریخ بیهقی ).<br />بیهوده مجوی آب حیوان <br />در ظلمت خویش چون سکندر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا خلق را از ظلمت جهل و ضلالت نفس برهانیدند. (کلیله و دمنه ). یکی را... قوّت شهوانی بر قوّت عقل غالب گشته و نور بصیرت او را به حجاب ظلمت پوشیده . (کلیله و دمنه ). زاهد خود را از ظلمت فسق و فساد... برهانید. (کلیله و دمنه ). اگر ظلمت شب مانع نیامدی یکی از آن مخاذیل جان بیرون نبردی . (ترجمه ٔتاریخ یمینی ). بوم اعتقاد ایشان که در ظلمت کفر به صدای (؟) بدعت نوحه میکرد در دام اسلام افکند. (ترجمه ٔ تاریخ یمینی ). عرصه ٔ آن بقاع از ظلمت کفر و شرک پاک کرد. (ترجمه ٔ تاریخ یمینی ).<br />چون برآمد نور ظلمت نیست شد<br />ظلم را ظلمت بود اصل و عضد.<br /> <font color=\"Red\">مولوی .</font><br />شب گریزد چونکه نور آید ز دور<br />پس چه داند ظلمت شب حال نور.<br /> <font color=\"Red\">مولوی .</font><br />نور حق چون برسدظلمت باطل برود.<br /> <font color=\"Red\">سعدی .</font><br />ظلم امروز ظلمت فرداست .<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> عذاب . <BR><font color=\"Blue\">◄</font> شدّت . <BR><font color=\"Blue\">◄</font> نقصان فعل حاسه ٔ بینائی : ظلمةالبصَر. ج، ظُلَم، ظُلَمات، ظُلُمات . صاحب کشاف اصطلاحات الفنون آرد: ظلمة، بالضم و السکون، هی عدم الضوء عما من شأنه ان یکون مضیئاً. فالتقابل بینها و بین الضوء تقابل العدم و الملکة. و الدلیل علی انها امر عدمی رؤیة الجالس فی الغار المظلم الخارج عنه اذا وقع علی الخارج ضوء بلا عکس، أی لایری الخارج الجالس و ما هو الاّ لأنّه لیس الظلام بامر حقیقی قائم بالهواء مانع للأبصار اذ لو کان کذلک لم یر احد بها الاَّخر اصلاً بوجود العائق عن الرؤیة بینهما فتعین انها عدم الضوء. و حینئذ ینتفی شرط کون الجالس فی الغار مرئیاً دون شرط کون الخارج مرئیاً فیری . و قیل الظلمة کیفیة وجودیة مضادّة للضوء، کما ان شرط الرؤیة ضوء یحیط بالمرئی لا الضوء مطلقاً و لا الضوء المحیط بالرائی فکذلک العائق عن الرؤیة ظلمة تحیط بالمرئی لا الظلمة المحیطة بالرائی و لا الظلمة مطلقاً. فلذلک اختلف حال الجالس و الخارج . و قد استدلوا علی وجودها ایضاً بقوله تعالی : و جعل الظلمات و النور. (قرآن <span class=\"hlight\" dir=\"rtl\">١/٦</span>). فان المجعول لایکون الا موجوداً. و اجیب بالمنع فان الجاعل کما یجعل الوجود یجعل العدم الخاص کالعمی . و انما المنافی للمجعولیة العدم الصرف کما فی خلق الموت و الحیوة (قرآن <span class=\"hlight\" dir=\"rtl\">٢/٦٧</span>). اعلم ان ّ منهم من جعل الظلمة شرطاً لرؤیة بعض الاشیاء کالتی تلمع من الکواکب و الشعل البعیدة و لاتری فی النهار. و ما ذلک الا لکون الظلمة شرطاً للرؤیة. و ردّ ذلک بان ذلک لیس لتوقف الرؤیة علی الظلمة بل لان الحس غیر منفعل باللیل عن الضوء القوی کما فی النهار فینفعل عن الضوء الضعیف و یدرکه . و لما کان فی النهار منفعلاً عن ضوء قوی ّ لم ینفعل عن الضعیف فلم یحس ّ به . و ذلک کالهباء الذی یری فی البیت اذا وقع علیه الضوء من الکوة و لایری فی الشمس لان بصر الانسان حینئذ یصیر مغلوباً لضوئها فلایقوی احساس الهباء بخلاف ما اذا کان فی البیت فان بصره لیس هنا منفعلاً عن ضوء قوی فلاجرم یدرک حینئذ. کذا فی شرح المواقف فی بحث المبصرات .<br /></font></div>'),
(179047, 'ظلمت آباد', '<span class=\"hlight\">ظلمت آباد.</span> <font color=\"DarkGreen\"><b>[ ظُ م َ ]</font></b> (اِ مرکب ) کنایه از عالم عدم است . (آنندراج ).<br /></font></div>'),
(179048, 'ظلمتکده', '<span class=\"hlight\">ظلمتکده .</span><font color=\"DarkGreen\"><b>[ ظُ م َ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) کنایه از دنیاست .<br /></font></div>'),
(179049, 'ظلمتیان', '<span class=\"hlight\">ظلمتیان .</span> <font color=\"DarkGreen\"><b>[ ظُ م َ ]</font></b> (اِ مرکب ) کنایه از بت پرستان و مخالفان مذهب حق باشد و طائفه ٔ ثنویان که نور و ظلمت را خداگویند و خالق خیر و شر نامند. (آنندراج ) (برهان ).<br /></font></div>'),
(179050, 'ظله ساختن', '<span class=\"hlight\">ظله ساختن .</span> <font color=\"DarkGreen\"><b>[ ظُل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ت َ ]</font></b> (مص مرکب ) تعویل . (تاج المصادر بیهقی ). باران گریز ساختن .<br /></font></div>'),
(179051, 'ظلوف', '<span class=\"hlight\">ظلوف .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظِلف . سُمهای شکافته . زنگله ها.<br /></font></div>'),
(179052, 'ظلول', '<span class=\"hlight\">ظلول .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظِل ّ.<br /></font></div>'),
(179053, 'ظلول', '<span class=\"hlight\">ظلول .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع مص ) ظَل ّ. روز گذاشتن . همه روز کاری کردن . (تاج المصادر بیهقی ): ظَل َّ نهاره یفعل کذا؛ یعنی تمام روز چنین میکند، و کذا ظَل َّ لیله یفعل کذا.<br /></font></div>'),
(179054, 'ظلوم', '<span class=\"hlight\">ظلوم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) ظَلاّم . سخت ستمکار <span class=\"hlight\">:</span> <br />عادت و رسم این گروه ظلوم <br />نیک ماند چوبنگری به ظلیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />درویشی را دیدم که سر بر آستان کعبه همی مالید و میگفت یا غفور یا رحیم تو دانی که از ظلوم و جهول چه آید. (گلستان ).<br /></font></div>'),
(179055, 'ظلوم', '<span class=\"hlight\">ظلوم .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظَلَم و ظَلْم .<br /></font></div>'),
(179056, 'ظلوم', '<span class=\"hlight\">ظلوم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) نام کنیزکی ام ولد، مادر الراضی باﷲ ابوالعباس احمدبن جعفر المقتدر خلیفه ٔ عباسی .<br /></font></div>'),
(179057, 'ظلکم طویل', '<span class=\"hlight\">ظلکم طویل .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ ل ُ ک ُ طَ ]</font></b> (ع جمله ٔ اسمیه ٔ دعایی ) سایه ٔ شما پاینده . عمرتان بادا دراز.<br /></font></div>'),
(179058, 'ظلیع', '<span class=\"hlight\">ظلیع.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) ستور لنگ . ظالع.<br /></font></div>'),
(179059, 'ظلیف', '<span class=\"hlight\">ظلیف .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (اِخ ) موضعی است درشعر عبیدبن ایوب اللص ّ آنجا که میگوید <span class=\"hlight\">:</span> <br />ألا لیت شعری هل تغیربعدنا<br />عن العهد قارات الظلیف الفوارد<br />و هل رام عن عهدی وُدَیْک ٌ مکانه <br />الی حیث یفضی سیل ذات المساجد.<br /><font color=\"Red\">(معجم البلدان ).</font><br /></font></div>'),
(179060, 'ظلیف', '<span class=\"hlight\">ظلیف .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص، اِ) بدحال . <BR><font color=\"Blue\">◄</font> خوار. ذلیل . <BR><font color=\"Blue\">◄</font> جای سخت . <BR><font color=\"Blue\">◄</font> کار دشوار. <BR><font color=\"Blue\">◄</font> بلای شدید. <BR><font color=\"Blue\">◄</font> سختی و درشتی . <BR><font color=\"Blue\">◄</font> بُن گردن . ج، ظُلف، ظُلُف . <BR><font color=\"Blue\">◄</font> ظلیف النفس ؛نزه النفس . ظلف النفس . <BR><font color=\"Blue\">◄</font> ذهب به ظلیفاً؛ مفت و رایگان و بی بها برد آن را. <BR><font color=\"Blue\">◄</font> تمام . کامل . کل ّ. همه : اَخذه بظلیفه و بظلیفته ؛ أی کله .<br /></font></div>'),
(179061, 'ظلیل', '<span class=\"hlight\">ظلیل .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) سایه دار. سایه وَر. سایه افکن . سایه ناک . ج، اَظِلَّة. (متن اللغة). <BR><font color=\"Blue\">◄</font> آنچه سایه اندازد. مظلل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ظِل ّ ظلیل </span> ؛ سایه ٔ دائم . سایه ٔ کشیده . سایه ٔ تمام . یا مبالغه است <span class=\"hlight\">:</span> <br />گرد راه و آفتاب معرکه نزدیک تو<br />خوشتر از گرد عبیر سوده و ظل ظلیل .<br /> <font color=\"Red\">فرخی .</font><br />در آن بقعه ٔ شاهوار در ظل ظلیل رفاهیت غنودم . (ترجمه ٔ تاریخ یمینی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مکان ظلیل </span> ؛ جای باسایه یا پیوسته سایه و گفته اند جای سرد و بارد.<br />رجوع به ظل شود.<br /></font></div>'),
(179062, 'ظلیلة', '<span class=\"hlight\">ظلیلة.</span> <font color=\"DarkGreen\"><b>[ ظَ ل َ ]</font></b> (ع ص، اِ) تأنیث ظلیل : و نیبت برشاووشان فی اماکن ظلیلة. (ابن البیطار). <BR><font color=\"Blue\">◄</font> استادنگاه آب در پائین مسیل رودبار. <BR><font color=\"Blue\">◄</font> مرغزار بسیاردرخت . ج، ظَلائل .<br /></font></div>'),
(179063, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) وادیی است در نجد <span class=\"hlight\">:</span> <br />من دیار کأنهن رسوم <br />لسلیمی برامة فتریم <br />اقفر الخِب ُّ من منازل اسما -<br />ءَ فجنبا مقلص فظلیم .<br /><font color=\"Red\">ابودؤاد الایادی (از معجم البلدان ).</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179064, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) شترمرغ نر. اشترمرغ . نعام . نعامه . مرغ آتش خوار. رفراف . ابوالبیض . ابوالصحاری . ابوثلثین . ج، ظِلمان، ظُلمان، اَظلِمة. (ذیل اقرب الموارد) <span class=\"hlight\">:</span> <br />کامران باش و می لعل خور و دشمن را<br />گو همی خور شب و روز آتش سوزان چو ظلیم .<br /> <font color=\"Red\">فرخی .</font><br />هرکه او را بستاید بنسوزد دهنش <br />ور دهان پر کند از آتش مانند ظلیم .<br /> <font color=\"Red\">فرخی .</font><br />عادت و رسم این گروه ظلوم <br />نیک ماند چو بنگری به ظلیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />به دار دنیا چون برفروخت آتش ظلم <br />سکار آن به جهنم همی خورد چو ظلیم .<br /> <font color=\"Red\">سوزنی .</font><br />فقیه عامی خواند ورا وعامه فقیه <br />به هر دونام بود بهره مند همچو ظلیم .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> خاک زمین مظلومة، أی محفورة. <BR><font color=\"Blue\">◄</font> شیر که پیش از جغرات شدن بخورند. ماست نرسیده . <BR><font color=\"Blue\">◄</font> (اِخ ) نام چندین اسب معروف .<br /></font></div>'),
(179065, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) مظلوم . ستمدیده .<br /></font></div>'),
(179066, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ لی ]</font></b> (ع ص ) بسیارستم .ظلوم . ظلاّم . رجل ظلیم ؛ کثیرالظلم . (مهذب الاسماء).<br /></font></div>'),
(179067, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (اِخ ) جایگاهی است در یمن و ذوظلیم از ملوک حِمْیَر منسوب بدانجاست .<br /></font></div>'),
(179068, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (اِخ ) ابن حطیط. محدث است .<br /></font></div>'),
(179069, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظُ ل َ ]</font></b> (اِخ ) ابن حنظلةبن مالک بن مرةبن مالک بن زیدمناةبن تمیم، و ظلیم لقب اوست . (تاج العروس ). <BR><font color=\"Blue\">◄</font> یکی از بطنهای براجم و از ایشان است حکم بن عبداﷲبن عدن بن ظلیم شاعر.<br /></font></div>'),
(179070, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) (الَ ...) آخرالنهر . نام ستاره ای از قدر اول بیرون صورت نهر .<br /></font></div>'),
(179071, 'ظلیم', '<span class=\"hlight\">ظلیم .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) مولی عبداﷲبن سعد. تابعی است .<br /></font></div>'),
(179072, 'ظلیمان', '<span class=\"hlight\">ظلیمان .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) تثنیه ٔ ظلیم . <BR><font color=\"Blue\">◄</font> (اِخ ) نام دو ستاره از قدر اول بیرون صورت نهر . <BR><font color=\"Blue\">◄</font> ظلیمان صغیران ؛ الریال .<br /></font></div>'),
(179073, 'ظلیمة', '<span class=\"hlight\">ظلیمة.</span><font color=\"DarkGreen\"><b>[ ظَ م َ ]</font></b> (ع اِ) شیر که پیش از جغرات شدن خورده شود. یقال : سقانا ظلیمة طیبة. <BR><font color=\"Blue\">◄</font> دادخواهی . الظلیمة! الظلیمة!؛ فغان ! فریاد! ای داد! <BR><font color=\"Blue\">◄</font> ستم . (مهذب الاسماء).<br /></font></div>'),
(179074, 'ظماء', '<span class=\"hlight\">ظماء.</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع ص ) ظماء بودن فصوص اسب ؛ بندهای آن سست و فروهشته و پرگوشت نبودن . <BR><font color=\"Blue\">◄</font> (مص ) تشنه یا سخت تشنه شدن . ظماءَة. <BR><font color=\"Blue\">◄</font> (اِمص ) ظِما. تشنگی <span class=\"hlight\">:</span> <br />مرا چو تیغ دهد آب، آبگون گردون <br />هرآنگهی که بنالم به پیش او ز ظما<br />چو تیغ نیک بتفساندم ز آتش دل <br />در آب دیده کند غرق تا به فرق مرا.<br /> <font color=\"Red\">مسعودسعد.</font><br />هرچند بیش گریم تشنه ترم به وصل <br />از آب کس شنید که افزون شود ظما.<br /> <font color=\"Red\">مسعودسعد.</font><br />جوق جوق اسپاه تصویرات ما<br />سوی چشمه ی ْ دل شتابان از ظما.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179075, 'ظمخ', '<span class=\"hlight\">ظمخ .</span> <font color=\"DarkGreen\"><b>[ ظِ م َ ]</font></b> (ع اِ) درختی است که به درخت چنار ماند. <BR><font color=\"Blue\">◄</font> درخت انجیر، به لغت طی . <BR><font color=\"Blue\">◄</font> اسم ثمر جودار است نزد اهل عرب به قیروان و غیر آن . و بعضی گفته اند که آن ثمره ٔ جوذر است . رجوع به جوذر شود.<br /></font></div>'),
(179076, 'ظمی', '<span class=\"hlight\">ظمی .</span> <font color=\"DarkGreen\"><b>[ ظَ ما ]</font></b> (ع اِمص ) کمی خون بن دندان . <BR><font color=\"Blue\">◄</font> گندمگونی لبها. سیاهی لبها. <BR><font color=\"Blue\">◄</font> کم خونی .<br /></font></div>'),
(179077, 'ظن', '<span class=\"hlight\">ظن .</span> <font color=\"DarkGreen\"><b>[ ظَن ن ]</font></b> (ع مص، اِمص ) پنداشت . گمان . ارتیاب . یعنی طرف راجح از دو طرف اعتقاد غیرجازم . (منتهی الارب ). حدس . <BR><font color=\"Blue\">◄</font> گمان بردن . <BR><font color=\"Blue\">◄</font> به درستی دانستن . دانستن . اعتقاد محکم . قوله تعالی <span class=\"hlight\">:</span> ظن داود (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤/٣٨</span>)؛ أی علم و ایقن . و لغت از اضداد است . (منتهی الارب ). باور. اعتقاد راجح مع عدم المنع من الترک . ادراک راجح از یکی از طرفین وجود یا عدم نسبت . غلبه ٔ یکی از طرفین وقوع و لاوقوع . ظَن ّ بالفتح و تشدید النون ؛ الشک ّ. و الظن و الوهم بحسب اللغة یکاد لایفرق بینهما. کذا فی الکرمانی . و هو بین الفقهاء التردد بین امرین استویا أو ترجح احدهما علی الاَّخر. و اما عند المتکلمین فالشک تجویز امرین لیس لاحدهما مزیة علی الاَّخر. و الظن ّ تجویز امرین احدهما ارجح من الاَّخر. و المرجوح یسمی بالوهم . کذا فی تیسیرالقاری ٔ فی علم القرائة بعد ذکر بحث الادغام . و فی شرح التجرید: الظن ترجیح احد الطرفین، أی الایجاب و السلب اعتقاداً راجحاً لاینقبض النفس معه عن الطرف الاَّخر. و هو غیر اعتقاد الرجحان . فان ّ اعتقاد الرجحان قد یکون جازماً، بخلاف الظن ّ فانه اعتقاد راجح بلا جزم و لذا یقبل الشدة و الضعف . و طرفاه علم و جهل فان بعض الظنون اقوی من بعض - انتهی .فالظن ادراک بسیط و التوهم امر مغایر له حاصل بعد ملاحظة الطرف الاَّخر. و ما قالوا ان ّ الظن ادراک یحتمل النقیض، فالمراد انّه کذلک بالقوة. کذا ذکره السّید السّند فی الحواشی العضدیة. و هکذا فی السﱡلّم . ثُم اطلاق الظن علی الاعتقاد الراجح هو المشهور و قد یطلق الظن بمعنی الوهم، کما فی التلویح فی رکن السنة فی بیان حکم خبر الواحد. و قد یطلق علی ما یقابل الیقین أی الاعتقاد الذی لایکون جازماً مطابقاً ثابتاً، سواءٌ کان غیر جازم أو جازماً غیر مطابق أو جازماً مطابقاً غیر ثابت . و علی هذا وقع فی البیضاوی فی تفسیر قوله تعالی : و ان هم الاّ یظنون . (قرآن <span class=\"hlight\" dir=\"rtl\">٧٨/٢</span>). و قد یطلق الظن ّ بازاء العلم علی کل ّ رأی و اعتقاد من غیرقاطع و ان جزم به صاحبه، کاعتقاد المقلد و المائل عن الحق لشبهة فیتناول الظن ّ بالمعنی المشهور الجهل المرکب و اعتقاد المقلد. هکذا یستفاد مما فی شرح المواقف و حاشیة للمولوی عبدالحکیم فی المقصد الاول من مرصد النظر. و فی کلیات ابی البقا: الظن ّ یکون معناه یقیناً و شکاً فهو من الاضداد، کالرّجاء یکون خوفاً و امناً. و الظن ّ فی الحدیث القدسی : انا عند ظن ّ عبدی بی، بمعنی الیقین و الاعتقاد. و عند المنطقیین التردد الراجح الغیرالجازم . و عند الفقهاء هو من قبیل الشک لانهم یریدون به التردد بین وجود الشی ٔ و عدمه سواء استویا أو ترجح احدهما. و العمل بالظن فی موضع الاشتباه صحیح شرعاً کما فی التحری . و غالب الظن عندهم ملحق بالیقین و هو الذی تبتنی علیه الاحکام و یعرف ذلک من تصفح کلامهم . و قد صرحوا فی نواقض الوضوء بأن ّ الغالب کالمتحقق . و صرحوا فی الطلاق بانه اذا ظن الوقوع لم یقع. و اذا غلب علی ظنه وقع. و الظن متی لاقی فصلاً مجتهداً فیه أو شبهة حکمیة وقع معتبراً. و قد یطلق الظن بازاء العلم علی کل رأی و اعتقاد من غیر قاطع و ان جزم به صاحبه، کاعتقاد المقلد و الزایغ عن الحق لشبهة. و قد یجی ٔ بمعنی التوقع کما فی قوله تعالی : یظنون انهم ملاقوا ربهم (قرآن <span class=\"hlight\" dir=\"rtl\">٤٦/٢</span>). و لا اثم فی ظن لایتکلم به و انّما الاثم فی ما یتکلم به . و لا عبرة بالظن البین خطائه کما لو ظن الماء نجساً فتوضاء به ثم تبین انه کان طاهراً جاز وضوئه . و الظنون تختلف قوة و ضعفاً دون الیقین - انتهی . ثم المقدمات الظنیة انواع : کالمشهورات . و المقبولات . و المسلمات . و المخیلات .و الوهمیات . و المقرونة بالقرائن، کنزول المطر بوجود السحاب الرطب . و تفصیل کل فی موضعه . و المظنونات وهی القضایا التی یحکم بها العقل حکماً راجحاً مع تجویز نقیضه، بمعنی انه لو خطر بالبال النقیض، لجوزه العقل صادقة کانت أو کاذبة، کما یقال فلان یطوف باللیل و کل من یطوف باللیل فهو سارق . قال المولوی عبدالحکیم فی حاشیة القطبی : قوله یحکم بها العقل حکماً راجحاً؛ أی سبب الحکم بها هو الرجحان . فیخرج المشهورات و المسلمات و المقبولات و یدخل التجربیات و المتواترات و الحدسیات الغیرالواصلة حد الجزم - انتهی . و قال الصادق الحلوانی فی حاشیة الطیبی بعد تعریفها بما ذکر: و یندرج فیها المشهورات فی بادی الرأی و بعض المشهورات الحقیقیة و المسلمات و المقبولات و کذا التجربیات الاکثریة و ما یناسبها من الاخبار القریبة من حد التواتر و الحدسیات الغیرالقویة - انتهی <span class=\"hlight\">:</span> <br />من در تو فکنده ظن نیکو<br />وابلیس ترا ز ره فکنده <br />مانند کسی که روز باران <br />بارانی پوشد از کونده .<br /> <font color=\"Red\">لبیبی .</font><br />امیر گفت : به خواجه این ظن نیست و هرگز نباشد. (تاریخ بیهقی ). به خلاف آن آمدکه ظن ّ من بود که جنگ سخت شد و در میدان جنگ کم از پانصد سوار کار میکردند و یک لشکر به نظاره بودند. (تاریخ بیهقی ). اغلب ظن من آن است که بدو بخشد و اگر خواجه شفاعت او کند که بدو بخشد خوشتر آید. (تاریخ بیهقی ). قوله تعالی : فظن ّ ان لن نقدر علیه (قرآن <span class=\"hlight\" dir=\"rtl\">٨٧/٢١</span>)؛ پنداشت که ما بر وی قادر نیستیم . (قصص الانبیاء).<br />مگر که ذات تو جان است کش نداند وهم <br />مگر که وصف تو عقل است کش نیابد ظن .<br /> <font color=\"Red\">مسعودسعد.</font><br />رای تو به یک نظره ٔ دزدیده ببیند<br />ظنی که کمین دارد در خاطر غدار.<br /> <font color=\"Red\">؟ (از کلیله و دمنه ).</font><br />شتربه حدیث دمنه بشنود... سخن اوظن ّ صدق و اعتقاد نصیحت پنداشت . (کلیله و دمنه ). چون ظن افتاد که اهل خانه را خواب ربود مقدّم دزدان هفت بار بگفت شولم شولم . (کلیله و دمنه ).<br />چون در تو ظن خلق به نیکی است نیک باش <br />تا در تو ظن خلق به نیکی شود یقین .<br /> <font color=\"Red\">سوزنی .</font><br />از حق ان الظن لایغنی رسید<br />مرکب ظن بر فلکها کی دوید.<br /> <font color=\"Red\">مولوی .</font><br />ای شغال بی جمال و بی هنر<br />هیچ بر خود ظن طاوسی مبر<br />زانکه طاوسان کنندت امتحان <br />خوار و بی رونق بمانی در جهان .<br /> <font color=\"Red\">مولوی .</font><br />من اگر ننگ مغان یا کافرم <br />آن نیم که بر خدا این ظن برم .<br /> <font color=\"Red\">مولوی .</font><br />ظنی که بیاراسته بودیم تبه گشت <br />تیری که بینداخته بودیم خطا شد.<br /> <font color=\"Red\">؟</font><br />ج، ظنون، اظانین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به ظن قوی </span> ؛ همانا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سؤظن </span> ؛ بدگمانی .<br /><BR><font color=\"Blue\">◄</font> متهم کردن . <BR><font color=\"Blue\">◄</font> تهمت نهادن .<br /></font></div>'),
(179078, 'ظن بردن', '<span class=\"hlight\">ظن بردن .</span> <font color=\"DarkGreen\"><b>[ ظَ ب ُ دَ ]</font></b> (مص مرکب ) گمان کردن <span class=\"hlight\">:</span> <br />ظن نبردم همی که چون مرغان <br />مر مرا جای در هوا باشد.<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(179079, 'ظن نیکو', '<span class=\"hlight\">ظن نیکو.</span> <font color=\"DarkGreen\"><b>[ ظَن ْ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) حسن ظن ّ <span class=\"hlight\">:</span> <br />بر ظن نیکو قصد کردم بدو<br />آزادگی کرد و وفا کرد ظن .<br /> <font color=\"Red\">فرخی .</font><br />من در تو فکنده ظن نیکو<br />ابلیس ترا ز ره فکنده .<br /><font color=\"Red\">لبیبی .</font><br /></font></div>'),
(179080, 'ظن کردن', '<span class=\"hlight\">ظن کردن .</span> <font color=\"DarkGreen\"><b>[ ظَ ک َ دَ ]</font></b> (مص مرکب ) پنداشتن . توهم کردن .<br /></font></div>'),
(179081, 'ظنابیب', '<span class=\"hlight\">ظنابیب .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) ج ِ ظُنبوب . <BR><font color=\"Blue\">◄</font> قَرَع َ ظنابیب الأمر؛ خوار گردانید آن را و رام کرد. یا آماده ٔ جنگ گردید و درآمد در امورِ شِداد.<br /></font></div>'),
(179082, 'ظنانت', '<span class=\"hlight\">ظنانت .</span> <font color=\"DarkGreen\"><b>[ ظِ ن َ ]</font></b> (ع اِمص ) تهمت .<br /></font></div>'),
(179083, 'ظنب', '<span class=\"hlight\">ظنب .</span> <font color=\"DarkGreen\"><b>[ ظِمْب ْ ]</font></b> (ع اِ) بیخ و بن درخت .<br /></font></div>'),
(179084, 'ظنبة', '<span class=\"hlight\">ظنبة.</span> <font color=\"DarkGreen\"><b>[ ظُم ْ ب َ ]</font></b> (ع اِ)پی که بر اطراف پرهائی که نزدیک سوفار است پیچند.<br /></font></div>'),
(179085, 'ظنبوب', '<span class=\"hlight\">ظنبوب .</span> <font color=\"DarkGreen\"><b>[ ظُم ْ ]</font></b> (ع اِ) کرانه ٔ پیشین ساق یا استخوان خشک ساق یا طرف استخوان ساق . حرف ساق از قدم یا استخوان آن یا حرف استخوان آن . (بحر الجواهر). <BR><font color=\"Blue\">◄</font> میخی در کعب سنان که سرنیزه در وی رود. ج، ظنابیب .<br /></font></div>'),
(179086, 'ظنة', '<span class=\"hlight\">ظنة.</span> <font color=\"DarkGreen\"><b>[ ظِن ْ ن َ ]</font></b> (ع اِ) تهمت . افتراء. بهتان . ج، ظِنن .<br /></font></div>'),
(179087, 'ظنمة', '<span class=\"hlight\">ظنمة.</span> <font color=\"DarkGreen\"><b>[ ظَ ن َ م َ ]</font></b> (ع اِ) یک شربت از شیر که مسکه از آن نگرفته باشند.<br /></font></div>'),
(179088, 'ظنن', '<span class=\"hlight\">ظنن .</span> <font color=\"DarkGreen\"><b>[ ظِ ن َ ]</font></b> (ع اِ) ج ِ ظِنّة.<br /></font></div>'),
(179089, 'ظنون', '<span class=\"hlight\">ظنون .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) مرد سُست کم حیلت . <BR><font color=\"Blue\">◄</font> زن ِ ذات شرف که به جهت آن نکاح کنند. <BR><font color=\"Blue\">◄</font> مرد بدگمان . <BR><font color=\"Blue\">◄</font> چاه که ندانند آب دارد یانه . <BR><font color=\"Blue\">◄</font> چاه کم آب . <BR><font color=\"Blue\">◄</font> وام که ندانند گزارده شود یا نه، یعنی گیرنده بازدهد یا نی .<br /></font></div>'),
(179090, 'ظنون', '<span class=\"hlight\">ظنون .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظَن <span class=\"hlight\">:</span> و فرونهادن بار امل در مهب شکوک و منزل ظنون . (کلیله و دمنه ).<br /></font></div>'),
(179091, 'ظنی', '<span class=\"hlight\">ظنی .</span> <font color=\"DarkGreen\"><b>[ ظَن ْ نی ی ]</font></b> (ص نسبی ) منسوب به ظَنّه که قبیله ای است . (سمعانی ).<br /></font></div>'),
(179092, 'ظنین', '<span class=\"hlight\">ظنین .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص ) مُتهم . مَظنون .صاحب تهمت . تُهمت زده . تهمت نهاده شده . تهمت کرده شده .<br /></font></div>'),
(179093, 'ظهار', '<span class=\"hlight\">ظهار.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) گروه . جماعت . <BR><font color=\"Blue\">◄</font> جانب کوتاه موی پر مرغ .<br /></font></div>'),
(179094, 'ظهار', '<span class=\"hlight\">ظهار.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) ظاهر زمین سنگستان و سنگناک .<br /></font></div>'),
(179095, 'ظهار', '<span class=\"hlight\">ظهار.</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع مص ) تظهیر. مظاهره . تَظَهر. با زن خود صیغه ٔ بیزاری زیرین گفتن : انت ِ عَلَی َّ کظَهْرِ اُمّی ؛ یعنی چنانکه مادر بر من حرام است تو نیز از این پس چنانی . و در این حال زن بدو حرام شود و تا کفاره ندهد حلال نگردد. ظهار در جاهلیت موجب تحریم ابدی زوجه بر زوج بود و اسلام آن را فقط سبب لزوم کفاره بر زوج در صورت اراده ٔ نزدیکی با زوجه قرار داد. از برای تحقق ظهار لازم است که زوج بالغ و عاقل و رشید باشد و دو عادل نیز جمله ٔ دال بر ظهار را استماع کنند. ظهار بالکسر لغة مصدر ظاهَرَ الرجل ؛ أی قال لزوجته انت علی کظهر امی ؛ أی انت علی ّحرام کظهر امی . فکنی عن البطن بالظهر الذی هو عمود البطن، لئلایذکر ما یقارب الفرج . ثم قیل ظاهر من امرأته، فعدّی بمن، لتضمین معنی التجنب لاجتناب اهل الجاهلیة عن المراءة المظاهر منها، اذ الظهار طلاق عندهم کما فی الکشاف . و شرعاً تشبیه مسلم عاقل بالغ زوجته أو جزء منها شائعاً کالثلث و الربع أو ما یعبر به عن الکل بما لایحل النظر الیه من المحرمة علی التأبید و لو برضاع أو صهریة و زاد فی النهایة قید الاتفاق احترازاً عما لو قال انت علی ّ مثل فلانة و فلانة ام من زنی بها أو بنتها لم یکن مظاهراً و لا فرق بین کون ذلک العضو أو غیره مما لایحل الیه النظر. و انما خص باسم الظهار تغلیباً للظهر لأنّه کان الاصل فی استعمالهم . فالتشبیه مخرج لنحو انت امی و اختی فانه لیس ظهاراً کما فی مبسوط صدرالاسلام . فلو قال ان فعلت کذا فانت امی و فعلته فهو باطل و ان نوی التحریم . و قید المسلم احتراز عن الذمی و العاقل عن المجنون و البالغ عن الصبی ّ. فان ظهار هؤلاء غیر صحیح . و الاضافة مخرجةلما قالت المراءة لزوجها انت علی ّ کظهر امی، فانه لیس بشی ٔ و عن ابی یوسف انه ظهار. و قال الحسن انه یمین کما فی المحیط. و قید الزوجة مخرج لاجنبیة أو لامته قال لها ان تزوجتک فانت علی کظهر امی . فانه لم یکن ظهاراً الا اذا تزوج الاجنبیة و الامة بعد اعتاقها فانه ینقلب ظهاراً کما فی قاضیخان و غیره . و قید علی التأبید مخرج لما اذا شبه بمزنیة الاب أو الابن فان حرمتها لاتکون مؤبدة. و لذا لو حکم بجواز نکاحها نفذ عندمحمد خلافاً لابی یوسف . و یدخل ما اذا شبه بظهر ام امراءة قبل هذه المراءة أو نظر الی فرجها بشهوة. فانه ظهار عند ابی یوسف خلافاً لابی حنیفة. ثم حکم الظهار حرمة الوطی و دواعیه الی وجود الکفارة. هکذا یستفاد من جامع الرموز و فتح القدیر. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(179096, 'ظهار', '<span class=\"hlight\">ظهار.</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (اِخ ) یکی از حصن های یهود در خیبر. (معجم البلدان ).<br /></font></div>'),
(179097, 'ظهارت', '<span class=\"hlight\">ظهارت .</span> <font color=\"DarkGreen\"><b>[ ظَ رَ ]</font></b> (ع مص ) ظَهارَة. قوی پشت گردیدن . <BR><font color=\"Blue\">◄</font> ظهر عنه العیب ؛ محو و ناپدید گردید عیب او. <BR><font color=\"Blue\">◄</font> ظهر بالبعیر؛ آماده کرد شتر را جهت حاجت . <BR><font color=\"Blue\">◄</font> ظهر بحاجتی ؛ فراموش کرد حاجت مرا.<br /></font></div>'),
(179098, 'ظهاره', '<span class=\"hlight\">ظهاره .</span> <font color=\"DarkGreen\"><b>[ ظِ رَ ]</font></b> (ع اِ) ابره . رویه . مقابل بطانه و آستر و زیره <span class=\"hlight\">:</span> قباها را ظهاره ٔ پوشش کردند. (جهانگشای جوینی ). ج، ظهائر.<br /></font></div>'),
(179099, 'ظهاری', '<span class=\"hlight\">ظهاری .</span> <font color=\"DarkGreen\"><b>[ ظَ ری ی ]</font></b> (ع ص، اِ) ج ِ ظِهری ّ. شتران آماده جهت حاجت .<br /></font></div>'),
(179100, 'ظهاریة', '<span class=\"hlight\">ظهاریة.</span> <font color=\"DarkGreen\"><b>[ ظُ ری ی َ ]</font></b> (ع اِ) بندی از بندهای کشتی گیران و یا آن شغزبیة است که پای درپیچیدن باشد و یا بر پشت افکندن حریف را. <BR><font color=\"Blue\">◄</font> نوعی از آرمش با زنان . <BR><font color=\"Blue\">◄</font> اوثقه الظهاریة؛ محکم بست شانه ٔ او را.<br /></font></div>'),
(179101, 'ظهر', '<span class=\"hlight\">ظهر.</span> <font color=\"DarkGreen\"><b>[ ظَ هََ ]</font></b> (ع اِ) درد پشت . پشت درد.<br /></font></div>'),
(179102, 'ظهر', '<span class=\"hlight\">ظهر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع اِ) پُشت . ضدّ بَطن . ج، اَظْهُر، ظُهور، ظُهران . <BR><font color=\"Blue\">◄</font> چارپای بارکش . <BR><font color=\"Blue\">◄</font> ستور برنشست . و منه : لِص ﱡ عادی ظَهر؛ یعنی درآمد در شتران و دزدید. <BR><font color=\"Blue\">◄</font> بار. <BR><font color=\"Blue\">◄</font> دیگ کهنه . <BR><font color=\"Blue\">◄</font> مال بسیار. <BR><font color=\"Blue\">◄</font> فخر به چیزی . <BR><font color=\"Blue\">◄</font> جانب کوتاه موی پر مرغ : رِش سهمک بظهران و لاترشه ببطنان . <BR><font color=\"Blue\">◄</font> راه درشت . <BR><font color=\"Blue\">◄</font> زمین بلند درشت . <BR><font color=\"Blue\">◄</font> لفظ قرآن . خلاف بطن که تأویل آن است و حدیث و خبر. <BR><font color=\"Blue\">◄</font> آنچه از تو غائب باشد. <BR><font color=\"Blue\">◄</font> به پشت رسیدن چیزی . <BR><font color=\"Blue\">◄</font> اعطاه عن ظهر ید؛ یعنی بی مکافات داد او را. <BR><font color=\"Blue\">◄</font> خفیف الظهر؛ کم عیال . <BR><font color=\"Blue\">◄</font> ثقیل الظهر؛ بسیارعیال . <BR><font color=\"Blue\">◄</font> هو علی ظهرسفر؛ او آماده ٔ راه است . <BR><font color=\"Blue\">◄</font> اقران الظهر؛ از پس پشت درآیندگان در حرب . <BR><font color=\"Blue\">◄</font> لاتجعل حاجتی بظهر؛ فراموش مکن . پس پشت میفکن . <BR><font color=\"Blue\">◄</font> سال وادیهم ظهراً؛ روان شد رودبار ایشان از باران زمین ایشان، خلاف سال وادیهم درٔاً یعنی روان شد از آب زمین دیگران . <BR><font color=\"Blue\">◄</font> اصبت منک مَطر ظهر؛ از تو رسید مرا خیر بسیار. <BR><font color=\"Blue\">◄</font> هو یأکل علی ظهر یدی ؛ نفقه ٔ او من میدهم . <BR><font color=\"Blue\">◄</font> هو بین ظهریهم ؛او در میانه و در معظم ایشان است . و کذا بین ظهرانیهم . <BR><font color=\"Blue\">◄</font> نزل بین ظهریهم ؛ فرودآمد پس پشت آنها. <BR><font color=\"Blue\">◄</font> لقیته بین الظهرین و بین الظهرانین ؛ یعنی ملاقات کردم او را بعد دو روز یا سه روز. <BR><font color=\"Blue\">◄</font> جاء فلان بین ظهریه ؛ أی قومه . <BR><font color=\"Blue\">◄</font> فانزل بین ظهرانیکم و ظهریکم ؛ أی فی وسطکم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> عن ظهر القلب ؛ از حفظ. از بر.<br /></font></div>'),
(179103, 'ظهر', '<span class=\"hlight\">ظهر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع مص ) مبتلی به درد پشت شدن . دردمند شدن پشت . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بر جای بلند شدن . <BR><font color=\"Blue\">◄</font> دست یافتن . <BR><font color=\"Blue\">◄</font> آشکار شدن . (زوزنی ). <BR><font color=\"Blue\">◄</font> غلبه . <BR><font color=\"Blue\">◄</font> امداد. پشت به پشت دادن .<br /></font></div>'),
(179104, 'ظهر', '<span class=\"hlight\">ظهر.</span> <font color=\"DarkGreen\"><b>[ ظَ هَِ ]</font></b> (ع ص ) دردگن پُشت . مبتلی به پشت درد.رجل ٌ ظَهر؛ مردی که پشتش درد کند. (مهذب الاسماء).<br /></font></div>'),
(179105, 'ظهر', '<span class=\"hlight\">ظهر.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) پس از زوال آفتاب . ظاهِرة. گرمگاه . چاشت . نیم روز. پیشین . مقابل ضحی که نیم چاشت است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">صلوةالظهر</span> ؛ نماز پیشین .<br /></font></div>'),
(179106, 'ظهر', '<span class=\"hlight\">ظهر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) جایگاهی است و بدانجا وقعه ای بوده است میان عمروبن تمیم و بنی حنیفه . (معجم البلدان ).<br /></font></div>'),
(179107, 'ظهر حمار', '<span class=\"hlight\">ظهر حمار.</span> <font color=\"DarkGreen\"><b>[ ظَ رُ ح ِ ]</font></b> (اِخ ) دهی است بین نابلس و بیسان که گویند قبر بنیامین برادر یوسف آنجاست .<br /></font></div>'),
(179108, 'ظهر رانتل', '<span class=\"hlight\">ظهر رانتل .</span><font color=\"DarkGreen\"><b>[ ظَ رُ ت ِ ]</font></b> (اِخ ) رجوع به قلعه ٔ ظهر رانتل شود.<br /></font></div>'),
(179109, 'ظهرالبطن', '<span class=\"hlight\">ظهرالبطن .</span> <font color=\"DarkGreen\"><b>[ ظَ رُل ْ ب َ ]</font></b> (ع اِ مرکب ) زیر و زبر.<br /></font></div>'),
(179110, 'ظهرالبلد', '<span class=\"hlight\">ظهرالبلد.</span> <font color=\"DarkGreen\"><b>[ ظَ رُل ْ ب َ ل َ ]</font></b> (ع اِ مرکب ) بیرون شهر.<br /></font></div>'),
(179111, 'ظهرالکف', '<span class=\"hlight\">ظهرالکف .</span><font color=\"DarkGreen\"><b>[ ظَ رُل ْ ک َف ف ]</font></b> (ع اِ مرکب ) پشت پنجه . پشت دست .<br /></font></div>'),
(179112, 'ظهران', '<span class=\"hlight\">ظهران .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) دهی است به بحرین . <BR><font color=\"Blue\">◄</font> کوهی در اطراف قنان . <BR><font color=\"Blue\">◄</font> رودباری است نزدیک مکّه، میان مکه و عسفان . آن را مرّالظهران نیز گویند.<br /></font></div>'),
(179113, 'ظهران', '<span class=\"hlight\">ظهران .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظَهر.<br /></font></div>'),
(179114, 'ظهرانی', '<span class=\"hlight\">ظهرانی .</span> <font color=\"DarkGreen\"><b>[ ظَ]</font></b> (ص نسبی ) منسوب به یکی از ظَهرانها. ثوب ظَهرانی ّمنسوب به ظَهران بحرین است، و گفته اند ظهران یمن .<br /></font></div>'),
(179115, 'ظهرانین', '<span class=\"hlight\">ظهرانین .</span> <font color=\"DarkGreen\"><b>[ ظَ ن َ ]</font></b> (ع اِ) لقیته ُ بین الظهرین و بین الظّهرانین ؛ یعنی ملاقات کردم او را بعد دو روز یا سه روز.<br /></font></div>'),
(179116, 'ظهرنویسی', '<span class=\"hlight\">ظهرنویسی .</span> <font color=\"DarkGreen\"><b>[ ظَ ن ِ ]</font></b>(حامص مرکب ) پشت نویسی .<br /></font></div>'),
(179117, 'ظهرکوک', '<span class=\"hlight\">ظهرکوک .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ص مرکب ) ساعتی که ظهر به ظهر کوک کنند، یعنی اول روز را از ظهر گیرند نه از طلوع آفتاب .<br /></font></div>'),
(179118, 'ظهری', '<span class=\"hlight\">ظهری .</span> <font color=\"DarkGreen\"><b>[ ظِ ری ی ]</font></b> (ع ص ) پس پشت انداخته . فراموش کرده . قوله تعالی <span class=\"hlight\">:</span> ورأکم ظهریاً (قرآن <span class=\"hlight\" dir=\"rtl\">٩٢/١١</span>)؛ أی بظهر و هو ان تنساه و تغفل عنه . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> شتر آماده ٔ جهت حاجت . ج، ظهاری ّ.<br /></font></div>'),
(179119, 'ظهری', '<span class=\"hlight\">ظهری .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ص نسبی ) منسوب به ظهر که بطنی است از حِمْیَر. (سمعانی ).<br /></font></div>'),
(179120, 'ظهرین', '<span class=\"hlight\">ظهرین .</span> <font color=\"DarkGreen\"><b>[ ظُ رَ ]</font></b> (ع اِ) نماز ظهر و عصر. رجوع به صلوة شود.<br /></font></div>'),
(179121, 'ظهور', '<span class=\"hlight\">ظهور.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع مص ) آشکار شدن . آشکارا شدن . پدید آمدن . پدیدار شدن . ظاهر شدن <span class=\"hlight\">:</span> مرد... توبه کرد که پیش از ظهور حجتی بر امثال این کار اقدام ننماید. (کلیله و دمنه ). و چنانکه ظهور آن بی ادوات آتش زدن ممکن نگردد اثر این بی تجربت و ممارست هم ظاهر نشود. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> پیدایش . <BR><font color=\"Blue\">◄</font> پیدائی . وضوح . هویدائی . آشکاری . ابانت . بروز. تجلی . رونمائی . بداهت . <BR><font color=\"Blue\">◄</font> بر جای بلند شدن : ظهر علیه ؛ به بام برآمد. <BR><font color=\"Blue\">◄</font> ظَهر علی ؛ یاری داد مرا. <BR><font color=\"Blue\">◄</font> دست یافتن . چیره شدن : ظهر به و علیه ؛ چیره گردید بر وی . <BR><font color=\"Blue\">◄</font> ظَهر بفلان ؛ آشکار کرد او را. <BR><font color=\"Blue\">◄</font> اطلاع بر سِرّ. <BR><font color=\"Blue\">◄</font> فخر به علم . <BR><font color=\"Blue\">◄</font> مرتبه ٔ بالا گرفتن . <BR><font color=\"Blue\">◄</font> به پشت زدن . <BR><font color=\"Blue\">◄</font> (اصطلاح نجوم ) در تحت الشعاع نبودن کوکب .<br /></font></div>'),
(179122, 'ظهور', '<span class=\"hlight\">ظهور.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) شهری است در بحر از سرزمین مَهرة در اقصای یمن .<br /></font></div>'),
(179123, 'ظهور', '<span class=\"hlight\">ظهور.</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (ع اِ) ج ِ ظَهر.<br /></font></div>'),
(179124, 'ظهوری', '<span class=\"hlight\">ظهوری .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) تبریزی . شاعری است . از اوست :<br />چه رشک میبری ای دل به کشتگان غمش <br />تو هم به مقصد خود میرسی شتاب مکن .<br /></font></div>'),
(179125, 'ظهوری', '<span class=\"hlight\">ظهوری .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) شیرازی . شاعری است . از اوست :<br />تو پاک دامنی از ما ز رشک نزدیک است <br />که سر به وادی تهمت دهی گمان مرا<br />اگر دروغ وگر راست حرفها دارم <br />ز غیر زود ببر یا ببر زبان مرا.<br /></font></div>'),
(179126, 'ظهوری', '<span class=\"hlight\">ظهوری .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) ترشیزی . از شعرای خراسان است . او به هندوستان مسافرت کرد و به خدمت ابراهیم عادلشاه ثانی رسید و ساقی نامه ٔ خود را که حاوی چهارهزار بیت است به نام وی پرداخت . او را دیوانی است و هم سه رساله به نام «خوان خلیل » و «رساله ٔ نورس » و «گلزار ابراهیم » و کتاب منشآت . وفات او در <span class=\"hlight\" dir=\"rtl\">١٠٢٦</span> هَ . ق . روی داد. از اوست :<br />بهار است بی می حرام است زیست <br />بر احوال زهاد باید گریست <br />بهار است رخت ورع کن گرو<br />می کهنه دارد کنون سال نو.<br /></font></div>'),
(179127, 'ظهوری', '<span class=\"hlight\">ظهوری .</span> <font color=\"DarkGreen\"><b>[ ظُ ]</font></b> (اِخ ) از قدمای شعرای عثمانی است منسوب به خانواده ٔ دلبندزاده از اهل مناستر و به همانجا درگذشته است .<br /></font></div>'),
(179128, 'ظهون', '<span class=\"hlight\">ظهون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) سنّور وحشی است و به فارسی گربه ٔ دشتی نامند. (فهرست مخزن الادویة).<br /></font></div>'),
(179129, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) ابن رافع. صحابی است .<br /></font></div>'),
(179130, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ع ص، اِ) هم پشت . مدد. یار. یاور. مددکار. ظِهرة. ظُهرة. پشتیوان . پشتیبان . یاریگر. کمک . ج، ظُهَراء. (مهذب الاسماء)<span class=\"hlight\">:</span> و الملائکة بعد ذلک ظهیر. (قرآن <span class=\"hlight\" dir=\"rtl\">٤/٦٦</span>).<br />بدان منگر ای خواجه گر ظاهری <br />نبینی همی مرد دین را ظهیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />پشت احکام قران بود به شمشیر خدای <br />بهتر از تیغ سخن را نبود هیچ ظهیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />نان پاره ٔ خویشتن بجستم <br />از شاه، ظهیر دولت و داد.<br /> <font color=\"Red\">مسعودسعد.</font><br />ظهیر ملّت و ملک و نصیر دولت و دین <br />به راستی و سزا بودش از خلیفه خطاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />عالم عادل مؤید مظفر منصور ظهیر سریر سلطنت و مشیر تدبیر مملکت . (گلستان ). <BR><font color=\"Blue\">◄</font> نیم روز. گرمگاه . ظهیرة. ظُهر. <BR><font color=\"Blue\">◄</font> دردپشت رسیده . مبتلی به پشت درد. <BR><font color=\"Blue\">◄</font> قوی پشت از شتر و جز آن : بعیر ظهیر؛شتر قوی (مذکر و مؤنث در آن یکسان است ).<br /></font></div>'),
(179131, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ظَ ]</font></b> (اِخ ) ابوبکر احمدبن علی بلخی . متوفی در <span class=\"hlight\" dir=\"rtl\">٥٥٣</span> هَ . ق . او راست : شرح الجامع الصغیر محمدبن حسن شیبانی، ممدوح مسعودسعد. رجوع به شواهد کلمه ٔ ظهیر شود.<br /></font></div>'),
(179132, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) ابن محمد ابوالمنذر. تابعی است .<br /></font></div>'),
(179133, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظُ هََ ]</font></b> (اِخ ) نام گروهی است از عرب . رجوع به بنی ظهیر شود.<br /></font></div>'),
(179134, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) حسن بن ظئر، مکنی به ابی علی فارسی، معروف به ظهیر. مردی فقیه و لغوی و نحوی بود و در قاهره به سال <span class=\"hlight\" dir=\"rtl\">٥٩٨</span> هَ . ق . بدرود حیات گفت . یاقوت گوید ابوجعفر محمدبن عبدالعزیز الادریسی الحسنی الصعیدی شاگرد ظهیر در قاهره به سال <span class=\"hlight\" dir=\"rtl\">٦١٢</span> مرا گفت که : ظهیر در کتابها و فتاوی خود می نوشت الحسن النعمانی . من از این نسبت وی پرسیدم . گفت من نعمانی و از اولاد نعمان بن المنذرم و مولدم دهی است مشهور به نعمانیه، از آنجا به شیراز آمدم و به فارسی شهرت یافتم . ظهیر مردی بود به فنون علوم و قرائت عشره و شواذ و تفسیر قرآن از ناسخ و منسوخ عالم و در فقه و خلاف و کلام و منطق و حساب و هیأت و طب مبرز و در لغت و نحو و عروض و قوافی و روایت اشعار عرب و ایام ایشان و اخبار پادشاهان عجم و عرب چیره دست . و در هر فنی از این فنون و علوم کتابی از بر داشت چنانکه در تفسیر، کتاب لباب التفسیر از تاج القراء و در فقه کتاب الوجیز از غزالی و در فقه ابی حنیفه کتاب جامعالصغیراز محمدبن حسن شیبانی به نظم نسفی و در کلام کتاب نهایةالاقدام از شهرستانی و در لغت کتاب الجمهرة ابن دُرید و این کتاب اخیر را چنان از پی هم نقل میکرد که قاری فاتحةالکتاب را. و خود وی مرا گفت که علوم را درالواحی می نوشتم چنانکه قرآن را برای حفظ و از بر کردن خوانند و مکرر میخواندم تا در مدت چهارده سال همه را حفظ کردم . و در نحو کتاب ایضاح از ابی علی و عروض صاحب بن عباد و در منطق ارجوزه ٔ ابوعلی بن سینا را ازبر داشت و به قانون طب ابن سینا واقف و به لغت عبرانی عارف بود و با اهل آن زبان مناظره میکرد چنانکه گفتی حِبری از احبار یهود است . تسلط ظهیر بیش از همه چیز در فن ادب بود چنانکه وقتی شیخ ابوالفتح عثمان بن عیسی النحوی البلطی که در این وقت شیخ اهل زمان خویش در دیار مصر بود چون شاگردی و مستفیدی درباره ٔ لغت از وی سوءالها میکرد و از جمله روزی که من نیز حضور داشتم از وی از امثال کلمه ٔ شقحطب پرسید. وی در جواب او گفت این گونه کلمات را که در زبان عرب افتد منحوت خوانند و از منحوت آن خواهند که کلمه از دو کلمه ٔ دیگر ساخته شده باشد، چنانکه نجار از دو چوب یک آلت سازد. شقحطب نیز منحوت از شق و حطب است . بلطی باز درخواست تا از نظائر شقحطب که در زبان عرب آمده است اورا آگاه سازد تا در شناختن نوع آن کلمات وی را تکیه گاه و معوّلی باشد و او مقدار بیست ورق از حفظ در این معنی بر وی فروخواند و آن را کتاب تنبیه البارعین علی المنحوت من کلام العرب نامید. و گفت السعید اباالقاسم هبةاﷲبن الرشید جعفربن سناءالملک را دیدم که از وی به وجه امتحان از کلمات غریب کلام عرب سؤال کردی ووی به شوارد آن جواب گفتی . و باز ابوجعفر گفت که ظهیر مرا گفت چون به خوزستان درآمدم مجیر بغدادی شاگردشهرستانی را دیدار کردم و وی در علوم نظری تبرز داشت . فرمانروای خوزستان بر آن شد که مناظره ای در مجلس خویش میان ما ترتیب دهد. این خبر به من رسید و دانستم که بضاعت وی در کلام وافر لیکن معرفت او به لغت اندک است . از این روی چون به مناظره نشستیم و مجلس به دانشمندان پر بود، بدو گفتم : تعرض الکلام اذاً اء فرأیت الطلة الی قرینها فارها فی و بصان أو الجساد اذاتأشب بی المغیث . و او معنی آن کلمات از من درخواست و من از روی تعنت گفتم بنگرید مدعی مرتبت امامت را که از زبان عرب که کلام خدای تعالی بدان زبان نازل و احادیث سیدالمرسلین بدان ادا شده است آگاه نیست . کلمه ٔ مناظره مشتق از نظر باشد یعنی نظیر را سزد با نظیر خود مناظره کردن و این مرد نظیر من نیست، چه او یک علم از علومی را که مجتهد از دانستن آنها ناگزیر است (یعنی علم لغت ) فاقد می باشد. و از این گفتار من همهمه در مجلسیان درافتاد وبر دو فرقه شدند، فرقه ای با من و فرقه ای بر من و مجلس در همین محاجه و خلاف پایان یافت و مردم بپراکندندو در شهر شهرت افتاد که من مجیر را مجاب و مفحم کرده ام . و ظهیر مدتی در قدس شریف اقامت گزید و در نزدیک صخره ای درس میگفت و روزی ملک العزیز عثمان بن صلاح بن یوسف آنگاه که وی مشغول تدریس بود بر وی گذر کرد و ازکسان از حال وی بپرسید و چون مرتبت ظهیر را در علوم بدانست وی را طلبید و به مصاحبت خویش ترغیب کرد و قصدش این بود که شهاب الدین ابوالفتح طوسی را به وسیله ٔاو بشکند و بمالد. پس ظهیر با وی به قاهره شد و ملک ماهیانه شصت دینار مقرری او کرد و صد رطل نان و بره ای و به هر روز شمعی و چیزهای دیگر و اصناف مردم بدومیل کردند و بر رونق بازار او بیفزود تا عزیز مجلس مناظره ای مقرر داشت میان او و طوسی فردای عید. و ظهیر قصد کرد که با وی نیز همچون مجیر عمل کند، چه طوسی مردی قلیل المحفوظات ولی جری و شدیدالمعارضه و مقدام بود. اتفاقاً روز عید ملک عزیز برنشست و طوسی و ظهیر با وی برنشستند. ظهیر در میان سخن ملک عزیز را گفت : «انت یا مولانا من اهل الجنة». طوسی را گزکی به دست افتاد و گفت و ما یدریک انه من اهل الجنة و کیف تزکی علی اﷲ تعالی . فقال له الظهیر قد زکی رسول اﷲ (ص ) اصحابه فقال ابوبکر فی الجنة و عمر فی الجنة فقال له ابیت یا مسکین الا جهلاً ماتفرق بین التزکیة عن اﷲ و التزکیة علی اﷲ و انت من اخبرک أن ّ هذا من اهل الجنةما انت الا کما زعموا ان فأرة وقعت فی دن خمر فشربت فسکرت فقالت این القطاط فلاح لها هرﱡ فقالت لاتؤاخذ السکاری بما یقولون . و انت شربت من خمر دن نعمة هذا الملک فسکرت فصرت تقول خالیاً این العلماء فابلس و لم یجد جواباً و انصرف و قدانکسرت حرمته عند العزیز و شاعت هذه الحکایة بین العوام و صارت تحکی فی الاسواق و المحافل فکان مآل امره ان انضوی الی المدرسة التی انشأها الامیر ترکون الاسدی یدرس بها مذهب ابی حنیفة الی ان مات . وی کتابی در تفسیر قرآن بر شاگردان خود املاء میکرد و پس از سالها به تفسیر این آیه رسید: «تلک الرُسل فضلنا بعضهم علی بعض » (قرآن <span class=\"hlight\" dir=\"rtl\">٢٥٣/٢</span>) در مقدار دویست ورق و بمرد و تفسیر سوره ٔ بقره را به پایان نرسانید و او را کتابی است در شرح الصحیحین بر ترتیب حمیدی که آن را کتاب الحجة نامیده است و آن اختصار کتاب الافصاح فی تفسیر الصحاح وزیر ابن هبیره است وچیزهائی را که مناسب شمرده بر آن افزوده است . و نیزکتابی دارد در اختلاف الصحابة و التابعین و فقهاء الانصار که به انجام نرسانیده است . و نیز او را خطب و فصول وعظیّه است که مشحون به غریب و حوشاء لغت است . ورجوع به معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٦٤</span>-<span class=\"hlight\" dir=\"rtl\">٦٨</span> شود.<br /></font></div>'),
(179135, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) ظهیرالدین طاهربن محمد الفاریابی، مکنی به ابوالفضل، ملک الکلام و صدرالحکماء. دولتشاه سمرقندی در تذکره گوید: شاعری است به غایت اهل و فاضل ودر شاعری مرتبه ٔ عالی دارد چنانکه بعضی از اکابر و افاضل متفقند که سخن او نازکتر و باطراوت تر از سخن انوری است و بعضی قبول نکرده اند و از خواجه مجدالدین همگر فارسی در این باب فتوی خواسته اند، او حکم کرده که سخن انوری افضل است فی کل حال . در شیوه ٔ شاعری مشارالیه است و در علم و فضل بی نظیر. اصل او از فاریاب است اما در روزگار اتابیک قزل ارسلان بن اتابیک ایلدگزبه عراق و آذربایجان افتاده و مداح قزل ارسلان بوده وخواجه ظهیر شاگرد استاد رشیدی سمرقندی است که قصه ٔ مهر و وفا به نظم آورده و داد سخنوری در نظم آن داستان داده و در باب خواجه ظهیرالدین بزرگان گفته اند:<br />دیوان ظهیر فاریابی <br />در کعبه بدزد اگر بیابی .<br />و عوفی گوید: در دولت اتابیک ابوبکر آسایشها یافت و چنین شنیدم از بزرگی که شبی در مجلس اتابیک ابوبکر این رباعی بگفت :<br />ای ورد ملائکه دعای سر تو<br />سر نیست زمانه را به جای سر تو<br />با دشمن تو نیام شمشیر تو گفت <br />سرّ دل من باد قضای سر تو.<br />تمامت دیوان ظهیر مطبوع و مصنوع است وشعر او لطفی دارد که لطف او هیچ شعر دیگر ندارد. وفات ظهیر در <span class=\"hlight\" dir=\"rtl\">٥٩٨</span> هَ . ق . در تبریز بود. از ممدوحین وی حسام الدین اردشیربن علاءالدوله حسن از طبقه ٔ دوم ملوک آل باوند (<span class=\"hlight\" dir=\"rtl\">٥٦٧</span> تا <span class=\"hlight\" dir=\"rtl\">٦٠٢</span>) و طغانشاه حاکم نیشابور (<span class=\"hlight\" dir=\"rtl\">٥٦٩</span>تا <span class=\"hlight\" dir=\"rtl\">٥٨١</span>) و محمدبن ایلدگز و قزل ارسلان و نصرةالدین ابوبکر از اتابکان آذربایجان را میتوان نام برد. خاقانی و جمال الدین عبدالرزاق - که ترکیب بند مفصل و شیوائی در مدح ظهیرالدین فاریابی که او نیز در ستایش جمال الدین ابیاتی گفته دارد - از معاصرین ظهیر هستند. ازاشعار اوست :<br />سپیده دم که شدم محرم سرای سرور<br />شنیدم آیت توبوا الی اﷲ از لب حور<br />به گوش جان من آمد نداء حضرت قدس <br />که ای خلاصه ٔ تقدیرو زبده ٔ مقدور<br />جهان رباط خراب است بر گذرگه سیل <br />گمان مبر که به یک مشت گل شود معمور<br />بر آستان فنا دل منه که جای دگر<br />برای عشرت تو برکشیده اند قصور<br />مگر تو بی خبری کاندر این مقام ترا<br />چه دشمنان حسودند و دوستان غیور<br />بکوش تا به سلامت به مأمنی برسی <br />که راه سخت مخوف است و منزلی بس دور<br />ببین که تا چه نشیب وفراز در پیش است <br />زآستان عدم تا به پیشگاه نشور<br />ترا مسافت دور و دراز در پیش است <br />بدین دوروزه اقامت چرا شوی مغرور<br />تو در میان گروهی غریب مهمانی <br />چنان مکن که به یکبارگی شوند نفور<br />ببین که تا شکمت سیر و تنْت پوشیده ست <br />چه مایه جانورند از تو خسته و رنجور<br />چه بارهاست ز تو بر تن سوام و هوام <br />چه داغهاست ز تو بر دل وحوش و طیور<br />به دشت جانوری خار میخورد غافل <br />تو تیز میکنی از بهر سلب او ساطور<br />کناغ چند ضعیفی ز خون دل بتند<br />به محفل آری کین اطلس است و آن سیفور<br />بدان طمع که دهان خوش کنی ز غایت حرص <br />نشسته ای مترصد که قی کند زنبور<br />ز کرم مرده کفن برکشی و درپوشی <br />میان اهل مروت که داردت معذور<br />به وقت روز شود همچو صبح معلومت <br />که با که باخته ای عشق در شب دیجور<br />به باده دست میالای کآن همه خون است <br />که قطره قطره چکیده ست از دل انگور<br />دل مرا چو گریبان گرفت جذبه ٔ حق <br />فشاند دامن همت به خاکدان غرور<br />بشد ز خاطرم اندیشه ٔ می و معشوق <br />برفت از سرم آواز بربط و طنبور<br />ز هرچه کردم و گفتم کنون پشیمانم <br />به جز دعاو ثناء خدایگان صدور<br />وزیر مشرق و مغرب نصیر دولت و دین <br />که باد رایت عالیش تا ابدمنصور<br />نه بر حدیقه ٔ فکرش وزیده باد غلط<br />نه بر صحیفه ٔ عزمش نشسته گرد فتور<br />ز طول و عرض جهان کمال او صد ره <br />مهندسان خرد معترف شده به قصور<br />نشسته در دل و چشم ملوک هیبت او<br />چنانکه صولت می درطبیعت مخمور<br />زهی دقایق لطفت خفی چو جرم سها<br />ولیک گشته چو خورشید در جهان مشهور<br />صریر کلک تو درکشف مشکلات جهان <br />چنانکه نغمه ٔ داود در اداء زبور<br />به زیر دامن افلاک خلقت آن مجمر<br />که کرد جیب افق را پر از بخار بخور<br />به گرد خطه ٔ اسلام حفظت آن خندق <br />که می نیابد شِعری ̍ بر او مجال عبور<br />سوی حریم خلافت ترا همان آتش <br />نموده راه که اول کلیم را سوی طور<br />تو روی با علمی کرده ای که رایت صبح <br />به زیر سایه ٔ آن گم شود به وقت ظهور<br />ترا به حبل متین است اعتصام چه باک <br />اگر گسسته شود رشته ٔ سنین و شهور<br />چراغ بخت تو زآن شمع برفروخته اند<br />که آفتاب به پروانه خواهد از وی نور<br />نهال جاه تو زآن حوض یافته ست نما<br />که از ترشح اوحاصل آمده ست بحور<br />فراست تو چو افکند نور بر عالم <br />نماند در تتق غیب هیچ سِر مستور<br />همای همت تو گردنان گردون را<br />ز عجز و ضعف چو عصفور دید و ما العصفور<br />همیشه تا نتوان کرد حصر دورفلک <br />ترا چو خور به فلک باد عمر نامحصور<br />صلاح ملک و ملل بر عنایتت مبنی <br />دوام دین و دول بر کفایتت مقصور.<br />قصیده :<br />تا غمزه ٔ تو تیر جفا بر کمان نهاد<br />خوی تو رسم خیره کشی در جهان نهاد<br />بس جان نازنین که بلا را نشان شده <br />زآن تیرها که غمزه ٔتو در کمان نهاد<br />صبری که در میان غمم دستگیر بود<br />از دست محنت تو قدم بر کران نهاد<br />عیبی که چشم عقل بدوزد ز تیرگی <br />دست زمانه در سر زلفت عیان نهاد<br />و اندیشه ای که گم شود از لطف در ضمیر<br />گردون به راز با کمرت در میان نهاد<br />بر ره نشسته دیده که تا چون وفا شود<br />آن وعده ها که لطف تو در گوش جان نهاد<br />در خط شوم ز سبزه ٔ خطّ تو هر زمان <br />تا لب چرابر آن لب شکّرفشان نهاد<br />بر سر زنم ز غیرت زلفت که از چه روی <br />سر بر کنار تازه گل و ارغوان نهاد<br />اینگونه مشکلات که در راه عشق تست <br />دل بر وفای عهد تو مشکل توان نهاد<br />دانم یقین که نشکند الا ثنای شاه <br />مهری که عشوه ٔتو مرا بر زبان نهاد<br />منت خدای را که به نام خدایگان <br />بر چرخ پیر مسند بخت جوان نهاد<br />دست زمانه گوهر شاهی به فال نیک <br />در آستین حکم قزل ارسلان نهاد<br />شاه جهان مظفردین خسرو عجم <br />کز فخر پای بر سر هفت آسمان نهاد<br />در تنگنای بیضه ٔ تدبیر عدل او<br />نقاش طبع صورت مرغ شیان نهاد<br />قدرش رکاب با فلک اندر رکاب شد<br />فرمانْش با زمانه عنان در عنان نهاد<br />ای صفدری که در صف هیجا ترا خرد<br />همتای پیل جنگی و شیر ژیان نهاد<br />از انتقام عدل تو با ضعف خویش کبک <br />در چشم باشه و دل باز آشیان نهاد<br />چشم بنفشه صورت قهرت به خواب دید<br />سر چون عدوت بر سر زانو از آن نهاد<br />بر بام هفت قلعه ٔ گردون هزار شب <br />حزم تو پای بر زبر پاسبان نهاد<br />تو بی قرینی از همه اقران از آن قِبَل <br />نامت زمانه خسرو صاحبقران نهاد<br />دستت سبک مخالف دین را به باد داد<br />زآن بادها که در سر گرز گران نهاد<br />جاه تو اسب بر سر مهر سپهر تاخت <br />جود تو داغ بر دل دریا و کان نهاد<br />جز سرمه ٔ اجل نبرد حسرتی که دهر<br />در چشم دشمن تو به نوک سنان نهاد<br />تیر تو مسرعی است که پیش از زه کمان <br />تقدیر مژده ٔ ظفرش در دهان نهاد<br />آن سر که چرخ از سر تکلیف برگرفت <br />در امتثال حکم تو بر آستان نهاد<br />تا در قبول عقل نیاید که آدمی <br />دل بر بقاء مملکت جاودان نهاد<br />جاوید زی که نوبت ملک ترا قضا<br />در وجه دفع فتنه ٔ آخر زمان نهاد.<br />همو راست :<br />شرح غم تو لذت شادی به جان دهد<br />لعل لب تو طعم شکر در دهان دهد<br />طاوس جان به جلوه درآید ز خرّمی <br />گر طوطی لبت به حدیثی زبان دهد<br />شمعی است چهره ٔ تو که هر شب ز نور خود<br />پروانه ٔ عطا به مه آسمان دهد<br />خلقی ز پرتو تو چو پروانه سوختند<br />کس نیست کز حقیقت رویت نشان دهد<br />زلفت به جادوئی ببرد هر کجا دلی است <br />وآنگه به چشم و ابروی نامهربان دهد<br />هندو ندیده ام که چو ترکان جنگجوی <br />هرچ آیدش به دست به تیر و کمان دهد<br />جز زلف و چهره ٔ تو ندیدم که هیچ کس <br />خورشید را ز ظلمت شب سایبان دهد<br />مقبل کسی بودکه ز خورشید عارضت <br />هجرانْش تا به سایه ٔ زلفت امان دهد<br />گر در رخم بخندی بر من منه سپاس <br />کآن خاصیت همی رخ چون زعفران دهد<br />وقت است اگر لب تو به عهد مزوّری <br />بیمار عشق را شکر و ناردان دهد<br />مائیم و آب دیده که سقّای کوی دوست <br />صد مشک از این متاع به یک تای نان دهد<br />آن بخت کو که عاشق رنجور قوتی <br />با این دل ضعیف و تن ناتوان دهد<br />وآن طاقت از کجا که صدائی ز درد دل <br />در بارگاه خسرو خسرونشان دهد<br />فریاد من زطارم گردون گذشت و نیست <br />امکان آن که زحمت آن آستان دهد<br />نُه کرسی فلک نهد اندیشه زیر پای <br />تا بوسه بر رکاب قزل ارسلان دهد<br />در موضعی که چون دم روح القدس ز باد<br />نصرت همای رایت او راروان دهد<br />تیغش ز کله ٔ سر بی مغز دشمنان <br />نسرین چرخ را چو هما استخوان دهد<br />در برگ ریز عمر عدو صرصر اجل <br />نوروز را طبیعت فصل خزان دهد<br />واطراف باغ معرکه را تیغ آب رنگ <br />از خون کشتگانْش گل و ارغوان دهد<br />تردامنی ّ دشمنش از روی خاصیت <br />رنگ از برون جوشن و برگستوان دهد<br />راه نجات بسته شود بر زمین چنانک <br />مرگ از حذر عنان به ره کهکشان دهد<br />هر سرگرانیی که کند خصم تو به عمر<br />بازوش وقت حمله به گرز گران دهد<br />ای خسروی که حفظ تو هنگام اهتمام <br />گوگرد را ز صولت آتش امان دهد<br />هرجا که رأیت از در تدبیر درشود<br />تقدیر بر وساده ٔ حکمش مکان دهد<br />پیرند چرخ و اختر و بخت تو نوجوان <br />آن به که پیر نوبت خود با جوان دهد<br />فرّ همای سلطنت آن را بود به حق <br />کش حکم توبه سایه ٔ چترش امان دهد<br />هر آهنی که در سر چوبی کنند راست <br />چون رمح تو چگونه قرار جهان دهد<br />اعجاز موسوی ندهد هر کجا کسی <br />چوبی شعیب وار به دست شبان دهد<br />صد قرن بر جهان گذرد تا زمام ملک <br />اقبال در کف چو تو صاحبقران دهد<br />در رزم رستمی تو و در بزم حاتمی <br />گردون ترا عنان قزح بهر آن دهد<br />با بحر برزنی چو به دستت قدح نهد<br />وز مهرکین کشی چو به دستت عنان دهد<br />هرکو چو تیغ با تو زبان آوری کند<br />قهرت جواب او به زبان سنان دهد<br />بر گرد بارگاه تو کیوان به شب بتافت <br />تا روز بوسه بر قدم پاسبان دهد<br />شاها خلایق از تو عزیز و توانگرند<br />درویشیم سزد که به دست هوان دهد؟<br />پوشیده زهره جامه ٔ زربفت و مشتری <br />محتاج خرقه ای است که در طیلسان دهد<br />در عهد چون تو شاهی کز فضله ٔ سخات <br />هر روز چرخ راتب دریا و کان دهد<br />شاید که بعد خدمت یکساله در عراق <br />نانم هنوز خسرو مازندران دهد؟<br />تا آسمان چو کسوت شب را رفو کند<br />گه از شهاب سوزن و گه ریسمان دهد<br />بادی چنانکه کسوت عمر ترا قضا<br />یک سر طراز مملکت جاودان دهد.<br />و هم از اوست :<br />تراست لعل شکربار و در میان گوهر<br />میان لعل چرا کرده ای نهان گوهر<br />به خنده چون لب یاقوت رنگ بگشائی <br />ز شرم زرد شود همچو زعفران گوهر<br />رُخم چو زرد شد از جزع دیده هر ساعت <br />فشانم از غم آن لعل دُرفشان گوهر<br />مرا به باد مده گرچه خاکسارم از آنک <br />به خاک تیره کند بیشتر مکان گوهر<br />اگرچه سیم و زرم نیست هست گوهر اشک <br />که نزد عقل به از صدهزار کان گوهر<br />سزد که ننگ نیاید ترا ز صحبت من <br />از آنکه ننگ ندارد ز ریسمان گوهر<br />چنان به چشم تو بی قیمتم ز بی درمی <br />که روز بزم به چشم خدایگان گوهر<br />همین بس است که الماس طبع من دارد<br />چو خنجر ملک شرق درمیان گوهر<br />خدایگان ملوک جهان طغان شه آنک <br />نثار می کند از جود بر جهان گوهر<br />ز بس که خون مخالف بریخت روز مصاف <br />گرفت در دل کان رنگ ارغوان گوهر<br />به یمن بخت چو گیرد قلم به دست کند<br />به صورت شبه ازنوک او روان گوهر<br />سپهرقدرا دست خرد نمی یابد<br />به قدر جود تو در گنج شایگان گوهر<br />اگر تو دست سخاوت کشیده تر نکنی <br />به هیچ کان ندهد هیچ کس نشان گوهر<br />خروس عدل تو تا پر زده ست در عالم <br />به جای بیضه نهاده ست ماکیان گوهر<br />زهی زمانه که بعد از هزار غصه و رنج <br />مرا نهاد ز مدح تو در دهان گوهر<br />زمانه گرچه بیازاردم نیازارم <br />کسی نیفکند از دست رایگان گوهر<br />اگرچه موج برآورد سالها دریا<br />به هیچ وقت نیفکند بر کران گوهر<br />قصیده ای که به مدح تو گفت بنده چو دُر<br />ردیف ساختش از بهر امتحان گوهر<br />در این دیار بسی شاعران باهنرند<br />که نور فکرت ایشان دهد به کان گوهر<br />سزد به نظم چنین گوهری کنند قیام <br />از آنکه خوب نماید به توأمان گوهر<br />همیشه تا که به هنگام نوبهار سحاب <br />کند نثار بر اطراف بوستان گوهر<br />نثار مجلست از چرخ گوهری بادا<br />که در حساب نیاید بهاء آن گوهر.<br />گویند که ظهیر از نیشابور به طریق سیاحت به اصفهان رفت و در آن حین صدرالدین عبداللطیف خجندی قاضی القضاة و مشارالیه آن ملک بود. روزی ظهیر به سلام خواجه رفت، دید که صدر خواجه مسکن فضلا و علماست . او سلام کرد و غریب وار به جائی نشست و التفاتی چنانکه خواست نیافت . تافته شد و این قطعه را بدیهه گفت وبه دست خواجه داد. قطعه :<br />بزرگوارا دنیا ندارد آن عظمت <br />که هیچ کس را زیبد بدان سرافرازی <br />شرف به فضل و هنر باشد و ترا همه هست <br />بدین نعیم مزوّرچرا همی نازی <br />ز چیست کاهل هنر را نمیکنی تمییز<br />تو نیز هم به هنر در زمانه ممتازی <br />به من نگه تو به بازی مکن از آنکه به فضل <br />دلم به گیسوی حوران نمیکند بازی <br />اگرچه نیست خوشت یک سخن ز من بشنو<br />چنانکه آن را دستور حال خود سازی <br />تو این سپر که ز دنیا کشیده ای در رو<br />به روز عرض مظالم چنان بیندازی <br />که از جواب سلامی که خلق را بر تست <br />به هیچ مظلمه ٔ دیگری نپردازی .<br />رجوع به لباب الالباب عوفی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> و تذکره ٔ دولتشاه ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span> شود.<br /></font></div>'),
(179136, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) ظهیرالمُلک . رجوع به علی بن حسن بیهقی، شرف الدین ظهیرالملک عامل هراة شود. (تتمه ٔ صوان الحکمة).<br /></font></div>'),
(179137, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) فارسی . شهرزوری گوید شهاب الدین مقتول بصائر را نزد ظهیر خوانده بوده است . رجوع به تتمه ٔ صوان الحکمة ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span> شود.<br /></font></div>'),
(179138, 'ظهیر', '<span class=\"hlight\">ظهیر.</span> <font color=\"DarkGreen\"><b>[ ظَ]</font></b> (اِخ ) فاریابی . رجوع به ظهیرالدین طاهر... شود.<br /></font></div>'),
(179139, 'ظهیرآباد', '<span class=\"hlight\">ظهیرآباد.</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) دهی است در مازندران . (رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(179140, 'ظهیرالحق', '<span class=\"hlight\">ظهیرالحق .</span> <font color=\"DarkGreen\"><b>[ ظَ رُل ْ ح َق ق ]</font></b> (اِخ ) لقب محمدبن مسعود الادیب الغزنوی . رجوع به محمد... شود. (تتمه ٔ صوان الحکمه ).<br /></font></div>'),
(179141, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b> (اِخ ) خسروشاه بن بهرام شاه غزنوی، مکنی به ابوشجاع . رجوع به خسروشاه شود.<br /></font></div>'),
(179142, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَرُدْ دَ ل َ ]</font></b> (اِخ ) رجوع به بیستون بن وشمگیر شود.<br /></font></div>'),
(179143, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b> (اِخ ) علیخان، ملقب به صفاعلیشاه . داماد ناصرالدین شاه و مرید صفی علیشاه . (متوفی <span class=\"hlight\" dir=\"rtl\">١٣٤٢</span> هَ . ق .). مقبره ٔ او در شمیران معروف و مدفن عده ای از دانشمندان و رجال است .<br /></font></div>'),
(179144, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b> (اِخ ) رجوع به مسعودبن محمود غزنوی شود.<br /></font></div>'),
(179145, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b> (اِخ ) رجوع به نظام الملک بن نظام الملک شود. (لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179146, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b> (اِخ ) محمدابراهیم خان برادرزاده ٔ آغامحمدخان قاجار. حاکم کرمان . (متوفی <span class=\"hlight\" dir=\"rtl\">١٢٤٠</span> هَ . ق .).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179147, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَل َ ]</font></b> (اِخ ) ابومنصور وشمگیر. رجوع به وشمگیر شود.<br /></font></div>'),
(179148, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b>(اِخ ) ممدوح مسعودسعد. رجوع به شواهد ظهیر و رجوع به ابراهیم بن سلطان مسعودبن سلطان محمود غزنوی شود.<br /></font></div>'),
(179149, 'ظهیرالدولة', '<span class=\"hlight\">ظهیرالدولة.</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دَ ل َ ]</font></b> (ع اِ مرکب ) پشتیبان دولت .<br /></font></div>'),
(179150, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) اردبیلی . رجوع به قاضی زاده شود.<br /></font></div>'),
(179151, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَرُدْ دی ]</font></b> (اِخ ) رجوع به جعفربن یحیی ترمنتی شود.<br /></font></div>'),
(179152, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به بابر ظهیرالدین شود.<br /></font></div>'),
(179153, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span><font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) بارزی . شاعری است . از اوست :<br />لئن فتکت الحاظه بحشاشتی <br />و ساعدها بالهجر و اغتر بالحسن <br />فلا بُدَّ ان تقتص لی منه ذقنه <br />و تذبحه قهراً من الاذن للاذن .<br />رجوع به فوات الوفیات ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢</span> شود.<br /></font></div>'),
(179154, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) تاج الکتاب السرخی . عوفی در لباب الالباب گوید: سید الاجل کان سیادت و جان سعادت بر آسمان علوم ماه تابان و بر فلک علو خورشید رخشان، مدتها دیوان انشاء سلطان شهید به رسم او بود. منشآت او مقبول فضلا و مکتوبات او پسندیده ٔ علما چنانکه نثره نثار نثر او سزیدی و شِعری ̍ شعار شعر او شایستی و از اشعار او داعی را بیشتر سماع نیفتاده ست . فاما شنیدم که به حضرت ملک کبیر تاج الدین تمران رحمه اﷲ قطعه ای فرستاد و از وی کنیزکی بکر التماس کرد و مطلع آن قطعه این است :<br />صدرا به ذات پاک خداوند انس و جان <br />کز جان و دل ثناء جلال تو گفته ام ...<br /> <font color=\"Red\">الخ .</font><br />چون ملک تاج الدین رحمه اﷲاین قطعه برخواند کنیزک بچه ای هندی بکر که زنگیان زلف او رومی آفتاب را طپانچه ٔ غیرت می زدند به نزدیک اوفرستاد و این قطعه در عذر آن نبشت :<br />چون به الماس طبع دُر سفتی <br />دُرّ ناسفته ای فرستادم <br />قوتت ده خدای عزّوجل <br />که ز بی قوتی به فریادم .<br />رجوع به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>-<span class=\"hlight\" dir=\"rtl\">١٣٨</span> شود.<br /></font></div>'),
(179155, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به اسحاق بن ابی بکر حنفی شود.<br /></font></div>'),
(179156, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به احمدبن اسماعیل تمرتاشی شود.<br /></font></div>'),
(179157, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به احمدبن ابی ثابت اسماعیل بن محمد شود.<br /></font></div>'),
(179158, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به ابوشجاع روذراوری محمدبن الحسین بن محمدبن عبداﷲبن ابراهیم شود.<br /></font></div>'),
(179159, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b>(اِخ ) ابوبکر عطار. وزیر المستضی ٔ بنوراﷲ، سی وسومین خلیفه ٔ عباسی . او در ابتدای کار بازرگان بود و با اهل تصرف درآمیخت و در نظر مستضی ٔ آمد، وزارت بدو دادو او مردی بود که بر رعیت تثقیل کردی و عوام او را دشمن داشتندی و تا آخر عهد مستضی ٔ وزیر بود. در سنه ٔسبعین وخمسمائه (<span class=\"hlight\" dir=\"rtl\">٥٧٠</span> هَ . ق .) قطب الدین قیماز که منصب امیرالامرائی داشت قصد گرفتن ظهیرالدین عطار که در سلک مخصوصان خلیفه منتظم بود کرد و ظهیرالدین به دارالخلافه گریخته، قیماز آتش نهب و تاراج در خانه اش زد و با بعضی از امرا و جمع کثیر از اهل غوغا و غارت روی به قصر خلافت نهاد تا ظهیرالدین را از خلیفه بگیرد و چون آواز ازدحام طوایف انام به گوش مستضی ٔ رسید و دانست که منشاء آن فتنه کیست، بر بام کوشک رفت و خودرا به مردم نمود و فریاد زد ایها الناس قیماز پای از حد خود فراتر می نهد، اکنون اموالش از شماست . چون مردم عام این سخن استماع نمودند متوجه منزل قطب الدین گشتند و ظهیرالدین رهائی یافت . رجوع به تجارب السلف چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span> و حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span> شود.<br /></font></div>'),
(179160, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) ابوالحسن علی بن الامام ابوالقاسم زیدبن محمدبن الحسین البیهقی . او یکی از علمای مشهور قرن ششم هجری است، و در حدود سنه ٔ <span class=\"hlight\" dir=\"rtl\">٤٩٠</span> هَ . ق . متولد شده و در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٦٥</span> هَ . ق . وفات یافته است و معاصر محمدبن عبدالکریم شهرستانی صاحب ملل و نحل متوفی در <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> و سیداسماعیل جرجانی صاحب ذخیره ٔ خوارزمشاهی متوفی در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٣١</span> بوده است و در صغر سن زمان عمر خیام را نیز دریافته و به مجلس او حاضر شده است . یاقوت گوید: «علی بن زید ابوالحسن بن ابی القاسم البیهقی، وفات او به سال <span class=\"hlight\" dir=\"rtl\">٥٦٥</span> بود و خود او در کتاب مشارب التجارب تألیف خویش آرد که کنیت من ابوالحسن باشد و نامم علی بن الامام ابی القاسم زیدبن الحاکم الامام امیرک محمدبن الحاکم ابی علی الحسین بن ابی سلیمان الامام فندق ابن الامام ایوب بن الحسن بن احمدبن عبدالرحمن بن عبیداﷲبن عمربن الحسن بن عثمان بن ایوب بن خزیمةبن عمروبن خزیمةبن ثابت بن ذی الشهادتین صاحب رسول اﷲ صلی اﷲ علیه و آله و سلم ابن الفاکه بن ثعلبةبن ساعدةبن عامربن عنان بن عامربن خطمةبن جشم بن مالک بن الاوس و نسبت خویش را تا آدم آورده است ». و سپس در متن یاقوت این عبارت آمده است : «و ذلک یسیر، قد ذکرناه فی عدة مواضع من کتبنا» و بازگوید: «مولد من به روز شنبه ٔ بیست وهفتم شعبان سال در قصبه ٔ سابزوار از ناحیه ٔ بیهق بود و آن شهری است که ساسان بن ساسان بن بابک بن ساسان پی افکنده است . پدر من مرا به کُتّاب سپرد وپس از آن ما به ناحیه ٔ ششتمذ از قراء این ناحیه رحلت کردیم، چه پدر مرا در آنجا ضیاعی بود و در عهد کودکی کتاب الهادی للشادی تصنیف میدانی را از بر کردم ونیز کتاب السامی فی الاسامی همان مؤلف و کتاب المصادر قاضی زوزنی را و کتاب غریب القرآن عزیزی و کتاب اصلاح المنطق و کتاب المنتحل میکالی و اشعار متنبی و حماسه و سبعیات و کتاب تلخیص در نحو. پس از آن کتاب مجمل را در لغت از حفظ کردم و در شهور سال <span class=\"hlight\" dir=\"rtl\">٥١٤</span> در مدرس ابی جعفر المقری امام جامع قدیم به نیشابور مصنف کتاب ینابیعاللغة و جز آن حاضر آمدم و در این مدرس کتاب تاج المصادر تألیف او را حفظ کردم و نحو ابن فضال و فصلی از کتاب مقتصد و امثال ابی عبید و امثال امیر ابی الفضل میکالی را نزد او خواندم . سپس در محرم سال <span class=\"hlight\" dir=\"rtl\">٥١٦</span> به درس امام صدرالافاضل احمدبن محمد میدانی رفتم و کتاب السامی فی الاسامی را که تصنیف خود اوست و نیزکتاب المصادر قاضی و کتاب المنتحل و کتاب غریب الحدیث ابی عبید و کتاب اصلاح المنطق و مجمع الامثال تألیف خود ابی جعفر و کتاب صحاح اللغه ٔ جوهری را نزد او درست کردم و در این میانه به محضر امام ابراهیم الهرازالمتکلم نیز تردد داشتم و از انوار علوم کلام از او اقتباس میکردم و نیز به خدمت امام محمد الفزاری میرفتم و از او غریب الحدیث خطابی و جز آن را شنودم و دراین وقت پدرم به سلخ جمادی الاَّخره ٔ سال <span class=\"hlight\" dir=\"rtl\">٥١٧</span> درگذشت ومن در ذی الحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٥١٨</span> به مرو شدم و در آنجا به خدمت تاج القضاة ابی سعد یحیی بن عبدالملک بن عبیداﷲبن ساعد که ملکی در صورت آدمی بود پیوستم و از لفظ او کتاب زکوة و مسائل خلافیة و سپس دیگر مسائل را غیر مرتب تعلیقات کردم و یک سال تمام در مناظره و مجادله خوض وغور کردم تا آنجا که نفس من قانع شد و همچنین استادمن از من بپسندید و در این وقت در این مدرسه و هم در جامع مجلس وعظ داشتم . سپس در ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٥٢١</span> از مرو بازگشتم و در آنجا به ازدواج پرداختم و این امر مرا از تحصیل سخت بازداشت، سپس با نیشابور عود کردم و از آنجا به زیارت مادر خود به مسقطالرأس خویش بیهق شدم و سه ماه بدانجا ببودم و این به سال <span class=\"hlight\" dir=\"rtl\">٥٢١</span> بود، پس به نیشابور مراجعت کردم و باز به بیهق بازگشتم و به مصاهرت الاجل شهاب الدین محمدبن مسعود المختار که در اول والی ری بود و سپس مشرفی مملکت داشت نائل آمدم و سالها پای بند اهل و اولاد بودم و در جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٥٢٦</span> قضاء بیهق به من دادند و برخی از عمر گرانمایه در اینگونه اموری که منتهی نتیجه ٔ آن همان است که شریح قاضی گفته است : «اصبحت و نصف الناس علی ّ غضبان » صرف شد و چاره ٔ خلاص و رستگاری خویش را جز انتقال از آنجا ندیدم و از این رو در شب عید شوال سال <span class=\"hlight\" dir=\"rtl\">٥٢٦</span> به قصد ری عزیمت کردم و در این وقت والی ری شهاب الدین پدرزن من بود و اکابر و قضاة و سایر اجلاء ری از من حسن استقبال کردند و تا بیست وهفتم جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> بدانجا بزیستم و در این مدت تنها به حساب و جبر و مقابله و قسمی از احکام نظر داشتم و چون به خراسان مراجعت کردم نزد حکیم استاد خراسان عثمان بن جادوکار به اتمام این صناعت پرداختم و کتبی از احکام به دست کردم و در این صناعت مشارالیه شدم و از آنجا در غره ٔ ربیعالاَّخر سال <span class=\"hlight\" dir=\"rtl\">٥٢٩</span> به نشابور منتقل شدم و هنوز در علم حکمت پخته نبودم و به بیهق معاودت کردم و از نقصان خود در این صناعت سخت اندوهناک بودم و در سال <span class=\"hlight\" dir=\"rtl\">٥٣٠</span> بدینجا در خواب دیدم که گوینده ای مرا گفت قطب الدین محمد مروزی ملقب به طبسی نصیری را دریاب . بر اثر این خواب به سرخس شدم و نزد او اقامت گزیدم و آنچه از دنانیرو دراهم داشتم خرج شد و آتش آز خویش بدان فرونشاندم و در بیست وهفتم شوال <span class=\"hlight\" dir=\"rtl\">٥٣٢</span> به نشابور بازگشتم (ظاهراًدر اینجا جمله یا جمله هائی ساقط شده است، چه پس از عبارت مذکور گوید) و با او در نشابور اقامت کردم تا آنگاه که او در رجب سال <span class=\"hlight\" dir=\"rtl\">٥٣٦</span> مبتلی به فالج گردید، پس در شعبان همان سال به بیهق آمدم و رشک و حسد اقارب در اینجا سخت مرا بی آرام میداشت و از آنجا در رمضان سال <span class=\"hlight\" dir=\"rtl\">٥٣٧</span> خائفاً یترقب به نیشابور شدم و بزرگان نیشابور مقدم من گرامی داشتند و به روزهای جمعه به مسجد جامع نیشابور قدیم و به چهارشنبه در مسجد مربع و در دوشنبه در مسجد الحاج مجلس میگفتم و وفود اکرام وزیر ملک الوزراء طاهربن فخرالملک و اکابر حضرت بر من پیوسته بود و من بدانجا رحل اقامت افکندم و تا غره ٔ رجب سال <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> بدانجا ببودم و پس برای زیارت مادر به بیهق رحلت کردم و مادر من و پسرم احمد در این سال بمردند و این مادر حافظ قرآن و عالم به وجوه تفاسیر بود. اینک تصانیف من در این مدت : کتاب اسئلة القرآن مع الاجوبة مجلدة. کتاب اعجاز القرآن مجلدة. کتاب الافادة فی کلمة الشهادة مجلدة. کتاب المختصر من الفرائض مجلدة.کتاب الفرائض بالجدول مجلدة. کتاب اصول الفقه مجلدة. کتاب قرائن آیات القرآن مجلدة. کتاب معارج نهج البلاغة و هو شرح الکتاب مجلدة. کتاب نهج الرشاد فی الاصول مجلدة. کتاب کنزالحجج فی الاصول مجلدة. کتاب جلاء صدأالشک فی الاصول . کتاب ایضاح البراهین فی الاصول مجلدة. کتاب الافادة فی اثبات الحشر و الاعادة مجلدة. کتاب تحفة السادة مجلدة. کتاب التحریر فی التذکیر مجلدتان . کتاب الوقیعة فی منکر الشریعة مجلدة. کتاب تنبیه العلماء علی تمویه المتشبهین بالعلماء. کتاب ازاهیر الریاض المریعة و تفسیر الفاظ المحاورة و الشریعة مجلدة. کتاب اشعار مجلدة. کتاب دررالسخاب و دررالسحاب فی الرسائل مجلدة. کتاب البلاغة الخفیة مجلدة. کتاب ملح البلاغة مجلدة. کتاب طرائق الوسائل الی حدائق الرسائل مجلدة. کتاب الرسائل بالفارسی مجلدة. کتاب رسائل المتفرقة مجلدة. کتاب عقوداللاَّلی مجلدة. کتاب غررالامثال مجلدتان . کتاب الانتصار من الاشرار مجلدة. کتاب الاعتبار بالاقبال و الادبار مجلدة. کتاب وشاح دمیة القصرمجلدة ضخمة. کتاب اسرار الاعتذار مجلدة. کتاب شرح مشکلات المقامات الحریریة مجلدة. کتاب درة الوشاح و هو تتمة کتاب الوشاح مجلدة خفیفة. کتاب العروض مجلدة. کتاب ازهار اشجار الاشعار مجلدة. کتاب عقود المضاحک بالفارسی مجلدة. کتاب نصائح الکبراء بالفارسیة مجلدة. کتاب آداب السفر مجلدة. کتاب مجامع الامثال و بدائع الاقوال اربع مجلدات . کتاب مشارب التجارب اربع مجلدات .کتاب ذخائر الحکم مجلدة. کتاب شرح الموجز المعجز مجلدة. کتاب اسرارالحکم مجلدة. کتاب عرائس النفائس مجلدة. کتاب اطعمة المرضی مجلدة. کتاب المعالجات الاعتباریة مجلدة. کتاب تتمة صوان الحکمة مجلدة. کتاب السموم مجلدة. کتاب فی الحساب مجلدة. کتاب خلاصة الزیجة مجلدة. کتاب اسامی الادویة و خواصها و منافعها مجلدة و هو معنون بتفاسیر العقاقیر مجلدة ضخمة. کتاب جوامع الاحکام ثلاث مجلدات . کتاب امثلة الاعمال النجومیة مجلدة.کتاب مؤامرات الاعمال النجومیة مجلدة. کتاب غررالاقیسة مجلدة. کتاب معرفة ذات الحلق و الکرة و الاصطرلاب مجلدة. کتاب احکام القرانات مجلدة. کتاب ربیعالعارفین مجلدة. کتاب ریاحین العقول مجلدة. کتاب الاراحة عن شدائد المساحة مجلدة. کتاب حصص الاصفیاء فی قصص الانبیاءعلی طریق البلغاء بالفارسیة مجلدتان . کتاب المشتهر فی نقض المعتبر الذی صنفه الحکیم ابوالبرکات مجلدة. کتاب بساتین الانس و دساتین الحدس فی براهین النفس مجلدة. کتاب مناهج الدرجات فی شرح کتاب النجاة ثلاث مجلدات . کتاب الامانات فی شرح الاشارات . کتاب رقیات التشبهات علی خفایا المختلطات بالجداول مجلدة. کتاب شرح رسالة الطر مجلدة. کتاب شرح الحماسة مجلدة. کتاب الرسالة العطارة فی مدح بنی الزنارة . کتاب تعلیقات فصول بقراط. کتاب شرح شعر البحتری و ابی تمام مجلدة. کتاب شرح شهاب الاخبار مجلدة».<br />یاقوت پس از ذکر تصانیف مذکوره گوید فهرستی که از تألیفات علی بن زید بیهقی دادیم بر طبق فهرستی بود که خود او در کتاب مشارب التجارب آورده است، لکن من علاوه بر آن، کتاب تاریخ بیهق او را به فارسی و کتاب لباب الانساب تألیف وی را نیز دیدم و در اول ورود من به نیشابور در ذی قعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٦١٣</span> کتاب وشاح الدمیة بیهقی را در آنجا یافتم . در این کتاب گوید که ابوالقاسم باخرزی از تصنیف کتاب دمیةالقصر در جمادی الاَّخره ٔ سال <span class=\"hlight\" dir=\"rtl\">٤٦٦</span> فراغت یافته است و من به تصنیف الوشاح درغره ٔ جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٥٢٨</span> آغاز کردم و در رمضان سال <span class=\"hlight\" dir=\"rtl\">٥٣٥</span> به انجام رسانیدم و در همین کتاب الوشاح اشعاری از خود در مدح مخلص الدین ابی الحزم محمدبن عاصم کاتب انشاء در دیوان سلطان سنجر که خواهرزاده ٔ ابواسماعیل طغرائی است نقل میکند:<br />کریم علی اوج النجوم علاه <br />و ایقظ نوّام المدیح نداه <br />سری و اهتدی طبعی بنجم کماله <br />و احمد فی وقت الصباح سزاه <br />له روضة ابدت من الفضل نرجساً<br />و غصناًمن الاقبال طاب جناه <br />اعاد رصاع القلب فی رحل ورده <br />و غادر فی قلبی ضواع هواه <br />تفرق اشجان الافاضل یمنة<br />و یجمع کل الصید جوف فراه <br />لقد زرت اشراف الزمان و انما<br />ابی الفضل الا ان ازورفناه .<br />و عماد اصفهانی در کتاب الخریدة ذکر او آورده و به ریاست و شرف وی را ستوده است و گوید پدر من مرا حدیث کرد که آنگاه که علی بن زید بیهقی در عقیب نکبت به ری شد بخت بدو اقبال کرد و شرف الدین بیهقی که در این وقت والی ری بود با موکب خویش به استقبال وی شتافت و او را به منزل خویش فرودآورد و به ترمیم خلل ها و زیانهای وارده ٔ بدو پرداخت و در این وقت شرف الدین خویش را آماده ٔ کفالت وزارت سلطان میکرد و مکانتی عالی داشت و این دو تا آنگاه که مرگ در میانشان جدائی افکند در ری مقیم و با هم مأنوس بودند و جدائی آنان از یکدیگر به مرگ در سال <span class=\"hlight\" dir=\"rtl\">٥٣٣</span> بود و باز پدر من میگفت که گمان میکنم نکبت او در وقعه ٔ سلطان سنجر با کفار ختائیه بود و پدر من پیوسته ثناء او میگفت و میگفت بیهقی را نظیری نبوده است و کتاب وشاح الدمیة را به ذیل کتاب ابی الحسن باخرزی او نوشته و این کتاب در خراسان موجود است و در آنجا قطعات ذیل را از شعر خویش آورده است :<br />تراجعت الامور علی قفاها<br />کما یتراجع البغل الرموح <br />و تستبق الحوادث مقدمات <br />کما یتقدم الکبش النطوح .<br />و قوله :<br />تشیر باطراف لطاف کأنها<br />انابیب مسک أو اساریع مندل <br />و تومی بلحظ فاترالطرف فاتن <br />بمرود سحر بابلی مکحل <br />ینم علی ما بیننا من تجاذب <br />نسیم الصبا جأت بریا القرنفل .<br />وله :<br />یاخالق العرش حملت الوری <br />لما طغی الماء علی جاریه <br />و عبدک الاَّن طغی ماؤه <br />فی صلبه فاحمله علی جاریه (؟).<br />یاقوت گوید آنچه گفتیم نقل از کتاب عماد است و آنگاه که منقولات عماد را با آنچه بیهقی خود از تاریخ حیات خویش به خط خویش نگاشته است مطابقه کنیم اختلافاتی در تاریخ و غیر آن هست و خدای تعالی داناتر به حقیقت باشد. و باز از اوست قطعات ذیل که درکتاب الوشاح در مدح عزیزالدین ابوالفتوح علی بن فضل اﷲ المستوفی الطغرائی گفته است و من از خط خود بیهقی آن را نقل کرده ام :<br />شموسی فی افق الحیاة هلال <br />و امنی من صرف الزمان محال <br />و اطلب و المطلوب عزّ وجوده <br />و ارجو و تحقیق الرجاء محال <br />الی کم ارجی من زمانی مسرة<br />و قد شاب من رأس الزمان قذال <br />وبال علی الطاوس الوان ریشه <br />و علم الفتی حقاً علیه وبال <br />و للدهر تفریق الاحبة عادة<br />و للجهل داء فی الطباع عضال <br />لقد ساد بالمال المصون معاشر<br />و اخلاقهم للمخزیات عیال <br />و بینهم ذل المطامع عزة<br />و عندهم کسب الحرام حلال .<br />و له :<br />ضجیعی فی لیلی جوی و نحیب <br />و الفی فی نومی ضنا و لغوب <br />دجی لیل آمالی و ابطاء صبحه <br />و للمنذرات السود فیه نعیب <br />و تلسعنی الایام فهی اراقم <br />و تخدعنی الاَّمال فهی کذوب <br />ألا لیت شعری هل ابیتن لیلة<br />و باعی فی ظل الوصال رحیب <br />خلیلی لاترکن الی الدهر آمناً<br />فاحسانه بالسیآت مشوب <br />و کم جاهل قد قال لی انت ناقص <br />فهیج لیث الحقد و هو غضوب <br />و عیرنی بالعلم و الحلم و النهی <br />قبائل من اهل الهوی و شعوب <br />فقلت لهم لاتعذلونی فاننی <br />لصفو زجاجات العلوم شروب <br />و ماضرنی انی علیم بمشکل <br />و قد مس ّ اهل الدهر منه لغوب <br />لئن عُدّ علم المرء جرماً لدیکم <br />فذلک جرم لست منه اتوب <br />کفی حزناً انی مقیم ببلدة<br />بها صاحب العلم الرصین غریب .<br />و باز در این کتاب (یعنی وشاح ) گوید آنگاه که به خدمت امیر یعقوب بن اسحاق المظفربن نظام الملک رفتم مقدم مرا به اکرام و تعظیم و تفخیم مقابله کرد و من بدیهةً این چهار شعر بگفتم :<br />یعقوب یظهر دائماً فی لفظه <br />عسلاً لدیه نظمه یعسوبه ُ<br />و غدا بحمداﷲ صدراً مکرماً<br />یعلو نطاق المشتری عرقوبه ُ<br />فسقی انامله ُ حدائق لفظه <br />و جری علی نهج العلی یعبوبه ُ<br />قد غاب یوسف خاطری عن مصره <br />و یشم ریح قمیصه یعقوبه ُ.<br />و امیر گفت آیا بر این وتیره و منوال که من گفته ام خواهی چیزی گفتن و قطعه ٔ ذیل را بخواند:<br />اء عاذل مهلاً لیس عذلک ینفع<br />و قولک فینا دائماً لیس ینجع<br />و هل یصبر الصب المشوق علی الجوی <br />و فی الوصل مشتاق و فی الهجر مجزع <br />یقولون ان الهجر یشفی من الجوی <br />و ان فؤاد الصب فی القرب اجزع <br />بکل تداوینا فلم یشف ما بنا<br />الا ان قرب الدار اجدی و انفع<br />تحن الی ظل من العیش وارف <br />و عهد مضی منه مصیف و مربع.<br />گفتم ای صدر سرکه را حلاوت انگبین و سرمه را طلاوت حور عین نتواند بودن، چراغ مرده کجا، نور آفتاب کجا! و لاشه ٔ خر را به اسب تازی چه نسبت . گفت ترا از جواب گفتن این قطعه گزیری نیست و من با شتاب و عجله به بداهت و ارتجال و بر سبیل استعجال قطعه ٔ ذیل بگفتم :<br />سری طیفه ُ وهناً و لی فیه مطمع<br />و برق الامانی فی دجی الهجر یلمع<br />و یأبی حقین الهجر عدرة طیفه <br />فلم ادر فی مهوی الهوی کیف اصنع<br />لقد یحمد القوم السری فی صباحهم <br />زمان تلاق عنده الشمل یجمع<br />و ها انا اَسری فی ظلامی و اننی <br />أذم ّ صباحی و الخلائق هجع<br />اقول لصبری انت ذخری لدی النوی <br />و ذخر الفتی حقاً شفیع مشفع<br />و اسکن ماءالعین ناری و انما<br />هواء الهوی من تربة الطیف انفع<br />رأیت معیدی الخیال فقال من <br />جهینة اخبار المعیدی تسمع<br />دعوت الی حیس الهوی جندب الهوی <br />فولی وطرف العین فی النوم یرتع<br />و قال لنفسی لاتموتی صبابة<br />لعل زماناً قد مضی لک یرجع<br />و لم یبق منی غیر ما قلت منشداً<br />حشاشة نفس ودّعت یوم ودّعوا<br />فلاذ بشمس الدین یعقوب من له <br />نجوم لها فی مشرق المجد مطلع<br />اجلک یا یعقوب عن کنه مدحتی <br />لانک عن مدحی اجل و ارفع.<br />و امیر مرا تشریف قصیده ٔ ذیل ارزانی داشت که اول آن این است :<br />الا ابلغ الی سلمی السلاما...<br />و من جواب آن بگفتم و پس از جواب بر سبیل اداء شکر منعم قطعه ٔ ذیل تقدیم داشتم :<br />یا صاحبی کسدت اسواق اشواقی <br />و التفت الساق یوم الهجر بالساق <br />یا لیت شعری هل سعد یساعدنی <br />ام هل لداءالهوی فی الناس من راق <br />ام هل سبیل الی سلوان مکتئب <br />ام هل طریق الی ایناس مشتاق <br />یا نجل اسحاق یا من ثوب سودده <br />قد جل فی الدهر عن وهی و اسحاق <br />فماتمهلت فی یومی وغی و ندی <br />الا قضیت بآجال و ارزاق <br />و کل ذکر وان طال الزمان به <br />فان ذکرک فی نادی الندی باق .<br /> <font color=\"Red\">(معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٥</span> صص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>-<span class=\"hlight\" dir=\"rtl\">٢١٨</span>).</font><br />ابوالحسن بیهقی از مشاهیر علمای عصر خود بود و کتب نفیسه ٔ بسیاری به زبان عربی و فارسی تألیف کرد و یاقوت در معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٥</span> صص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>-<span class=\"hlight\" dir=\"rtl\">٢١٨</span> در ترجمه ٔ حال او هفتادوچهار کتاب از مؤلفات او را به اسم و رسم میشمرد، ولی از سؤحظ از جمیع این کتب نفیس جز تاریخ بیهق و جز تتمه ٔ صوان الحکمه در تاریخ حکما و چند کتاب دیگر که ذیلاً معرفی خواهیم کرد گویا چیزی از آثار او بر جای نمانده است . بیهقی تاریخ بیهق را به تصریح خود وی در سال <span class=\"hlight\" dir=\"rtl\">٥٦٣</span> در زمان سلطان مؤید آی آبه از غلامان سلطان سنجر که بلافاصله بعد از وفات سنجر بر خراسان مسلط شد تألیف کرده است . موضوع تاریخ بیهق چنانکه از اسم آن برمی آید عبارت است از تاریخ این ناحیه از ایران و تراجم مشاهیر رجالی که بدانجا منسوبند از علما و ادبا و شعرا و وزراء وسادات و کُتّاب و حکما و اطبا و غیرهم و انساب خانواده های مشهور که از قدیم در آنجا توطن داشته یا از مواضع دیگر بدانجا هجرت کرده اند و نیز تا اندازه ای ازجغرافیای این ناحیه بحث شده است . دیگر از تألیفات بیهقی ذیلی است بر صوان الحکمه ٔ ابوسلیمان منطقی سجستانی به نام تتمه ٔ صوان الحکمه که چاپ شده است . دیگر از تألیفات ابوالحسن بیهقی کتابی است به فارسی در نجوم بنام جوامع الاحکام که نسخ متعدد از آن در ایران یافت میشود و نفیس ترین آنها ظاهراً نسخه ای است که در سبزوار وجود دارد و به سال <span class=\"hlight\" dir=\"rtl\">٩٤٩</span> هَ . ق . نوشته شده است . کتاب دیگر بیهقی شرحی است از نهج البلاغه به نام معارج نهج البلاغة. ابوالحسن بیهقی به خواهش جمال المحققین ابوالقاسم علی بن حسن الحویفی (؟) النیشابوری به نوشتن این کتاب اقدام کرده و ابوالقاسم پیش از تمام شدن کتاب وفات یافته است و بیهقی کتاب را همچنان به نام او موشح داشته و آن را به کتابخانه ٔ ملک النقباء علی بن محمدبن یحیی حسینی تقدیم کرده است . از مؤلفات بیهقی نسخه ٔ دیگری موجود است که کمتر کسی از آن اطلاع دارد و آن جلد اول لباب الانساب است که در کتابخانه ٔ مدرسه ٔ سپهسالار موجود ولی اشتباهاً به نام نهایة الأنساب ضبط شده است . بیهقی این کتاب را به نام ابوالحسن علی بن محمدبن یحیی علوی در اواخر جمادی الاَّخره ٔ سال <span class=\"hlight\" dir=\"rtl\">٥٥٨</span> هجری شروع کرده و پس از سه ماه به اتمام رسانده است . لباب الانساب مشتمل است بر مطالب سودمند و نکات تاریخی مهم و دانستنی . و نیز از جمله ٔ کتب بسیار معروف بیهقی ذیلی بوده است بر تاریخ یمینی به نام مشارب التجارب و غوارب الغرائب و مشتمل بوده است بر وقایع تاریخی ایران در مدت صدوپنجاه سال از همانجا که تاریخ یمینی ختم میشود یعنی از حدود سال <span class=\"hlight\" dir=\"rtl\">٤١٠</span> الی حدود <span class=\"hlight\" dir=\"rtl\">٥٦٠</span> هَ . ق . و بعبارة اخری شامل بوده است تقریباً تاریخ تمام دوره ٔ غزنویه و تمام دوره ٔ سلجوقیه و نیمه ٔ اول دوره ٔ خوارزمشاهیه را. یاقوت در معجم الادباء مکرر ازاین کتاب نقل کرده است، همچنین ابن اثیر در تاریخ کامل و ابن ابی اصیبعه در طبقات الاطباء و عطاملک جوینی در تاریخ جهانگشا هر کدام فقراتی از این کتاب نقل کرده اند و حمداﷲ مستوفی در دیباچه ٔ تاریخ گزیده آن را از مآخذ خود میشمرد و از اینجا معلوم میشود که این کتاب به طور قطع تا اواسط قرن هشتم موجود بوده است . دیگر از تألیفات بیهقی ذیلی بوده است بر دمیةالقصر باخرزی موسوم به وشاح دُمیةالقصر یا اختصاراً وشاح الدُمیة در تراجم احوال شعراء عصر خود. یاقوت در معجم الادباء مکرّر از این کتاب نقل کرده و ابن خلکان نیز در ترجمه ٔ حال باخرزی اشاره بدان نموده، حاجی خلیفه این کتاب را به نام وشاح دمیةالقصر و لقاح روضةالعصر ذکرکرده و گویا نام کامل کتاب همین بوده است . دیگر از تألیفات بیهقی کتابی بوده است در امثال عرب موسوم به غررالامثال و دررالاقوال در دو جلد که به قول حاجی خلیفه مأخذ مجمع الامثال میدانی این کتاب بوده است، ولی ظاهراً این سهوی است واضح از حاجی خلیفه که منشاءآن عدم اطلاع از عصر بیهقی بوده است، چه بیهقی به تصریح خود او در مشارب التجارب (به نقل یاقوت از او در معجم الادباء) از شاگردان میدانی بوده و دو کتاب السامی فی الاسامی و مجمع الامثال را نزد خود مؤلف یعنی میدانی درس خوانده بوده است و علاوه بر این بیهقی قریب پنجاه سال پس از میدانی در حیات بوده، چه فوت میدانی در <span class=\"hlight\" dir=\"rtl\">٥١٨</span> و فوت بیهقی در <span class=\"hlight\" dir=\"rtl\">٥٦٥</span> بوده است . (از مقدمه ٔ تاریخ بیهق چ بهمنیار).<br /></font></div>'),
(179161, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) ابن علی بن قوام الدین . یکی از سادات مرعشی مازندران و در چالوس مقیم بود. رجوع به مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">٢٧</span> شود.<br /></font></div>'),
(179162, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) ابن علی بن زین العابدین بن الحسام العاملی العیناثی . مردی فاضل و عابد و فقیه از مشایخ جلیل القدر. او از شیخ علی بن احمد عاملی والد شهید ثانی روایت کند. رجوع به روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span> شود.<br /></font></div>'),
(179163, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به ابن مفلح شود.<br /></font></div>'),
(179164, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به ابراهیم بن سکمان شود.<br /></font></div>'),
(179165, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به ابراهیم بن حسین شود.<br /></font></div>'),
(179166, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) ابراهیم بن نصربن عسکر موصلی . رجوع به ابواسحاق سلامی شود.<br /></font></div>'),
(179167, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) (امیر...) ابراهیم صواب . در مبداء حال ملازمت امیر پیر حسین چوپانی می کرد و در آن اوان در خدمت جناب مبارزی بود. از آن جناب رخصت گرفته به شیراز شتافت و امیر شیخ رقم عزل بر صحیفه ٔ شمس الدین صاین و سیدغیاث الدین علی کشید و امیر ابراهیم را به استقلال وزیر گردانید و امیر ابراهیم نه به واسطه ٔ وفور کفایت بلکه از غایت جهالت ابواب مداخل و منافع ارکان دولت را مسدود ساخت . لاجرم آن جماعت یکی از رنود را تطمیع کردند تا فرصت نگاه داشته، به زخم تیری امیر ابراهیم را به عالم بقا فرستاد و کرّت دیگرمولانا شمس الدین صاین و سیدغیاث الدین علی قدم بر مسند وزارت نهادند. رجوع به دستور الوزراء ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> شود.<br /></font></div>'),
(179168, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) حاتم دهلوی . رجوع به حاتم دهلوی شود.<br /></font></div>'),
(179169, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) فرامرزبن علاءالدوله ابوجعفر محمدبن دشمنزیاربن کاکویه، مکنی به ابومنصور. از امرای دیالمه ٔ کاکویه . وی پس از مرگ پدر خود علاءالدوله در ابتدای سال <span class=\"hlight\" dir=\"rtl\">٤٣٣</span> هَ . ق . به جای وی نشست و اداره ٔ امور حکومتی علاءالدوله یعنی اصفهان و همدان و ری و قسمتی از بلاد غربی ایران به وی رسید، ولی برادران او به اطاعت وی گردن ننهادند چنانکه کمی بعد برادرش گرشاسف دم از استقلال زد و برادر دیگرش ابوحرب از در مخالفت درآمد و این نفاق آنان را سلجوقیان غنیمت شمردند چنانکه در همین سال ابراهیم ینال به ری آمد و از ظهیرالدین درخواست تا اطاعت سلاجقه را گردن نهد. ظهیرالدین نپذیرفت واز ری به همدان و بروجرد آمد و با برادر خود گرشاسف صلح کرد و گرشاسف حاکم همدان و با برادر متحد شد. ابراهیم ینال پس از تسخیر ری در <span class=\"hlight\" dir=\"rtl\">٤٣٤</span> به تعقیب پسران کاکویه به بروجرد رفت و آنجا را تصرف کرد. طغرل سلجوقی نیز پس از فتح خوارزم و گرگان و طبرستان و خراسان به ری آمد و بر قزوین و ابهر و زنجان دست یافت و ناچار ابومنصور و گرشاسف تسلیم او شدند و طغرل اصفهان را به ابومنصور واگذاشت . بین ظهیرالدین ابومنصور و ابوکالیجار دیلمی رقابت شدید بود چنانکه در سال <span class=\"hlight\" dir=\"rtl\">٤٣٥</span> ابومنصور برای بیرون کردن کرمان از دست ابوکالیجار بدانجا لشکر کشید، لیکن مغلوب شد و به طغرل سلجوقی توسل جست بدین امید که طغرل ممالک ایشان را مسخر و اداره ٔ آن را بدو واگذار کند و چون طغرل مهم او را انجام نداد ظهیرالدین از ری در ابتدای سال <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> مراسله ای به بوکالیجار نوشت و اظهار اطاعت کرد و قبول کرد که دراصفهان به نام او خطبه بخواند. امیر بویهی مسئول اورا بپذیرفت و میان ایشان صلحی برقرار گردید. در سال <span class=\"hlight\" dir=\"rtl\">٤٣٨</span> طغرل به عزم تسخیر اصفهان حرکت کرد و آن شهر رادر محاصره گرفت ولی به تسخیر آن موفق نگشت و ظهیرالدین سخت در برابر وی پافشاری کرد. ناچار طغرل به گرفتن خراج سالیانه راضی شده و دست از محاصره برداشت .<br />طغرل پس از دفع فتنه ٔ برادر خود ابراهیم ینال بار دیگر عازم فتح اصفهان شد و در محرم سال <span class=\"hlight\" dir=\"rtl\">٤٤٢</span> آنجا را محاصره کرد و عاقبت در محرم سال <span class=\"hlight\" dir=\"rtl\">٤٤٣</span> اصفهان را تسخیر کرد و دولت دیالمه ٔ کاکویه را برانداخت و ابومنصور را به حکومت یزد و ابرقویه فرستاد.<br /></font></div>'),
(179170, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْدی ]</font></b> (اِخ ) ولوالجی حنفی . او راست : امالی در فقه .<br /></font></div>'),
(179171, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) نوحباری . او راست : فوائد ظهیرالدین .<br /></font></div>'),
(179172, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) نصر السموری . رجوع به نصر... شود.<br /></font></div>'),
(179173, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) مرعشی (سید) ابن سیدکمال الدین بن سیدقوام الدین . مؤلف تاریخ طبرستان از سادات مازندران و پدران وی در این سرزمین حکومت داشته اند چنانکه جدش قوام الدین (متوفی در <span class=\"hlight\" dir=\"rtl\">٧٨١</span> هَ . ق .) از سال <span class=\"hlight\" dir=\"rtl\">٧٦٠</span> سلطنت داشته و پدرش کمال الدین (متوفی در <span class=\"hlight\" dir=\"rtl\">٨٥٥</span>) و اعمام و بنی اعمامش نیز به توالی و تناوب در آمل و ساری و دیگر نواحی مازندران حکومت کرده اند و در سال <span class=\"hlight\" dir=\"rtl\">٨٨١</span> که سیدظهیرالدین تاریخ طبرستان می نوشته هنوز سلطنت مازندران در آن خاندان بوده است . سیدظهیرالدین تاریخ طبرستان را به امر کارکیا سلطان علی میرزابن سلطان نامدار... شمس الدنیا و الدین کارکیا سلطان محمد تألیف کرده است . کتاب وی مشتمل بر یک مقدمه و شش باب است بدین ترتیب :<br />باب اول - در ذکر تاریخ حکام و سلاطین گیلان و دیلمستان ... باب دوم - در ذکر خروج سیدامیرکیا ملاطی ... باب سوم - در ذکر خروج سیدهادی کیا از تنکابن ... باب چهارم - در ذکر حکومت سیدرضی کیا و سیدمحمد... باب پنجم - در ذکر حکومت ناصرکیا و برادرش امیر سیداحمد... باب ششم - در ذکر سلطنت سلطان محمد... و رجوع به حبیب السیر صص <span class=\"hlight\" dir=\"rtl\">١٠٧</span>-<span class=\"hlight\" dir=\"rtl\">١١٢</span> و تاریخ ظهیرالدین مرعشی شود.<br /></font></div>'),
(179174, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمودبن عبدالصمد فارقی . رجوع به محمود... شود.<br /></font></div>'),
(179175, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن مسعود الادیب الغزنوی . رجوع به محمد... شود.<br /></font></div>'),
(179176, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن محمود نیشابوری . رجوع به محمد... شود.<br /></font></div>'),
(179177, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b>(اِخ ) محمدبن عمر نوح آبادی . رجوع به محمد... شود.<br /></font></div>'),
(179178, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن علی بن الکاتب السمرقندی . رجوع به بهاءالدین محمدبن علی بن محمدبن عمر الظهیری الکاتب و لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span>، <span class=\"hlight\" dir=\"rtl\">٩٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٠١</span>، <span class=\"hlight\" dir=\"rtl\">٣١٨</span>، <span class=\"hlight\" dir=\"rtl\">٣١٩</span> شود.<br /></font></div>'),
(179179, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن حسین، مکنی به ابوشجاع .وزیر المقتدی باﷲ بیست وهفتمین خلیفه ٔ عباسی . رجوع به ابوشجاع روذراوری در همین لغت نامه و تجارب السلف چ اقبال صص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span>-<span class=\"hlight\" dir=\"rtl\">٢٨٧</span> و حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٠</span> شود.<br /></font></div>'),
(179180, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن حسام العیناثی . رجوع به محمد... شود.<br /></font></div>'),
(179181, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن احمدبن عمر. رجوع به محمد... شود.<br /></font></div>'),
(179182, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) محمدبن احمد. قاضی و محتسب بخاری حنفی . رجوع به محمد... شود.<br /></font></div>'),
(179183, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) کندی . او راست : الجامع فی الفروع .<br /></font></div>'),
(179184, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) کراولی (خواجه ...). هشتمین از امرای سربداران، به روایت مطلعالسعدین خواهرزاده ٔ خواجه یحیی کراولی و به قول صاحب تاریخ سربداران برادر او، و بر هر تقدیر وی پس از قتل خواجه یحیی به اتفاق پهلوان حیدر قصاب سردار جماعت سربداران شد و او مردی حکیم و بی آزار بود و همواره به بازی و شطرنج اشتغال می نمود و پهلوان حیدر قصاب به سرانجام مهام فرق انام می پرداخت و پس از انقضای چهل روز پهلوان حیدر خواجه را معزول گردانیده خود متعهد آن مهم گردید (<span class=\"hlight\" dir=\"rtl\">٧٦٠</span> هَ . ق .). رجوع به حبیب السیر جزء <span class=\"hlight\" dir=\"rtl\">٢</span> از ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span> و طبقات سلاطین اسلام لین پول شود.<br /></font></div>'),
(179185, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) فاریابی . رجوع به ظهیرالدین طاهربن محمد شود.<br /></font></div>'),
(179186, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) (شیخ ...) عیسی بن شیخ معین الدین ابونصر احمدبن ابی الحسن الشافعی الجامی است که نسب وی به جریربن عبداﷲ البجلی میرسد. پدر وی یعنی معین الدین که در سال احدی و اربعین و اربعمائة (<span class=\"hlight\" dir=\"rtl\">٤٤١</span> هَ . ق .) متولد شده و در سال ست و ثلاثین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٣٦</span> هَ . ق .) وفات یافته از سالکان طریقت و اهل حقیقت بوده و صاحب کتابی است به نام سراج السایرین . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٢</span>).<br /></font></div>'),
(179187, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) علی بن محمد کازرونی . رجوع به علی ... شود.<br /></font></div>'),
(179188, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) علی بن عبدالعزیزبن عبدالرزاق مرغینانی . رجوع به علی ... شود.<br /></font></div>'),
(179189, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) علی بن شاهک القصاری الضریر البیهقی . رجوع به علی ... شود.<br /></font></div>'),
(179190, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به عبدالرحمن بن علی شیرازی شود.<br /></font></div>'),
(179191, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) عبدالرحمن علی بن شیخ نجیب الدین غش، رحمه اﷲ تعالی، خلف صدق وخلیفه ٔ به حق بود مر پدر خود را و چون مادر وی به وی حامله شد شیخ شهاب الدین برای وی پاره ای از خرقه ٔ مبارکه ٔ خود فرستاد، چون متولد شد آن را در وی پوشانیدند. اول خرقه ای که در دنیا پوشید وی (؟) بود و چون بزرگ شد به خدمت پدر مشغول شد و تربیت یافت و در ایام حیات پدر به حج رفت . شب عرفه در خواب دید که به روضه ٔ شریفه ٔ رسول (ص ) آمد و سلام گفت . از حجره ٔ شریف آواز آمد که و علیک السلام یا اباالتجاشی . پدر وی بر آن حال مطلع شد و اهل خود را از آن حال خبردار کرد و بشارت داد که مراد حاصل شد، و بعد از آن درس گفت و حدیث روایت کرد و تصنیف کرد و از تصانیف وی یکی آن است که عوارف را ترجمه کرده است و در آنجا تحقیقات صادر از کشف و الهام بسیار است و به مقامات بلند رسید و به کرامات ارجمند مشهور شد. توفی رمضان سنة ست عشر و سبعمائة (<span class=\"hlight\" dir=\"rtl\">٧١٦</span> هَ . ق .). (از نفحات الانس جامی ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>).<br /></font></div>'),
(179192, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) (الامام ...) رجوع به عبدالجلیل بن عبدالجبار شود.<br /></font></div>'),
(179193, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) صوفی جامع بوده است میان علوم ظاهری و باطنی و مولانا زین الدین تایبادی میفرمود که در زیر طاس فلک مثل ظهیرالدین کسی دیگر نمیدانم . مرید شیخ سیف الدین خلوتی است و پانزده سال در خدمت وی بوده است و شیخ سیف الدین در سنه ٔ ثلثةوسبعمائة (<span class=\"hlight\" dir=\"rtl\">٧٠٣</span> هَ . ق .) از دنیا رفته و قبر وی در مزار خلوتیان است و بر سر پل گازرگاه و شیخ سیف الدین مرید شیخ محمد خلوتی است که میگویند که هرگاه در خوارزم به ذکر مشغول شدی آواز وی چهار فرسخ برفتی و پهلوان محمود یکبار (؟) معاصر وی بوده و با وی صحبت میداشته . شیخ ظهیرالدین از قاری سبعه (؟) بوده است . وی گفته است که چون قرآن را تمام بر استاد خواندم حضرت رسالت (ص ) را شبی در خواب دیدم که گفت ظهیرالدین قرآن را بر من بخوان . از اول تا آخر بر وی خواندم . گویند که وقتی در اربعین نشسته چهار نوبت افطار کرد به آب گندم جوشیده هر ده روز یک نوبت و گویند که هرگاه که به زیارت گازرگاه رفتی چون از پل گازرگاه درگذشتی یعنی بعد ده روز (؟) پای برهنه کردی و گفتی از اولیأاﷲ شرم میدارم که پای با نعلین در روی ایشان نهم . در تاریخ سنه ٔ ثمانمائة (<span class=\"hlight\" dir=\"rtl\">٨٠٠</span> هَ. ق .) از دنیا برفته و قبر وی در مزار خلوتیان است در جوار قبر شیخ وی . (نفحات الانس جامی صص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>-<span class=\"hlight\" dir=\"rtl\">٣٢٩</span>).<br /></font></div>'),
(179194, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) شفروه . رجوع به عبداﷲبن شفروه شود.<br /></font></div>'),
(179195, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ظَ رُدْ دی ]</font></b> (اِخ ) رجوع به سیف الاسلام طغتکین شود.<br /></font></div>'),
(179196, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) حسن بن خطیربن ابی الحسین نعمانی . رجوع به نعمانی شود.<br /></font></div>'),
(179197, 'ظهیرالدین', '<span class=\"hlight\">ظهیرالدین .</span> <font color=\"DarkGreen\"><b>[ ظَ رُدْ دی ]</font></b> (اِخ ) (الامام ...) ولی ّالنسوی . معاصر عوفی است . عوفی درلباب الالباب گوید: او از علماء نامدار و افاضل ایام، فضایل افاضل در پیش او قطری از بحری و نظم ثریا و نثر نثره در مقابله ٔ نظم و نثر او از سوره ای سطری و در نسا مصاحبت او دریافتم و این رباعی از وی شنیدم :<br />صبحی ندمد زآخر هیچ شبی <br />تا تازه به رویم نرساند تعبی <br />حاصل من بی دولت حرمان، روزی <br />دارم ز تر و خشک جهان چشم و لبی .<br />و این قطعه در جواب شعر قاضی امام شمس الدین نسوی گفته رَحِمَه ُ اﷲ.<br />قطعه :<br />جز به جنابت اگر خطاب نویسند<br />نقش معماست کآن بر آب نویسند<br />در نسبت خسروی ز دانش گیرند<br />در لقبت مالک الرقاب نویسند<br />کلک ترا مشرف ممالک خوانند<br />کف ّ ترا نایب سحاب نویسند<br />عرش جنابا به ذات عرش و تعلّیش <br />پس به خطی کاوّل کتاب نویسند<br />گر همه کُتّاب عصر وقت بلاغت <br />مثل تو فصلی به هیچ باب نویسند<br />مهررُخا کین من ز چرخ بخواهی <br />تات به اضعاف آن ثواب نویسند<br />نوک قلمهای فاضلان زمانه <br />چند ز تشویش و اضطراب نویسند<br />دفتر عاهات در مطالعه دارند<br />وز سیر دهر انتخاب نویسند<br />آینه ٔ روح را مدادت خوانند<br />آبله ٔ راح را حباب نویسند<br />بازخرم از بلای دهر که کُتّاب <br />صدر ترا مرجع و مآب نویسند<br />قطعه ٔ قلبم جواب شعر تو شاید<br />عکس صدا را اگر جواب نویسند.<br />رجوع به لباب الالباب عوفی ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>-<span class=\"hlight\" dir=\"rtl\">٢٤٤</span> شود.<br /></font></div>'),
(179198, 'ظهیرک', '<span class=\"hlight\">ظهیرک .</span> <font color=\"DarkGreen\"><b>[ ظَ رَ ]</font></b> (اِخ ) دهی است تقریباً در سه فرسنگی مشرق شیراز. (فارس نامه ).<br /></font></div>'),
(179199, 'ظهیری', '<span class=\"hlight\">ظهیری .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) ظهیرالدین محمدبن علی بن محمدبن عمر الکاتب السمرقندی . رجوع به محمد... شود.<br /></font></div>'),
(179200, 'ظهیری', '<span class=\"hlight\">ظهیری .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (اِخ ) نیشابوری . او راست : سلجوقنامه .<br /></font></div>'),
(179201, 'ظوالع', '<span class=\"hlight\">ظوالع.</span> <font color=\"DarkGreen\"><b>[ ظَ ل ِ ]</font></b> (ع ص، اِ) ج ِ ظالع.<br /></font></div>'),
(179202, 'ظواهر', '<span class=\"hlight\">ظواهر.</span> <font color=\"DarkGreen\"><b>[ ظَ هَِ ]</font></b> (ع ص، اِ) ج ِ ظاهر.<br /></font></div>'),
(179203, 'ظواهر', '<span class=\"hlight\">ظواهر.</span> <font color=\"DarkGreen\"><b>[ ظَ هَِ ]</font></b> (اِخ ) (الَ ...) نام موضعی است . (الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br /></font></div>'),
(179204, 'ظوطل', '<span class=\"hlight\">ظوطل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) موضعی به جنوب بوانات .<br /></font></div>'),
(179205, 'ظوف', '<span class=\"hlight\">ظوف .</span> (ع اِ) اخذه بظوف رقبته و بظاف رقبته ؛ گرفت آن را همه یعنی به پوست گردن وی . <BR><font color=\"Blue\">◄</font> ترکته بظوفها و بظافها؛ گذاشتم آن را تنها.<br /></font></div>'),
(179206, 'ظویلمیة', '<span class=\"hlight\">ظویلمیة.</span> <font color=\"DarkGreen\"><b>[ ظُ وَ ل ِ می ی َ ]</font></b> (اِخ ) از آبهای بنی نمیر است .<br /></font></div>'),
(179207, 'ظی', '<span class=\"hlight\">ظی .</span> <font color=\"DarkGreen\"><b>[ ظَی ی ]</font></b> (ع اِ) انگبین . عسل .<br /></font></div>'),
(179208, 'ظی', '<span class=\"hlight\">ظی .</span> (ع اِ) نام حرف ِ ظاء. ظ.<br /></font></div>'),
(179209, 'ظیان', '<span class=\"hlight\">ظیان .</span> <font color=\"DarkGreen\"><b>[ ظَی ْ یا ]</font></b> (ع اِ) سپرم بیاوانی . (مهذب الاسماء). یاسمین دشتی . یاسمین برّی . یاسمن زرد. یاسمین البر. قلیماطس . و داود ضریر انطاکی در تذکره گوید: ظیان یاسمین بَرّ است و از آن رو آن را بدین نام خوانند که گل او یاسمین است (؟) و آن گیاهی است مایل به زردی با برگهای دقیق ماننده تر چیزی به لبلاب لکن نرمی اورا ندارد و در غیر فصل زمستان باشد و قوت بیخ آن بیست سال باقی ماند و آن گرم و خشک است در چهارم و بیخ ریشه ها که از اخلاط سه گانه تولد کند برکند خاصه مفاصل و نقرس را شرباً و طلاءً و آن را بر عرق النسا ضماد کنند ریش پدید آرد و شفا بخشد و روغن آن و همچنین بیخ آن وقتی که نصف وقیه از آن در یک رطل آب بجوشانند تا نصف آن تبخیر شود شفاء اعظم است در سرفه و ربو و بیماری انتصاب و عسرالنفس و روغن او در فالج و لقوه و زمینگیری مجرب است و در همه ٔ افعال با خربق اسود شریک است تا بدانجا که بعضی گمان برده اند که ظیان عین خربق سیاه است و ظیان سبب کرب و غثیان شود و مصلح آن روغن بادام است و شربت آن یک مثقال است - انتهی .<br />و یاس سفید عبارت از اوست و به لغت اندلس و مغرب عشبةالنار نامند و یربه فوقه . ایزنزو. قلیماطس . و قسم مغربی او مشهور به عشبة است و آن نباتی است شبیه به لبلاب و درهم پیچیده و گل او بسیار خوشبو و قسمی را بر شاخهای او خاری شبیه به خار گل سرخ و گل او از یاسمین بستانی که چنپلی نامند بسیار کوچکتر و بیخش سیاه و باریک و پرشعبه و قوّت بیخ او تا بیست سال باقی است . در چهارم گرم و خشک و سایر اجزای او در سیم و محلل و ملطف و بوییدن گل او جهت صداع و شقیقه و روغن او جهت علل بارده و ربو و سعال مُزمن و فالج و لقوه نافع و طبیخ شاخ و بیخ او که نیم وقیه را در یک رطل آب بجوشانند تا به نصف رسد و با شکر و امثال او بنوشند جهت ضیق النفس و سرفه ٔ کهنه و فالج و استرخای مزمن بی عدیل است و ظاهراً روش خاصی که بالفعل متداول است از اینجا استنباط کرده باشند و حمول او مدر حیض و مُسقط جنین و طبیخ برگ و شاخ او به قدر سه درهم با مثل آن بسفایج و مقل ازرق مسهل قوی سوداوی و کرب است و مضمضه ٔ طبیخ او با سرکه جهت درد دندان نافع و یک مثقال از بیخ او کشنده ٔ بقی و کرب و مغص و در قوت مثل خربق سیاه و مسهل بلغم و سودا و با آب خبازی مقیئی قوی و قدر شربتش تا نیم درهم است و مصلحش روغن بادام وطلای او محرق و مقرّح جلد و بهترین ادویه ٔ برص و جهت عرق النسا و مفاصل و فالج و امثال آن مفید و روغنی که در آن بیخ مذکور را جوشانیده باشند جهت فالج و مانند آن به غایت نافع است . (تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> انگبین . عسل . <BR><font color=\"Blue\">◄</font> گیاهی است که بدان پوست پیرایند.<br /></font></div>'),
(179210, 'ظیة', '<span class=\"hlight\">ظیة.</span> <font color=\"DarkGreen\"><b>[ ظَی ْ ی َ ]</font></b> (ع اِ) مردار در آماس و شکافتگی درآمده . (منتهی الارب ). ْْْ<br /></font></div>'),
(179211, 'ظیقی', '<span class=\"hlight\">ظیقی .</span> <font color=\"DarkGreen\"><b>[ ظَ ]</font></b> (ص نسبی ) منسوب است به ظیقان و هو منزل علی عشرة فراسخ من بریة عیذاب، منها ابوالحسن طاهربن عتیق السکاک الظیقی . (سمعانی ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br /></font></div>');
